# ============================================================
# ALVEX AI CONFIGURATION
# ============================================================

APP_NAME = "ALVEX AI"
APP_VERSION = "1.0.0"
APP_DESCRIPTION = "Independent Artificial Intelligence Platform"

ENVIRONMENT = os.getenv("ENVIRONMENT", "development")
DATABASE_URL = os.getenv("DATABASE_URL", "sqlite:///./alvex.db")

JWT_SECRET = os.getenv("JWT_SECRET")

if not JWT_SECRET:
    if ENVIRONMENT == "production":
        raise RuntimeError("JWT_SECRET must be configured in production.")
    JWT_SECRET = secrets.token_urlsafe(48)

JWT_ALGORITHM = "HS256"
TOKEN_EXPIRE_MINUTES = 60

MAX_MESSAGE_LENGTH = 12000
MAX_USERNAME_LENGTH = 80

logging.basicConfig(
    level=logging.INFO,
    format="%(asctime)s | %(levelname)s | %(message)s"
)

logger = logging.getLogger("ALVEX")


# ============================================================
# DATABASE
# ============================================================

Base = declarative_base()

engine = create_engine(
    DATABASE_URL,
    connect_args=(
        {"check_same_thread": False}
        if DATABASE_URL.startswith("sqlite")
        else {}
    ),
    pool_pre_ping=True
)

SessionLocal = sessionmaker(
    bind=engine,
    autoflush=False,
    autocommit=False
)


class User(Base):

    __tablename__ = "users"

    id = Column(Integer, primary_key=True)

    email = Column(String(254), unique=True, index=True)

    username = Column(String(80), nullable=True)

    password_hash = Column(String(255))

    is_admin = Column(Boolean, default=False)

    is_active = Column(Boolean, default=True)

    is_verified = Column(Boolean, default=False)

    plan = Column(String(30), default="free")

    created_at = Column(
        DateTime(timezone=True),
        default=lambda: datetime.now(timezone.utc)
    )

    conversations = relationship(
        "Conversation",
        back_populates="user",
        cascade="all, delete-orphan"
    )


class Conversation(Base):

    __tablename__ = "conversations"

    id = Column(Integer, primary_key=True)

    user_id = Column(
        Integer,
        ForeignKey("users.id"),
        index=True
    )

    title = Column(String(160), default="Yeni sohbet")

    created_at = Column(
        DateTime(timezone=True),
        default=lambda: datetime.now(timezone.utc)
    )

    user = relationship(
        "User",
        back_populates="conversations"
    )

    messages = relationship(
        "Message",
        back_populates="conversation",
        cascade="all, delete-orphan"
    )


class Message(Base):

    __tablename__ = "messages"

    id = Column(Integer, primary_key=True)

    conversation_id = Column(
        Integer,
        ForeignKey("conversations.id"),
        index=True
    )

    role = Column(String(20))

    content = Column(Text)

    created_at = Column(
        DateTime(timezone=True),
        default=lambda: datetime.now(timezone.utc)
    )

    conversation = relationship(
        "Conversation",
        back_populates="messages"
    )


class SecurityEvent(Base):

    __tablename__ = "security_events"

    id = Column(Integer, primary_key=True)

    user_id = Column(Integer, nullable=True)

    event_type = Column(String(100))

    description = Column(String(500))

    severity = Column(String(20), default="info")

    created_at = Column(
        DateTime(timezone=True),
        default=lambda: datetime.now(timezone.utc)
    )


class APIUsage(Base):

    __tablename__ = "api_usage"

    id = Column(Integer, primary_key=True)

    user_id = Column(Integer, index=True)

    endpoint = Column(String(255))

    created_at = Column(
        DateTime(timezone=True),
        default=lambda: datetime.now(timezone.utc)
    )


Base.metadata.create_all(bind=engine)


def get_db():

    db = SessionLocal()

    try:
        yield db

    finally:
        db.close()


# ============================================================
# PASSWORD SECURITY
# ============================================================

password_context = CryptContext(
    schemes=["pbkdf2_sha256"],
    deprecated="auto"
)

oauth_scheme = OAuth2PasswordBearer(
    tokenUrl="/api/auth/login"
)


def hash_password(password):

    return password_context.hash(password)


def verify_password(password, hashed):

    return password_context.verify(password, hashed)


# ============================================================
# AUTHENTICATION
# ============================================================

def create_token(user_id):

    expiration = (
        datetime.now(timezone.utc)
        + timedelta(minutes=TOKEN_EXPIRE_MINUTES)
    )

    payload = {
        "sub": str(user_id),
        "exp": expiration,
        "iat": datetime.now(timezone.utc)
    }

    return jwt.encode(
        payload,
        JWT_SECRET,
        algorithm=JWT_ALGORITHM
    )


def get_current_user(
    token: str = Depends(oauth_scheme),
    db: Session = Depends(get_db)
):

    try:

        payload = jwt.decode(
            token,
            JWT_SECRET,
            algorithms=[JWT_ALGORITHM]
        )

        user_id = int(payload["sub"])

    except (JWTError, ValueError, KeyError):

        raise HTTPException(
            status_code=401,
            detail="Invalid authentication token"
        )

    user = db.query(User).filter(
        User.id == user_id
    ).first()

    if not user or not user.is_active:

        raise HTTPException(
            status_code=401,
            detail="Account unavailable"
        )

    return user


def require_admin(
    user: User = Depends(get_current_user)
):

    if not user.is_admin:

        raise HTTPException(
            status_code=403,
            detail="Administrator privileges required"
        )

    return user


