# ============================================================
# PYTORCH LOCAL AI MODEL
# ============================================================

class ALVEXTransformer(nn.Module):

    def __init__(
        self,
        vocab_size=8000,
        embedding_dim=256,
        heads=8,
        layers=4
    ):

        super().__init__()

        self.embedding = nn.Embedding(
            vocab_size,
            embedding_dim
        )

        transformer_layer = nn.TransformerEncoderLayer(
            d_model=embedding_dim,
            nhead=heads,
            batch_first=True
        )

        self.transformer = nn.TransformerEncoder(
            transformer_layer,
            num_layers=layers
        )

        self.output = nn.Linear(
            embedding_dim,
            vocab_size
        )

    def forward(self, tokens):

        x = self.embedding(tokens)

        mask = nn.Transformer.generate_square_subsequent_mask(
            tokens.size(1),
            device=tokens.device
        )

        x = self.transformer(
            x,
            mask=mask,
            is_causal=True
        )

        return self.output(x)


class ALVEXAIEngine:

    def __init__(self):

        self.device = (
            "cuda"
            if torch.cuda.is_available()
            else "cpu"
        )

        self.model = ALVEXTransformer().to(
            self.device
        )

        self.model_ready = False

        self.model_path = os.getenv(
            "ALVEX_MODEL_PATH",
            "checkpoints/alvex.pt"
        )

        self.load_model()

    def load_model(self):

        if not os.path.isfile(self.model_path):

            logger.warning(
                "No trained ALVEX model checkpoint found."
            )

            return

        try:

            state = torch.load(
                self.model_path,
                map_location=self.device,
                weights_only=True
            )

            self.model.load_state_dict(state)

            self.model.eval()

            self.model_ready = True

            logger.info("ALVEX local model loaded.")

        except Exception:

            logger.exception(
                "Model checkpoint could not be loaded."
            )

    def status(self):

        return {
            "model": "ALVEX-LOCAL",
            "ready": self.model_ready,
            "device": self.device,
            "external_api": False
        }

    def respond(self, prompt):

        if not self.model_ready:

            return (
                "ALVEX AI yerel modelinin eğitimi henüz "
                "tamamlanmadı. Model mimarisi hazır, ancak "
                "eğitilmiş ağırlıklar olmadan gerçek bir "
                "AI yanıtı üretilemez."
            )

        return (
            "Model ağırlıkları yüklendi ancak tokenizer "
            "ve metin üretim sistemi henüz etkinleştirilmedi."
        )


ai_engine = ALVEXAIEngine()


# ============================================================
# SECURITY MONITORING
# ============================================================

request_counts = defaultdict(list)

MAX_REQUESTS = 60
WINDOW_SECONDS = 60


def record_security_event(
    db,
    event_type,
    description,
    user_id=None,
    severity="info"
):

    event = SecurityEvent(
        user_id=user_id,
        event_type=event_type,
        description=description[:500],
        severity=severity
    )

    db.add(event)
    db.commit()


def check_rate_limit(identifier):

    now = time.time()

    timestamps = request_counts[identifier]

    request_counts[identifier] = [
        timestamp
        for timestamp in timestamps
        if now - timestamp < WINDOW_SECONDS
    ]

    if len(request_counts[identifier]) >= MAX_REQUESTS:

        return False

    request_counts[identifier].append(now)

    return True


