# ============================================================
# DAILY USAGE MANAGEMENT
# ============================================================

def get_daily_usage(
    db,
    user_id
):

    now = datetime.now(timezone.utc)

    start = now.replace(
        hour=0,
        minute=0,
        second=0,
        microsecond=0
    )

    count = db.query(
        APIUsage
    ).filter(
        APIUsage.user_id == user_id,
        APIUsage.created_at >= start
    ).count()

    return count


def get_plan_limit(plan):

    return PLAN_DAILY_LIMITS.get(
        plan,
        PLAN_DAILY_LIMITS["free"]
    )


def check_user_quota(
    db,
    user
):

    usage = get_daily_usage(
        db,
        user.id
    )

    limit = get_plan_limit(
        user.plan
    )

    return {
        "allowed": usage < limit,
        "used": usage,
        "limit": limit,
        "remaining": max(0, limit - usage)
    }


def enforce_user_quota(
    db,
    user
):

    quota = check_user_quota(
        db,
        user
    )

    if not quota["allowed"]:

        raise HTTPException(
            status_code=429,
            detail={
                "message": "Daily usage limit reached",
                "plan": user.plan,
                "limit": quota["limit"]
            }
        )

    return quota


