# ============================================================
# MESSAGE VALIDATION
# ============================================================

def validate_message_content(content):

    if not isinstance(content, str):

        raise ValueError(
            "Message must be a string"
        )

    content = content.strip()

    if not content:

        raise ValueError(
            "Message cannot be empty"
        )

    if len(content) > MAX_MESSAGE_LENGTH:

        raise ValueError(
            "Message exceeds maximum length"
        )

    return content


def count_message_tokens_approx(content):

    if not content:

        return 0

    return len(content.split())


def calculate_message_statistics(content):

    return {
        "characters": len(content),
        "words": len(content.split()),
        "approximate_tokens": count_message_tokens_approx(
            content
        )
    }


# ============================================================
# LOCAL TOKENIZER FOUNDATION
# ============================================================

class ALVEXTokenizer:

    def __init__(self):

        self.vocabulary = {
            "<PAD>": 0,
            "<UNK>": 1,
            "<BOS>": 2,
            "<EOS>": 3
        }

        self.reverse_vocabulary = {
            value: key
            for key, value in self.vocabulary.items()
        }

        self.next_token_id = 4

    def tokenize(self, text):

        if not isinstance(text, str):

            raise TypeError(
                "Tokenizer input must be text"
            )

        return text.strip().split()

    def add_token(self, token):

        if token not in self.vocabulary:

            token_id = self.next_token_id

            self.vocabulary[token] = token_id

            self.reverse_vocabulary[token_id] = token

            self.next_token_id += 1

    def build_vocabulary(
        self,
        texts
    ):

        for text in texts:

            for token in self.tokenize(text):

                self.add_token(token)

        return len(self.vocabulary)

    def encode(self, text):

        tokens = self.tokenize(text)

        return [
            self.vocabulary.get(
                token,
                self.vocabulary["<UNK>"]
            )
            for token in tokens
        ]

    def decode(self, token_ids):

        tokens = []

        for token_id in token_ids:

            token = self.reverse_vocabulary.get(
                int(token_id),
                "<UNK>"
            )

            if token not in [
                "<PAD>",
                "<BOS>",
                "<EOS>"
            ]:

                tokens.append(token)

        return " ".join(tokens)

    def save(self, path):

        import json

        with open(
            path,
            "w",
            encoding="utf-8"
        ) as file:

            json.dump(
                self.vocabulary,
                file,
                ensure_ascii=False,
                indent=2
            )

    def load(self, path):

        import json

        with open(
            path,
            "r",
            encoding="utf-8"
        ) as file:

            vocabulary = json.load(file)

        self.vocabulary = vocabulary

        self.reverse_vocabulary = {
            int(value): key
            for key, value in vocabulary.items()
        }

        self.next_token_id = (
            max(self.reverse_vocabulary.keys()) + 1
        )

        return True


alvex_tokenizer = ALVEXTokenizer()


# ============================================================
# TRAINING DATASET FOUNDATION
# ============================================================

class ALVEXTextDataset(torch.utils.data.Dataset):

    def __init__(
        self,
        texts,
        tokenizer,
        max_length=256
    ):

        self.texts = texts

        self.tokenizer = tokenizer

        self.max_length = max_length

        self.samples = []

        for text in texts:

            encoded = tokenizer.encode(text)

            if len(encoded) < 2:

                continue

            encoded = encoded[:max_length]

            self.samples.append(encoded)

    def __len__(self):

        return len(self.samples)

    def __getitem__(self, index):

        sample = self.samples[index]

        input_ids = sample[:-1]

        target_ids = sample[1:]

        return (
            torch.tensor(
                input_ids,
                dtype=torch.long
            ),
            torch.tensor(
                target_ids,
                dtype=torch.long
            )
        )


# ============================================================
# MODEL TRAINING CONFIGURATION
# ============================================================

class ALVEXTrainingConfig:

    def __init__(self):

        self.epochs = 3

        self.learning_rate = 0.0001

        self.batch_size = 8

        self.max_length = 256

        self.gradient_clip = 1.0

        self.weight_decay = 0.01

        self.checkpoint_directory = (
            ALVEX_MODEL_DIRECTORY
        )

    def to_dict(self):

        return {
            "epochs": self.epochs,
            "learning_rate": self.learning_rate,
            "batch_size": self.batch_size,
            "max_length": self.max_length,
            "gradient_clip": self.gradient_clip,
            "weight_decay": self.weight_decay
        }


training_config = ALVEXTrainingConfig()


# ============================================================
# TRAINING ENGINE
# ============================================================

class ALVEXTrainingEngine:

    def __init__(
        self,
        model,
        tokenizer,
        config
    ):

        self.model = model

        self.tokenizer = tokenizer

        self.config = config

        self.device = ai_engine.device

        self.history = []

        self.optimizer = torch.optim.AdamW(
            self.model.parameters(),
            lr=config.learning_rate,
            weight_decay=config.weight_decay
        )

        self.loss_function = nn.CrossEntropyLoss()

    def train_epoch(
        self,
        dataloader
    ):

        self.model.train()

        total_loss = 0.0

        total_batches = 0

        for inputs, targets in dataloader:

            inputs = inputs.to(self.device)

            targets = targets.to(self.device)

            self.optimizer.zero_grad()

            outputs = self.model(inputs)

            loss = self.loss_function(
                outputs.reshape(
                    -1,
                    outputs.size(-1)
                ),
                targets.reshape(-1)
            )

            loss.backward()

            torch.nn.utils.clip_grad_norm_(
                self.model.parameters(),
                self.config.gradient_clip
            )

            self.optimizer.step()

            total_loss += loss.item()

            total_batches += 1

        average_loss = (
            total_loss / total_batches
            if total_batches
            else 0.0
        )

        self.history.append(
            average_loss
        )

        return average_loss

    def save_checkpoint(
        self,
        filename="alvex.pt"
    ):

        destination = (
            self.config.checkpoint_directory
            / filename
        )

        torch.save(
            self.model.state_dict(),
            destination
        )

        return str(destination)

    def get_training_history(self):

        return {
            "epochs_completed": len(self.history),
            "loss_history": self.history,
            "device": self.device
        }


