def register_model(
    db,
    name,
    version,
    architecture,
    checkpoint_path
):

    existing = db.query(
        ModelRegistry
    ).filter(
        ModelRegistry.name == name
    ).first()

    if existing:

        existing.version = version

        existing.architecture = architecture

        existing.checkpoint_path = checkpoint_path

    else:

        existing = ModelRegistry(
            name=name,
            version=version,
            architecture=architecture,
            checkpoint_path=checkpoint_path
        )

        db.add(existing)

    db.commit()

    return existing


def list_registered_models(db):

    models = db.query(
        ModelRegistry
    ).order_by(
        ModelRegistry.id.desc()
    ).all()

    return [
        {
            "id": model.id,
            "name": model.name,
            "version": model.version,
            "architecture": model.architecture,
            "active": model.is_active
        }
        for model in models
    ]


