import secrets
import hashlib
from datetime import datetime, timezone
from sqlalchemy import Column, Integer, String, DateTime, Text, ForeignKey
from sqlalchemy.orm import relationship


# ------------------------------------------------------------
# 1. DATABASE MODELS
# ------------------------------------------------------------

class AlvexAPIKey(Base):
    __tablename__ = "alvex_api_keys"

    id = Column(Integer, primary_key=True, index=True)
    user_id = Column(Integer, ForeignKey("users.id"), nullable=False, index=True)

    name = Column(String(100), nullable=False)
    key_prefix = Column(String(20), nullable=False)
    key_hash = Column(String(64), nullable=False, unique=True, index=True)

    created_at = Column(DateTime, default=datetime.utcnow)
    last_used_at = Column(DateTime, nullable=True)
    revoked_at = Column(DateTime, nullable=True)


class AlvexAuditLog(Base):
    __tablename__ = "alvex_audit_logs"

    id = Column(Integer, primary_key=True, index=True)
    user_id = Column(Integer, nullable=True, index=True)

    action = Column(String(100), nullable=False)
    details = Column(Text, nullable=True)
    ip_address = Column(String(64), nullable=True)

    created_at = Column(DateTime, default=datetime.utcnow, index=True)


# Create tables after all model classes are declared.
Base.metadata.create_all(bind=engine)


# ------------------------------------------------------------
# 2. SECURITY HELPERS
# ------------------------------------------------------------

def alvex_hash_api_key(raw_key: str) -> str:
    return hashlib.sha256(raw_key.encode("utf-8")).hexdigest()


def alvex_create_audit_log(
    db,
    action: str,
    user_id=None,
    details=None,
    ip_address=None
):
    entry = AlvexAuditLog(
        user_id=user_id,
        action=action,
        details=details,
        ip_address=ip_address
    )

    db.add(entry)
    db.commit()

    return entry


def alvex_require_admin(user):
    is_admin = (
        getattr(user, "is_admin", False)
        or getattr(user, "role", "") == "admin"
    )

    if not is_admin:
        raise HTTPException(
            status_code=403,
            detail="Administrator privileges required."
        )


# ------------------------------------------------------------
# 3. API KEY SCHEMAS
# ------------------------------------------------------------

class APIKeyCreateRequest(BaseModel):
    name: str = Field(
        min_length=2,
        max_length=100,
        description="A name for your API key"
    )


# ------------------------------------------------------------
# 4. CREATE API KEY
# ------------------------------------------------------------

@app.post("/api/keys")
def create_api_key(
    data: APIKeyCreateRequest,
    request: Request,
    db: Session = Depends(get_db),
    user=Depends(get_current_user)
):
    raw_key = "alvex_" + secrets.token_urlsafe(32)
    key_hash = alvex_hash_api_key(raw_key)

    key_record = AlvexAPIKey(
        user_id=user.id,
        name=data.name,
        key_prefix=raw_key[:12],
        key_hash=key_hash
    )

    db.add(key_record)
    db.commit()
    db.refresh(key_record)

    alvex_create_audit_log(
        db=db,
        action="api_key_created",
        user_id=user.id,
        details=f"API key created: {data.name}",
        ip_address=request.client.host if request.client else None
    )

    # The complete key is displayed only once.
    return {
        "success": True,
        "message": "Store this key securely. It will not be shown again.",
        "api_key": raw_key,
        "key_id": key_record.id,
        "name": key_record.name
    }


