# ------------------------------------------------------------

@app.get("/api/keys")
def list_api_keys(
    db: Session = Depends(get_db),
    user=Depends(get_current_user)
):
    keys = (
        db.query(AlvexAPIKey)
        .filter(AlvexAPIKey.user_id == user.id)
        .order_by(AlvexAPIKey.created_at.desc())
        .all()
    )

    return {
        "total": len(keys),
        "keys": [
            {
                "id": item.id,
                "name": item.name,
                "prefix": item.key_prefix,
                "created_at": item.created_at,
                "last_used_at": item.last_used_at,
                "revoked": item.revoked_at is not None
            }
            for item in keys
        ]
    }


# ------------------------------------------------------------
# 6. REVOKE API KEY
# ------------------------------------------------------------

@app.delete("/api/keys/{key_id}")
def revoke_api_key(
    key_id: int,
    request: Request,
    db: Session = Depends(get_db),
    user=Depends(get_current_user)
):
    key_record = (
        db.query(AlvexAPIKey)
        .filter(
            AlvexAPIKey.id == key_id,
            AlvexAPIKey.user_id == user.id
        )
        .first()
    )

    if not key_record:
        raise HTTPException(
            status_code=404,
            detail="API key not found."
        )

    if key_record.revoked_at is not None:
        raise HTTPException(
            status_code=400,
            detail="This API key has already been revoked."
        )

    key_record.revoked_at = datetime.utcnow()
    db.commit()

    alvex_create_audit_log(
        db=db,
        action="api_key_revoked",
        user_id=user.id,
        details=f"API key {key_id} revoked",
        ip_address=request.client.host if request.client else None
    )

    return {
        "success": True,
        "message": "API key revoked."
    }


