import time
from collections import defaultdict
from threading import Lock
from datetime import datetime, timedelta, timezone

from fastapi import Header
from sqlalchemy import func


# ------------------------------------------------------------
# 1. API USAGE DATABASE MODEL
# ------------------------------------------------------------

class AlvexAPIRequestLog(Base):
    __tablename__ = "alvex_api_request_logs"

    id = Column(Integer, primary_key=True, index=True)
    user_id = Column(Integer, nullable=False, index=True)

    endpoint = Column(String(200), nullable=False)
    status_code = Column(Integer, nullable=False)
    duration_ms = Column(Integer, nullable=False, default=0)

    created_at = Column(DateTime, default=datetime.utcnow, index=True)


Base.metadata.create_all(bind=engine)


# ------------------------------------------------------------
# 2. API KEY AUTHENTICATION
# ------------------------------------------------------------

def alvex_get_api_key_record(raw_key: str, db):
    if not raw_key or not raw_key.startswith("alvex_"):
        return None

    key_hash = alvex_hash_api_key(raw_key)

    record = (
        db.query(AlvexAPIKey)
        .filter(
            AlvexAPIKey.key_hash == key_hash,
            AlvexAPIKey.revoked_at.is_(None)
        )
        .first()
    )

    return record


def alvex_authenticate_api_key(
    raw_key: str,
    db
):
    record = alvex_get_api_key_record(raw_key, db)

    if not record:
        raise HTTPException(
            status_code=401,
            detail="Invalid or revoked API key."
        )

    record.last_used_at = datetime.utcnow()
    db.commit()

    return record


# ------------------------------------------------------------
# 3. API USAGE LIMITS
# ------------------------------------------------------------

ALVEX_PLAN_LIMITS = {
    "free": {
        "requests_per_day": 100,
        "requests_per_minute": 10
    },
    "plus": {
        "requests_per_day": 1000,
        "requests_per_minute": 60
    },
    "pro": {
        "requests_per_day": 5000,
        "requests_per_minute": 120
    },
    "business": {
        "requests_per_day": 20000,
        "requests_per_minute": 300
    }
}


def alvex_get_user_plan(user):
    plan = getattr(user, "plan", "free")

    if not isinstance(plan, str):
        return "free"

    plan = plan.lower()

    if plan not in ALVEX_PLAN_LIMITS:
        return "free"

    return plan


def alvex_check_daily_limit(user, db):
    plan = alvex_get_user_plan(user)
    limit = ALVEX_PLAN_LIMITS[plan]["requests_per_day"]

    start_of_day = datetime.utcnow().replace(
        hour=0,
        minute=0,
        second=0,
        microsecond=0
    )

    used = (
        db.query(AlvexAPIRequestLog)
        .filter(
            AlvexAPIRequestLog.user_id == user.id,
            AlvexAPIRequestLog.created_at >= start_of_day
        )
        .count()
    )

    if used >= limit:
        raise HTTPException(
            status_code=429,
            detail="Daily API request limit reached."
        )

    return {
        "used": used,
        "limit": limit,
        "remaining": max(0, limit - used)
    }


# ------------------------------------------------------------
# 4. API REQUEST TRACKER
# ------------------------------------------------------------

def alvex_record_api_request(
    db,
    user_id,
    endpoint,
    status_code,
    duration_ms
):
    record = AlvexAPIRequestLog(
        user_id=user_id,
        endpoint=endpoint[:200],
        status_code=status_code,
        duration_ms=max(0, int(duration_ms))
    )

    db.add(record)
    db.commit()


# ------------------------------------------------------------
# 5. API KEY DEPENDENCY
# ------------------------------------------------------------

def get_api_key_user(
    authorization: str = Header(default=""),
    db: Session = Depends(get_db)
):
    if not authorization.startswith("Bearer "):
        raise HTTPException(
            status_code=401,
            detail="Bearer API key required."
        )

    raw_key = authorization[7:].strip()

    record = alvex_authenticate_api_key(raw_key, db)

    user = (
        db.query(User)
        .filter(User.id == record.user_id)
        .first()
    )

    if not user:
        raise HTTPException(
            status_code=401,
            detail="API key owner no longer exists."
        )

    return user


