class AlvexModelService:
    def __init__(self):
        self.available = False
        self.model_name = "ALVEX-Transformer"
        self.version = "0.4.0"
        self.last_error = None

    def refresh_status(self):
        try:
            global alvex_ai

            self.available = (
                "alvex_ai" in globals()
                and alvex_ai is not None
                and getattr(alvex_ai, "model_ready", False)
            )

            self.last_error = None

        except Exception as exc:
            self.available = False
            self.last_error = str(exc)

        return self.available

    def status(self):
        self.refresh_status()

        return {
            "name": self.model_name,
            "version": self.version,
            "available": self.available,
            "error": self.last_error
        }


alvex_model_service = AlvexModelService()


@app.get("/api/model/service")
def model_service_status():
    return alvex_model_service.status()


