@app.get("/api/developer/usage")
def developer_usage(
    user=Depends(get_api_key_user),
    db: Session = Depends(get_db)
):
    start_of_day = datetime.utcnow().replace(
        hour=0,
        minute=0,
        second=0,
        microsecond=0
    )

    records = (
        db.query(AlvexAPIRequestLog)
        .filter(
            AlvexAPIRequestLog.user_id == user.id,
            AlvexAPIRequestLog.created_at >= start_of_day
        )
        .all()
    )

    total = len(records)

    average_duration = (
        sum(item.duration_ms for item in records) / total
        if total else 0
    )

    successful = sum(
        1 for item in records
        if 200 <= item.status_code < 400
    )

    return {
        "date": start_of_day.date().isoformat(),
        "total_requests": total,
        "successful_requests": successful,
        "failed_requests": total - successful,
        "average_duration_ms": round(average_duration, 2)
    }


