# ============================================================
# ALVEX AI - PART 5
# DOCUMENT MANAGEMENT / FILE PROCESSING / RAG FOUNDATION
# ============================================================

import os
import uuid
import json
import re
import hashlib
from pathlib import Path
from datetime import datetime

from fastapi import UploadFile, File
from sqlalchemy import Column, Integer, String, DateTime, Text, ForeignKey


# ------------------------------------------------------------
# 1. DOCUMENT STORAGE CONFIGURATION
# ------------------------------------------------------------

ALVEX_STORAGE = Path("storage")
ALVEX_DOCUMENTS = ALVEX_STORAGE / "documents"

ALVEX_STORAGE.mkdir(exist_ok=True)
ALVEX_DOCUMENTS.mkdir(exist_ok=True)

ALVEX_MAX_FILE_SIZE = 5 * 1024 * 1024

ALVEX_ALLOWED_EXTENSIONS = {
    ".txt",
    ".md",
    ".csv",
    ".json"
}


# ------------------------------------------------------------
# 2. DOCUMENT DATABASE MODEL
# ------------------------------------------------------------

class AlvexDocument(Base):
    __tablename__ = "alvex_documents"

    id = Column(Integer, primary_key=True, index=True)

    user_id = Column(
        Integer,
        ForeignKey("users.id"),
        nullable=False,
        index=True
    )

    original_name = Column(String(255), nullable=False)
    stored_name = Column(String(255), nullable=False, unique=True)

    file_extension = Column(String(20), nullable=False)
    file_size = Column(Integer, nullable=False)

    checksum = Column(String(64), nullable=False)

    processing_status = Column(
        String(30),
        default="uploaded"
    )

    created_at = Column(
        DateTime,
        default=datetime.utcnow
    )


class AlvexDocumentChunk(Base):
    __tablename__ = "alvex_document_chunks"

    id = Column(Integer, primary_key=True, index=True)

    document_id = Column(
        Integer,
        ForeignKey("alvex_documents.id"),
        nullable=False,
        index=True
    )

    user_id = Column(Integer, nullable=False, index=True)

    chunk_index = Column(Integer, nullable=False)
    content = Column(Text, nullable=False)

    created_at = Column(
        DateTime,
        default=datetime.utcnow
    )


Base.metadata.create_all(bind=engine)


# ------------------------------------------------------------
# 3. FILE VALIDATION
# ------------------------------------------------------------

def alvex_validate_document(filename, content):
    extension = Path(filename).suffix.lower()

    if extension not in ALVEX_ALLOWED_EXTENSIONS:
        raise HTTPException(
            status_code=400,
            detail="Unsupported file format."
        )

    if not content:
        raise HTTPException(
            status_code=400,
            detail="Empty files are not allowed."
        )

    if len(content) > ALVEX_MAX_FILE_SIZE:
        raise HTTPException(
            status_code=413,
            detail="File exceeds the 5 MB limit."
        )

    return extension


# ------------------------------------------------------------
# 4. DOCUMENT TEXT EXTRACTION
# ------------------------------------------------------------

def alvex_extract_text(extension, content):
    try:
        decoded = content.decode("utf-8-sig")

    except UnicodeDecodeError:
        raise HTTPException(
            status_code=400,
            detail="File must use UTF-8 encoding."
        )

    if extension == ".json":
        try:
            parsed = json.loads(decoded)
            return json.dumps(
                parsed,
                ensure_ascii=False,
                indent=2
            )
        except json.JSONDecodeError:
            raise HTTPException(
                status_code=400,
                detail="Invalid JSON document."
            )

    return decoded


# ------------------------------------------------------------
# 5. TEXT CLEANING
# ------------------------------------------------------------

def alvex_clean_document_text(content):
    content = content.replace("\x00", "")

    content = re.sub(
        r"\r\n?",
        "\n",
        content
    )

    content = re.sub(
        r"[ \t]+",
        " ",
        content
    )

    content = re.sub(
        r"\n{3,}",
        "\n\n",
        content
    )

    return content.strip()


# ------------------------------------------------------------
# 6. TEXT CHUNKING
# ------------------------------------------------------------

def alvex_split_into_chunks(
    content,
    chunk_size=1200,
    overlap=150
):
    if chunk_size <= 0:
        raise ValueError("chunk_size must be positive.")

    if overlap < 0 or overlap >= chunk_size:
        raise ValueError("Invalid overlap value.")

    chunks = []
    start = 0

    while start < len(content):
        end = min(
            start + chunk_size,
            len(content)
        )

        chunk = content[start:end].strip()

        if chunk:
            chunks.append(chunk)

        if end >= len(content):
            break

        start = end - overlap

    return chunks


# ------------------------------------------------------------
# 7. DOCUMENT UPLOAD
# ------------------------------------------------------------

@app.post("/api/documents/upload")
async def upload_document(
    file: UploadFile = File(...),
    db: Session = Depends(get_db),
    user=Depends(get_current_user)
):
    original_name = Path(
        file.filename or "document.txt"
    ).name

    content = await file.read(
        ALVEX_MAX_FILE_SIZE + 1
    )

    extension = alvex_validate_document(
        original_name,
        content
    )

    extracted_text = alvex_extract_text(
        extension,
        content
    )

    extracted_text = alvex_clean_document_text(
        extracted_text
    )

    if not extracted_text:
        raise HTTPException(
            status_code=400,
            detail="Document contains no readable text."
        )

    checksum = hashlib.sha256(
        content
    ).hexdigest()

    stored_name = (
        str(uuid.uuid4())
        + extension
    )

    destination = ALVEX_DOCUMENTS / stored_name

    document = AlvexDocument(
        user_id=user.id,
        original_name=original_name,
        stored_name=stored_name,
        file_extension=extension,
        file_size=len(content),
        checksum=checksum,
        processing_status="processing"
    )

    db.add(document)
    db.commit()
    db.refresh(document)

    try:
        destination.write_bytes(content)

        chunks = alvex_split_into_chunks(
            extracted_text
        )

        for index, chunk in enumerate(chunks):
            db.add(
                AlvexDocumentChunk(
                    document_id=document.id,
                    user_id=user.id,
                    chunk_index=index,
                    content=chunk
                )
            )

        document.processing_status = "processed"

        db.commit()

    except Exception:
        db.rollback()

        destination.unlink(missing_ok=True)

        raise HTTPException(
            status_code=500,
            detail="Document processing failed."
        )

    return {
        "success": True,
        "document_id": document.id,
        "filename": original_name,
        "size": len(content),
        "chunks_created": len(chunks),
        "status": document.processing_status
    }


