# ------------------------------------------------------------
# 9. DELETE DOCUMENT
# ------------------------------------------------------------

@app.delete("/api/documents/{document_id}")
def delete_document(
    document_id: int,
    db: Session = Depends(get_db),
    user=Depends(get_current_user)
):
    document = (
        db.query(AlvexDocument)
        .filter(
            AlvexDocument.id == document_id,
            AlvexDocument.user_id == user.id
        )
        .first()
    )

    if not document:
        raise HTTPException(
            status_code=404,
            detail="Document not found."
        )

    stored_path = (
        ALVEX_DOCUMENTS / document.stored_name
    )

    stored_path.unlink(missing_ok=True)

    db.query(AlvexDocumentChunk).filter(
        AlvexDocumentChunk.document_id == document.id,
        AlvexDocumentChunk.user_id == user.id
    ).delete(synchronize_session=False)

    db.delete(document)
    db.commit()

    return {
        "success": True,
        "message": "Document deleted."
    }


