import re
import json
import uuid
import time
import hashlib

from datetime import datetime
from sqlalchemy import (
    Column,
    Integer,
    String,
    Text,
    DateTime,
    ForeignKey,
    Boolean
)


# ------------------------------------------------------------
# 1. CHAT CONFIGURATION
# ------------------------------------------------------------

ALVEX_CHAT_CONFIG = {
    "version": "1.0.0",
    "max_input_length": 12000,
    "max_context_messages": 20,
    "max_memory_items": 50,
    "max_response_length": 8000,
    "default_temperature": 0.7,
    "default_top_k": 5,
    "enable_memory": True,
    "enable_rag": True,
    "enable_history": True
}


# ------------------------------------------------------------
# 2. CHAT MEMORY DATABASE
# ------------------------------------------------------------

class AlvexChatMemory(Base):
    __tablename__ = "alvex_chat_memories"

