# ------------------------------------------------------------
# 5. INPUT NORMALIZATION
# ------------------------------------------------------------

class AlvexInputProcessor:

    @staticmethod
    def normalize(text):

        if not isinstance(text, str):
            raise ValueError(
                "Input must be a string."
            )

        text = text.replace("\x00", "")

        text = re.sub(
            r"\r\n?",
            "\n",
            text
        )

        return text.strip()

    @staticmethod
    def validate(text):

        if not text:
            raise HTTPException(
                status_code=400,
                detail="Message cannot be empty."
            )

        if len(text) > ALVEX_CHAT_CONFIG[
            "max_input_length"
        ]:
            raise HTTPException(
                status_code=413,
                detail="Message is too long."
            )

        return True


# ------------------------------------------------------------
# 6. CHAT CONTEXT BUILDER
# ------------------------------------------------------------

class AlvexConversationContext:

    def __init__(self, maximum_messages=20):
        self.maximum_messages = maximum_messages

    def build(
        self,
        db,
        user_id,
        conversation_id
    ):

        conversation = (
            db.query(Conversation)
            .filter(
                Conversation.id == conversation_id,
                Conversation.user_id == user_id
            )
            .first()
        )

        if not conversation:
            raise HTTPException(
                status_code=404,
                detail="Conversation not found."
            )

        messages = (
            db.query(Message)
            .filter(
                Message.conversation_id == conversation_id
            )
            .order_by(Message.id.desc())
            .limit(self.maximum_messages)
            .all()
        )

        messages.reverse()

        return [
            {
                "role": message.role,
                "content": message.content
            }
            for message in messages
        ]


alvex_context_builder = AlvexConversationContext(
    ALVEX_CHAT_CONFIG["max_context_messages"]
)


# ------------------------------------------------------------
# 7. MEMORY MANAGER
# ------------------------------------------------------------

class AlvexMemoryManager:

    def save(
        self,
        db,
        user_id,
        memory_key,
        memory_value,
        category="general",
        importance=1,
        conversation_id=None
    ):

        memory_key = memory_key.strip()
        memory_value = memory_value.strip()

        if not memory_key or not memory_value:
            raise ValueError(
                "Memory key and value are required."
            )

        if len(memory_key) > 150:
            raise ValueError(
                "Memory key is too long."
            )

        if len(memory_value) > 3000:
            raise ValueError(
                "Memory value is too long."
            )

        importance = max(
            1,
            min(int(importance), 5)
        )

        existing = (
            db.query(AlvexChatMemory)
            .filter(
                AlvexChatMemory.user_id == user_id,
                AlvexChatMemory.memory_key == memory_key,
                AlvexChatMemory.is_active == True
            )
            .first()
        )

        if existing:

            existing.memory_value = memory_value
            existing.category = category
            existing.importance = importance
            existing.updated_at = datetime.utcnow()

            db.commit()

            return existing

        memory = AlvexChatMemory(
            user_id=user_id,
            conversation_id=conversation_id,
            memory_key=memory_key,
            memory_value=memory_value,
            category=category,
            importance=importance
        )

        db.add(memory)
        db.commit()
        db.refresh(memory)

        return memory

    def get_memories(
        self,
        db,
        user_id,
        limit=50
    ):

        return (
            db.query(AlvexChatMemory)
            .filter(
                AlvexChatMemory.user_id == user_id,
                AlvexChatMemory.is_active == True
            )
            .order_by(
                AlvexChatMemory.importance.desc(),
                AlvexChatMemory.updated_at.desc()
            )
            .limit(limit)
            .all()
        )

    def delete_memory(
        self,
        db,
        user_id,
        memory_id
    ):

        memory = (
            db.query(AlvexChatMemory)
            .filter(
                AlvexChatMemory.id == memory_id,
                AlvexChatMemory.user_id == user_id
            )
            .first()
        )

        if not memory:
            return False

        db.delete(memory)
        db.commit()

        return True

    def clear_memories(
        self,
        db,
        user_id
    ):

        deleted = (
            db.query(AlvexChatMemory)
            .filter(
                AlvexChatMemory.user_id == user_id
            )
            .delete(synchronize_session=False)
        )

        db.commit()

        return deleted


alvex_memory_manager = AlvexMemoryManager()


# ------------------------------------------------------------
# 8. MEMORY CONTEXT GENERATOR
# ------------------------------------------------------------

def alvex_build_memory_context(
    db,
    user_id
):

    memories = (
        alvex_memory_manager.get_memories(
            db,
            user_id,
            limit=ALVEX_CHAT_CONFIG[
                "max_memory_items"
            ]
        )
    )

    if not memories:
        return ""

    parts = []

    for memory in memories:

        parts.append(
            memory.memory_key
            + ": "
            + memory.memory_value
        )

    return "\n".join(parts)


# ------------------------------------------------------------
# 9. RESPONSE STRUCTURE
# ------------------------------------------------------------

class AlvexResponse:

    def __init__(
        self,
        content,
        model="ALVEX",
        sources=None,
        metadata=None
    ):

        self.content = content
        self.model = model
        self.sources = sources or []
        self.metadata = metadata or {}

        self.created_at = datetime.utcnow()

    def to_dict(self):

        return {
            "content": self.content,
            "model": self.model,
            "sources": self.sources,
            "metadata": self.metadata,
            "created_at": self.created_at.isoformat()
        }


# ------------------------------------------------------------
# 10. RESPONSE ORCHESTRATOR
# ------------------------------------------------------------

class AlvexResponseOrchestrator:

    def __init__(
        self,
        context_builder,
        memory_manager,
        rag_builder
    ):

        self.context_builder = context_builder
        self.memory_manager = memory_manager
        self.rag_builder = rag_builder

    def prepare(
        self,
        db,
        user_id,
        conversation_id,
        message
    ):

        history = self.context_builder.build(
            db,
            user_id,
            conversation_id
        )

        memory = alvex_build_memory_context(
            db,
            user_id
        )

        rag_result = {
            "context": "",
            "sources": []
        }

        if ALVEX_CHAT_CONFIG["enable_rag"]:

            rag_result = self.rag_builder.build(
                db,
                user_id,
                message,
                top_k=5
            )

        return {
            "history": history,
            "memory": memory,
            "document_context": rag_result["context"],
            "sources": rag_result["sources"]
        }


alvex_orchestrator = AlvexResponseOrchestrator(
    alvex_context_builder,
    alvex_memory_manager,
    alvex_rag_context_builder
)


# ------------------------------------------------------------
# 11. SESSION MANAGER
# ------------------------------------------------------------

class AlvexSessionManager:

    def create(
        self,
        db,
        user_id,
        title="New session"
    ):

        token = secrets.token_urlsafe(32)

        session = AlvexChatSession(
            user_id=user_id,
            session_token=token,
            title=title[:200]
        )

        db.add(session)
        db.commit()
        db.refresh(session)

        return session

    def get(
        self,
        db,
        user_id,
        session_id
    ):

        return (
            db.query(AlvexChatSession)
            .filter(
                AlvexChatSession.id == session_id,
                AlvexChatSession.user_id == user_id,
                AlvexChatSession.status == "active"
            )
            .first()
        )

    def update_activity(
        self,
        db,
        session
    ):

        session.last_activity = datetime.utcnow()

        db.commit()

    def close(
        self,
        db,
        user_id,
        session_id
    ):

        session = self.get(
            db,
            user_id,
            session_id
        )

        if not session:
            return False

        session.status = "closed"

        db.commit()

        return True


alvex_session_manager = AlvexSessionManager()


