@app.post("/api/chat/sessions")
def create_chat_session(
    data: dict,
    db: Session = Depends(get_db),
    user=Depends(get_current_user)
):

    title = str(
        data.get("title", "New session")
    )

    session = alvex_session_manager.create(
        db,
        user.id,
        title
    )

    return {
        "id": session.id,
        "title": session.title,
        "status": session.status,
        "created_at": session.created_at
    }


@app.get("/api/chat/sessions")
def list_chat_sessions(
    db: Session = Depends(get_db),
    user=Depends(get_current_user)
):

    sessions = (
        db.query(AlvexChatSession)
        .filter(
            AlvexChatSession.user_id == user.id
        )
        .order_by(
            AlvexChatSession.last_activity.desc()
        )
        .limit(100)
        .all()
    )

    return {
        "total": len(sessions),
        "sessions": [
            {
                "id": item.id,
                "title": item.title,
                "status": item.status,
                "last_activity": item.last_activity
            }
            for item in sessions
        ]
    }


@app.delete("/api/chat/sessions/{session_id}")
def close_chat_session(
    session_id: int,
    db: Session = Depends(get_db),
    user=Depends(get_current_user)
):

    success = alvex_session_manager.close(
        db,
        user.id,
        session_id
    )

    if not success:
        raise HTTPException(
            status_code=404,
            detail="Session not found."
        )

    return {
        "success": True,
        "message": "Session closed."
    }


