class AlvexFeedbackRequest(BaseModel):

    message_id: int

    rating: int = Field(
        ge=1,
        le=5
    )

    comment: Optional[str] = Field(
        default=None,
        max_length=2000
    )


@app.post("/api/chat/feedback")
def submit_chat_feedback(
    data: AlvexFeedbackRequest,
    db: Session = Depends(get_db),
    user=Depends(get_current_user)
):

    message = (
        db.query(Message)
        .join(
            Conversation,
            Message.conversation_id == Conversation.id
        )
        .filter(
            Message.id == data.message_id,
            Conversation.user_id == user.id
        )
        .first()
    )

    if not message:
        raise HTTPException(
            status_code=404,
            detail="Message not found."
        )

    feedback = AlvexChatFeedback(
        user_id=user.id,
        message_id=data.message_id,
        rating=data.rating,
        comment=data.comment
    )

    db.add(feedback)
    db.commit()

    return {
        "success": True,
        "feedback_id": feedback.id
    }


