# ------------------------------------------------------------
# 3. STANDARD MODEL REQUEST
# ------------------------------------------------------------

class AlvexLLMRequest(BaseModel):

    messages: List[Dict[str, str]]

    model: Optional[str] = None

    temperature: float = Field(
        default=0.7,
        ge=0,
        le=2
    )

    max_tokens: int = Field(
        default=2048,
        ge=1,
        le=8192
    )

    stream: bool = False


class AlvexLLMResponse(BaseModel):

    request_id: str

    provider: str

    model: str

    content: str

    duration_ms: int

    success: bool

    error: Optional[str] = None


# ------------------------------------------------------------
# 4. PROVIDER RESULT
# ------------------------------------------------------------

class AlvexProviderResult:

    def __init__(
        self,
        content="",
        model="",
        usage=None,
        finish_reason=None
    ):

        self.content = content

        self.model = model

        self.usage = usage or {}

        self.finish_reason = finish_reason

    def to_dict(self):

        return {
            "content": self.content,
            "model": self.model,
            "usage": self.usage,
            "finish_reason": self.finish_reason
        }


# ------------------------------------------------------------
# 5. PROVIDER INTERFACE
# ------------------------------------------------------------

class AlvexLLMProvider(ABC):

    name = "base"

    @abstractmethod
    async def generate(
        self,
        request: AlvexLLMRequest
    ) -> AlvexProviderResult:

        raise NotImplementedError

    @abstractmethod
    async def health_check(self) -> bool:

        raise NotImplementedError


# ------------------------------------------------------------
# 6. LOCAL OLLAMA PROVIDER
# ------------------------------------------------------------

class AlvexLocalProvider(AlvexLLMProvider):

    name = "local"

    def __init__(
        self,
        base_url=None,
        model=None
    ):

        config = ALVEX_PROVIDER_CONFIG["local"]

        self.base_url = (
            base_url or config["base_url"]
        ).rstrip("/")

        self.model = (
            model or config["model"]
        )

    async def generate(
        self,
        request: AlvexLLMRequest
    ):

        payload = {
            "model": request.model or self.model,
            "messages": request.messages,
            "stream": False,
            "options": {
                "temperature": request.temperature,
                "num_predict": request.max_tokens
            }
        }

        async with httpx.AsyncClient(
            timeout=ALVEX_LLM_CONFIG[
                "request_timeout"
            ]
        ) as client:

            response = await client.post(
                self.base_url + "/api/chat",
                json=payload
            )

            response.raise_for_status()

            data = response.json()

        message = data.get("message", {})

        return AlvexProviderResult(
            content=message.get("content", ""),
            model=data.get("model", self.model),
            usage={
                "input_tokens": data.get(
                    "prompt_eval_count",
                    0
                ),
                "output_tokens": data.get(
                    "eval_count",
                    0
                )
            },
            finish_reason=data.get("done_reason")
        )

    async def health_check(self):

        try:

            async with httpx.AsyncClient(
                timeout=5
            ) as client:

                response = await client.get(
                    self.base_url + "/api/tags"
                )

                return response.status_code == 200

        except Exception:

            return False


# ------------------------------------------------------------
# 7. OPENAI-COMPATIBLE PROVIDER
# ------------------------------------------------------------

class AlvexOpenAICompatibleProvider(
    AlvexLLMProvider
):

    name = "openai_compatible"

    def __init__(
        self,
        base_url=None,
        api_key=None,
        model=None
    ):

        config = ALVEX_PROVIDER_CONFIG[
            "openai_compatible"
        ]

        self.base_url = (
            base_url or config["base_url"]
        ).rstrip("/")

        self.api_key = (
            api_key or config["api_key"]
        )

        self.model = (
            model or config["model"]
        )

    async def generate(
        self,
        request: AlvexLLMRequest
    ):

        if not self.base_url or not self.api_key:

            raise RuntimeError(
                "Provider credentials are not configured."
            )

        payload = {
            "model": request.model or self.model,
            "messages": request.messages,
            "temperature": request.temperature,
            "max_tokens": request.max_tokens,
            "stream": False
        }

        headers = {
            "Authorization": (
                "Bearer " + self.api_key
            ),
            "Content-Type": "application/json"
        }

        async with httpx.AsyncClient(
            timeout=ALVEX_LLM_CONFIG[
                "request_timeout"
            ]
        ) as client:

            response = await client.post(
                self.base_url + "/chat/completions",
                json=payload,
                headers=headers
            )

            response.raise_for_status()

            data = response.json()

        choices = data.get("choices", [])

        if not choices:

            raise RuntimeError(
                "Provider returned no completion."
            )

        message = choices[0].get(
            "message",
            {}
        )

        return AlvexProviderResult(
            content=message.get("content", ""),
            model=data.get("model", self.model),
            usage=data.get("usage", {}),
            finish_reason=choices[0].get(
                "finish_reason"
            )
        )

    async def health_check(self):

        if not self.base_url or not self.api_key:
            return False

        headers = {
            "Authorization": (
                "Bearer " + self.api_key
            )
        }

        try:

            async with httpx.AsyncClient(
                timeout=5
            ) as client:

                response = await client.get(
                    self.base_url + "/models",
                    headers=headers
                )

                return response.status_code == 200

        except Exception:

            return False


# ------------------------------------------------------------
# 8. PROVIDER REGISTRY
# ------------------------------------------------------------

class AlvexProviderRegistry:

    def __init__(self):

        self.providers = {}

    def register(
        self,
        provider: AlvexLLMProvider
    ):

        if not isinstance(
            provider,
            AlvexLLMProvider
        ):

            raise TypeError(
                "Provider must implement AlvexLLMProvider."
            )

        self.providers[provider.name] = provider

    def get(self, name):

        provider = self.providers.get(name)

        if provider is None:

            raise ValueError(
                "Unknown provider: " + name
            )

        return provider

    def list_providers(self):

        return list(
            self.providers.keys()
        )


alvex_provider_registry = (
    AlvexProviderRegistry()
)

alvex_provider_registry.register(
    AlvexLocalProvider()
)

if ALVEX_PROVIDER_CONFIG[
    "openai_compatible"
]["enabled"]:

    alvex_provider_registry.register(
        AlvexOpenAICompatibleProvider()
    )


# ------------------------------------------------------------
# 9. PROVIDER HEALTH MONITOR
# ------------------------------------------------------------

class AlvexProviderHealthMonitor:

    def __init__(self, registry):

        self.registry = registry

        self.last_results = {}

    async def check_all(self):

        results = {}

        for name in self.registry.list_providers():

            provider = self.registry.get(name)

            try:

                healthy = await provider.health_check()

            except Exception:

                healthy = False

            results[name] = {
                "healthy": healthy,
                "checked_at": datetime.utcnow().isoformat()
            }

        self.last_results = results

        return results

    def get_last_results(self):

        return self.last_results


alvex_health_monitor = (
    AlvexProviderHealthMonitor(
        alvex_provider_registry
    )
)


# ------------------------------------------------------------
# 10. MODEL ROUTER
# ------------------------------------------------------------

class AlvexModelRouter:

    def __init__(self, registry):

        self.registry = registry

        self.default_provider = (
            ALVEX_LLM_CONFIG["default_provider"]
        )

    def select_provider(self, requested=None):

        provider_name = (
            requested or self.default_provider
        )

        return self.registry.get(
            provider_name
        )

    async def generate(
        self,
        request,
        provider_name=None
    ):

        provider = self.select_provider(
            provider_name
        )

        start = time.perf_counter()

        result = await provider.generate(
            request
        )

        duration = int(
            (time.perf_counter() - start) * 1000
        )

        return {
            "provider": provider.name,
            "result": result,
            "duration_ms": duration
        }


alvex_model_router = AlvexModelRouter(
    alvex_provider_registry
)


# ------------------------------------------------------------
# 11. MODEL REQUEST LOGGER
# ------------------------------------------------------------

def alvex_log_model_request(
    db,
    request_id,
    user_id,
    provider,
    model,
    status,
    duration_ms,
    input_tokens=0,
    output_tokens=0,
    error_message=None
):

    record = AlvexModelRequestLog(
        request_id=request_id,
        user_id=user_id,
        provider=provider,
        model=model,
        status=status,
        duration_ms=duration_ms,
        input_tokens=input_tokens,
        output_tokens=output_tokens,
        error_message=error_message
    )

    db.add(record)
    db.commit()


# ------------------------------------------------------------
# 12. AI GATEWAY
# ------------------------------------------------------------

class AlvexAIGateway:

    def __init__(self, router):

        self.router = router

    async def execute(
        self,
        request,
        user_id=None,
        provider_name=None,
        db=None
    ):

        request_id = str(uuid.uuid4())

        start = time.perf_counter()

        provider_used = (
            provider_name
            or ALVEX_LLM_CONFIG[
                "default_provider"
            ]
        )

        try:

            output = await self.router.generate(
                request,
                provider_name=provider_name
            )

            duration = int(
                (time.perf_counter() - start) * 1000
            )

            result = output["result"]

            if db is not None:

                alvex_log_model_request(
                    db=db,
                    request_id=request_id,
                    user_id=user_id,
                    provider=output["provider"],
                    model=result.model,
                    status="success",
                    duration_ms=duration,
                    input_tokens=result.usage.get(
                        "prompt_tokens",
                        result.usage.get(
                            "input_tokens",
                            0
                        )
                    ),
                    output_tokens=result.usage.get(
                        "completion_tokens",
                        result.usage.get(
                            "output_tokens",
                            0
                        )
                    )
                )

            return AlvexLLMResponse(
                request_id=request_id,
                provider=output["provider"],
                model=result.model,
                content=result.content,
                duration_ms=duration,
                success=True
            )

        except Exception as exc:

            duration = int(
                (time.perf_counter() - start) * 1000
            )

            if db is not None:

                try:

                    alvex_log_model_request(
                        db=db,
                        request_id=request_id,
                        user_id=user_id,
                        provider=provider_used,
                        model=request.model or "unknown",
                        status="error",
                        duration_ms=duration,
                        error_message=(
                            type(exc).__name__
                        )
                    )

                except Exception:

                    db.rollback()

            return AlvexLLMResponse(
                request_id=request_id,
                provider=provider_used,
                model=request.model or "unknown",
                content="",
                duration_ms=duration,
                success=False,
                error="AI provider request failed."
            )


alvex_ai_gateway = AlvexAIGateway(
    alvex_model_router
)


# ------------------------------------------------------------
# 13. MODEL GENERATION API
# ------------------------------------------------------------

@app.post("/api/ai/generate")
async def alvex_generate_endpoint(
    data: AlvexLLMRequest,
    db: Session = Depends(get_db),
    user=Depends(get_current_user)
):

    if len(data.messages) > 50:

        raise HTTPException(
            status_code=400,
            detail="Too many messages."
        )

    for message in data.messages:

        if not isinstance(message, dict):

            raise HTTPException(
                status_code=400,
                detail="Invalid message format."
            )

        if message.get("role") not in {
            "system",
            "user",
            "assistant"
        }:

            raise HTTPException(
                status_code=400,
                detail="Invalid message role."
            )

        if not isinstance(
            message.get("content"),
            str
        ):

            raise HTTPException(
                status_code=400,
                detail="Message content must be text."
            )

        if len(message["content"]) > 12000:

            raise HTTPException(
                status_code=413,
                detail="Message is too long."
            )

    if not data.messages:

        raise HTTPException(
            status_code=400,
            detail="At least one message is required."
        )

    response = await alvex_ai_gateway.execute(
        request=data,
        user_id=user.id,
        db=db
    )

    if not response.success:

        raise HTTPException(
            status_code=503,
            detail=response.error
        )

    return response.to_dict()


