# ------------------------------------------------------------
# 5. TOOL RESULT
# ------------------------------------------------------------

class AlvexToolResult:

    def __init__(
        self,
        success,
        data=None,
        error=None
    ):

        self.success = success
        self.data = data
        self.error = error

    def to_dict(self):

        return {
            "success": self.success,
            "data": self.data,
            "error": self.error
        }


# ------------------------------------------------------------
# 6. BASE TOOL INTERFACE
# ------------------------------------------------------------

class AlvexTool(ABC):

    name = "base_tool"

    description = "Base ALVEX tool"

    requires_confirmation = False

    @abstractmethod
    async def execute(
        self,
        arguments: Dict[str, Any],
        context: Dict[str, Any]
    ) -> AlvexToolResult:

        raise NotImplementedError

    def schema(self):

        return {
            "name": self.name,
            "description": self.description,
            "requires_confirmation": (
                self.requires_confirmation
            )
        }


# ------------------------------------------------------------
# 7. TOOL REGISTRY
# ------------------------------------------------------------

class AlvexToolRegistry:

    def __init__(self):

        self.tools = {}

    def register(self, tool):

        if not isinstance(tool, AlvexTool):

            raise TypeError(
                "Tool must inherit from AlvexTool."
            )

        if tool.name in self.tools:

            raise ValueError(
                "Tool already registered."
            )

        self.tools[tool.name] = tool

    def get(self, name):

        if name not in self.tools:

            raise ValueError(
                "Unknown tool."
            )

        return self.tools[name]

    def list_tools(self):

        return [
            tool.schema()
            for tool in self.tools.values()
        ]

    def remove(self, name):

        if name not in self.tools:
            return False

        del self.tools[name]

        return True


alvex_tool_registry = AlvexToolRegistry()


# ------------------------------------------------------------
# 8. SAFE CALCULATOR TOOL
# ------------------------------------------------------------

class AlvexCalculatorTool(AlvexTool):

    name = "calculator"

    description = (
        "Performs basic arithmetic calculations."
    )

    requires_confirmation = False

    async def execute(
        self,
        arguments,
        context
    ):

        operation = arguments.get("operation")

        a = arguments.get("a")
        b = arguments.get("b")

        if not isinstance(a, (int, float)):
            return AlvexToolResult(
                False,
                error="Invalid first number."
            )

        if not isinstance(b, (int, float)):
            return AlvexToolResult(
                False,
                error="Invalid second number."
            )

        if not math.isfinite(float(a)) or not math.isfinite(float(b)):
            return AlvexToolResult(
                False,
                error="Numbers must be finite."
            )

        operations = {
            "add": lambda: a + b,
            "subtract": lambda: a - b,
            "multiply": lambda: a * b,
            "divide": lambda: a / b if b != 0 else None
        }

        if operation not in operations:

            return AlvexToolResult(
                False,
                error="Unsupported operation."
            )

        if operation == "divide" and b == 0:

            return AlvexToolResult(
                False,
                error="Division by zero is not allowed."
            )

        return AlvexToolResult(
            True,
            data={
                "operation": operation,
                "result": operations[operation]()
            }
        )


# ------------------------------------------------------------
# 9. TEXT ANALYSIS TOOL
# ------------------------------------------------------------

class AlvexTextAnalysisTool(AlvexTool):

    name = "text_analysis"

    description = (
        "Analyzes text length, words and paragraphs."
    )

    async def execute(
        self,
        arguments,
        context
    ):

        content = arguments.get("text", "")

        if not isinstance(content, str):

            return AlvexToolResult(
                False,
                error="Text must be a string."
            )

        if len(content) > 50000:

            return AlvexToolResult(
                False,
                error="Text is too long."
            )

        words = content.split()

        paragraphs = [
            item
            for item in content.split("\n\n")
            if item.strip()
        ]

        return AlvexToolResult(
            True,
            data={
                "characters": len(content),
                "words": len(words),
                "paragraphs": len(paragraphs),
                "lines": len(content.splitlines())
            }
        )


# ------------------------------------------------------------
# 10. DOCUMENT SEARCH TOOL
# ------------------------------------------------------------

class AlvexDocumentSearchTool(AlvexTool):

    name = "document_search"

    description = (
        "Searches the authenticated user's documents."
    )

    async def execute(
        self,
        arguments,
        context
    ):

        db = context.get("db")
        user_id = context.get("user_id")

        query = arguments.get("query", "")

        if db is None or user_id is None:

            return AlvexToolResult(
                False,
                error="Missing execution context."
            )

        results = alvex_retrieve_document_chunks(
            db=db,
            user_id=user_id,
            query=query,
            limit=5
        )

        return AlvexToolResult(
            True,
            data={
                "results": results
            }
        )


