# ------------------------------------------------------------
# 12. TOOL EXECUTION ENGINE
# ------------------------------------------------------------

class AlvexToolExecutor:

    def __init__(self, registry):

        self.registry = registry

        self.execution_count = 0

    async def execute(
        self,
        tool_name,
        arguments,
        context
    ):

        if self.execution_count >= (
            ALVEX_AGENT_CONFIG["max_tool_calls"]
        ):

            return AlvexToolResult(
                False,
                error="Tool execution limit reached."
            )

        tool = self.registry.get(tool_name)

        if not isinstance(arguments, dict):

            return AlvexToolResult(
                False,
                error="Arguments must be an object."
            )

        self.execution_count += 1

        started = time.perf_counter()

        execution_id = str(uuid.uuid4())

        try:

            result = await asyncio.wait_for(
                tool.execute(
                    arguments,
                    context
                ),
                timeout=15
            )

            duration = int(
                (time.perf_counter() - started) * 1000
            )

            return {
                "execution_id": execution_id,
                "tool": tool_name,
                "duration_ms": duration,
                "result": result.to_dict()
            }

        except asyncio.TimeoutError:

            return {
                "execution_id": execution_id,
                "tool": tool_name,
                "result": {
                    "success": False,
                    "error": "Tool execution timed out."
                }
            }

        except Exception as exc:

            logging.exception(
                "ALVEX tool execution failed"
            )

            return {
                "execution_id": execution_id,
                "tool": tool_name,
                "result": {
                    "success": False,
                    "error": "Tool execution failed."
                }
            }


alvex_tool_executor = AlvexToolExecutor(
    alvex_tool_registry
)


# ------------------------------------------------------------
# 13. AGENT TASK MANAGER
# ------------------------------------------------------------

class AlvexTaskManager:

    def create(
        self,
        db,
        user_id,
        title,
        description
    ):

        task = AlvexAgentTask(
            task_id=str(uuid.uuid4()),
            user_id=user_id,
            title=title[:200],
            description=description,
            status="pending"
        )

        db.add(task)
        db.commit()
        db.refresh(task)

        return task

    def get(
        self,
        db,
        user_id,
        task_id
    ):

        return (
            db.query(AlvexAgentTask)
            .filter(
                AlvexAgentTask.task_id == task_id,
                AlvexAgentTask.user_id == user_id
            )
            .first()
        )

    def complete(
        self,
        db,
        task,
        result
    ):

        task.status = "completed"
        task.result = str(result)[:10000]
        task.completed_at = datetime.utcnow()

        db.commit()

        return task

    def fail(
        self,
        db,
        task,
        error
    ):

        task.status = "failed"
        task.error = str(error)[:2000]
        task.completed_at = datetime.utcnow()

        db.commit()

        return task


alvex_task_manager = AlvexTaskManager()


# ------------------------------------------------------------
# 14. AGENT PLANNER
# ------------------------------------------------------------

class AlvexAgentPlanner:

    def create_plan(self, objective):

        objective = str(objective).strip()

        if not objective:

            raise ValueError(
                "Objective cannot be empty."
            )

        return {
            "plan_id": str(uuid.uuid4()),
            "objective": objective,
            "steps": [
                {
                    "step": 1,
                    "name": "understand_request",
                    "description": (
                        "Analyze the user's objective."
                    )
                },
                {
                    "step": 2,
                    "name": "identify_tools",
                    "description": (
                        "Determine which tools are relevant."
                    )
                },
                {
                    "step": 3,
                    "name": "execute_tools",
                    "description": (
                        "Execute permitted tools."
                    )
                },
                {
                    "step": 4,
                    "name": "evaluate_results",
                    "description": (
                        "Evaluate the returned information."
                    )
                },
                {
                    "step": 5,
                    "name": "prepare_response",
                    "description": (
                        "Prepare the final response."
                    )
                }
            ]
        }


alvex_agent_planner = AlvexAgentPlanner()


# ------------------------------------------------------------
# 15. AGENT ENGINE
# ------------------------------------------------------------

class AlvexAgentEngine:

    def __init__(
        self,
        planner,
        executor
    ):

        self.planner = planner
        self.executor = executor

    async def run(
        self,
        objective,
        selected_tools,
        context
    ):

        plan = self.planner.create_plan(
            objective
        )

        results = []

        started = time.perf_counter()

        for tool_call in selected_tools:

            if (
                time.perf_counter() - started
                > ALVEX_AGENT_CONFIG[
                    "max_execution_time"
                ]
            ):

                break

            tool_name = tool_call.get("name")

            arguments = tool_call.get(
                "arguments",
                {}
            )

            if tool_name not in (
                self.executor.registry.tools
            ):

                results.append({
                    "tool": tool_name,
                    "success": False,
                    "error": "Tool not registered."
                })

                continue

            tool = self.executor.registry.get(
                tool_name
            )

            if tool.requires_confirmation:

                results.append({
                    "tool": tool_name,
                    "success": False,
                    "requires_confirmation": True
                })

                continue

            output = await self.executor.execute(
                tool_name,
                arguments,
                context
            )

            results.append(output)

        return {
            "plan": plan,
            "results": results,
            "duration_ms": int(
                (time.perf_counter() - started) * 1000
            )
        }


alvex_agent_engine = AlvexAgentEngine(
    alvex_agent_planner,
    alvex_tool_executor
)


