# ------------------------------------------------------------
# 17. AGENT EXECUTION API
# ------------------------------------------------------------

@app.post("/api/agents/run")
async def alvex_agent_run(
    data: AlvexAgentRequest,
    db: Session = Depends(get_db),
    user=Depends(get_current_user)
):

    if len(data.tools) > 8:

        raise HTTPException(
            status_code=400,
            detail="Too many tool calls."
        )

    context = {
        "user_id": user.id,
        "db": db
    }

    # Use a fresh executor for each request so limits
    # are not shared across different users.
    executor = AlvexToolExecutor(
        alvex_tool_registry
    )

    agent = AlvexAgentEngine(
        alvex_agent_planner,
        executor
    )

    result = await agent.run(
        objective=data.objective,
        selected_tools=data.tools,
        context=context
    )

    return {
        "success": True,
        "result": result
    }


