# ------------------------------------------------------------
# 22. PLUGIN MANAGER
# ------------------------------------------------------------

class AlvexPluginManager:

    def __init__(self):

        self.plugins = {}

    def register(
        self,
        plugin_id,
        name,
        description,
        version="1.0.0"
    ):

        if plugin_id in self.plugins:

            raise ValueError(
                "Plugin already registered."
            )

        self.plugins[plugin_id] = {
            "plugin_id": plugin_id,
            "name": name,
            "description": description,
            "version": version,
            "enabled": False
        }

    def enable(self, plugin_id):

        plugin = self.plugins.get(plugin_id)

        if not plugin:
            return False

        plugin["enabled"] = True

        return True

    def disable(self, plugin_id):

        plugin = self.plugins.get(plugin_id)

        if not plugin:
            return False

        plugin["enabled"] = False

        return True

    def list_plugins(self):

        return list(
            self.plugins.values()
        )


alvex_plugin_manager = AlvexPluginManager()


