class AlvexFactCheckEngine:

    def __init__(self, answer_engine):

        self.answer_engine = answer_engine

    async def check(
        self,
        claim,
        sources,
        user_id,
        db
    ):

        prompt = (
            "Evaluate the following claim using only "
            "the supplied sources.\n\n"
            "CLAIM:\n"
            + claim
            + "\n\n"
            + "Return these sections:\n"
            "Assessment: supported, contradicted, or uncertain.\n"
            "Evidence: summarize relevant evidence.\n"
            "Limitations: explain missing information.\n"
            "Sources: identify source numbers.\n"
            "Do not present uncertainty as certainty."
        )

        return await self.answer_engine.answer(
            query=prompt,
            sources=sources,
            user_id=user_id,
            db=db
        )


alvex_fact_check_engine = (
    AlvexFactCheckEngine(
        alvex_research_answer_engine
    )
)


