# ------------------------------------------------------------
# 22. RESEARCH QUERY NORMALIZER
# ------------------------------------------------------------

class AlvexResearchQueryNormalizer:

    @staticmethod
    def normalize(query):

        if not isinstance(query, str):

            raise ValueError(
                "Query must be a string."
            )

        query = query.strip()

        query = re.sub(
            r"\s+",
            " ",
            query
        )

        query = query.replace("\x00", "")

        return query[:500]

    @staticmethod
    def fingerprint(query):

        normalized = (
            AlvexResearchQueryNormalizer.normalize(
                query
            )
        )

        return hashlib.sha256(
            normalized.lower().encode("utf-8")
        ).hexdigest()


alvex_query_normalizer = (
    AlvexResearchQueryNormalizer()
)


# ------------------------------------------------------------
# 23. RESEARCH QUALITY SCORER
# ------------------------------------------------------------

class AlvexResearchQualityScorer:

    def score(self, sources):

        if not sources:
            return {
                "score": 0,
                "quality": "no_sources"
            }

        scores = []

        for source in sources:

            if isinstance(source, AlvexResearchSource):

                score = source.relevance_score

            else:

                score = source.get("score", 0)

            try:

                score = float(score)

            except (TypeError, ValueError):

                score = 0

            scores.append(
                max(0, min(score, 1))
            )

        average = sum(scores) / len(scores)

        if average >= 0.8:
            quality = "high"

        elif average >= 0.5:
            quality = "medium"

        else:
            quality = "low"

        return {
            "score": round(average, 3),
            "quality": quality,
            "source_count": len(scores)
        }


alvex_research_quality_scorer = (
    AlvexResearchQualityScorer()
)


# ------------------------------------------------------------
# 24. SOURCE DOMAIN SUMMARY
# ------------------------------------------------------------

def alvex_summarize_source_domains(
    sources
):

    domains = {}

    for source in sources:

        if isinstance(source, AlvexResearchSource):

            domain = source.domain

        else:

            domain = urlparse(
                source.get("url", "")
            ).hostname or "unknown"

        domains[domain] = (
            domains.get(domain, 0) + 1
        )

    return [
        {
            "domain": domain,
            "count": count
        }
        for domain, count in sorted(
            domains.items(),
            key=lambda item: item[1],
            reverse=True
        )
    ]


# ------------------------------------------------------------
# 25. RESEARCH QUALITY API
# ------------------------------------------------------------

@app.get("/api/research/{research_id}/quality")
def alvex_research_quality(
    research_id: str,
    db: Session = Depends(get_db),
    user=Depends(get_current_user)
):

    sources = alvex_source_repository.get_sources(
        db,
        user.id,
        research_id
    )

    if not sources:

        raise HTTPException(
            status_code=404,
            detail="Research sources not found."
        )

    quality = alvex_research_quality_scorer.score(
        sources
    )

    return {
        "research_id": research_id,
        "quality": quality,
        "domains": alvex_summarize_source_domains(
            sources
        )
    }


