# ------------------------------------------------------------
# 5. IDENTITY UTILITIES
# ------------------------------------------------------------

class AlvexIdentityUtils:

    @staticmethod
    def hash_identifier(identifier):

        return hashlib.sha256(
            identifier.strip().lower().encode("utf-8")
        ).hexdigest()

    @staticmethod
    def hash_token(token):

        return hashlib.sha256(
            token.encode("utf-8")
        ).hexdigest()

    @staticmethod
    def create_session_id():

        return str(uuid.uuid4())

    @staticmethod
    def safe_string(value, maximum=500):

        if not isinstance(value, str):
            return ""

        return value.replace(
            "\x00",
            ""
        )[:maximum]


alvex_identity_utils = AlvexIdentityUtils()


# ------------------------------------------------------------
# 6. ROLE INITIALIZATION
# ------------------------------------------------------------

class AlvexRoleInitializer:

    def initialize(self, db):

        for role_name, role_data in (
            ALVEX_DEFAULT_ROLES.items()
        ):

            role = (
                db.query(AlvexRole)
                .filter(
                    AlvexRole.name == role_name
                )
                .first()
            )

            if not role:

                role = AlvexRole(
                    name=role_name,
                    description=role_data["description"],
                    is_system_role=True
                )

                db.add(role)

                db.flush()

            for permission_name in (
                role_data["permissions"]
            ):

                permission = (
                    db.query(AlvexPermission)
                    .filter(
                        AlvexPermission.name
                        == permission_name
                    )
                    .first()
                )

                if not permission:

                    permission = AlvexPermission(
                        name=permission_name,
                        description=(
                            "System permission: "
                            + permission_name
                        )
                    )

                    db.add(permission)

                    db.flush()

                existing = (
                    db.query(AlvexRolePermission)
                    .filter(
                        AlvexRolePermission.role_id
                        == role.id,
                        AlvexRolePermission.permission_id
                        == permission.id
                    )
                    .first()
                )

                if not existing:

                    db.add(
                        AlvexRolePermission(
                            role_id=role.id,
                            permission_id=permission.id
                        )
                    )

        db.commit()


alvex_role_initializer = AlvexRoleInitializer()


# ------------------------------------------------------------
# 7. PERMISSION ENGINE
# ------------------------------------------------------------

class AlvexPermissionEngine:

    def get_user_roles(
        self,
        db,
        user_id
    ):

        records = (
            db.query(AlvexRole)
            .join(
                AlvexUserRole,
                AlvexUserRole.role_id == AlvexRole.id
            )
            .filter(
                AlvexUserRole.user_id == user_id
            )
            .all()
        )

        return records

    def get_user_permissions(
        self,
        db,
        user_id
    ):

        rows = (
            db.query(AlvexPermission.name)
            .join(
                AlvexRolePermission,
                AlvexRolePermission.permission_id
                == AlvexPermission.id
            )
            .join(
                AlvexUserRole,
                AlvexUserRole.role_id
                == AlvexRolePermission.role_id
            )
            .filter(
                AlvexUserRole.user_id == user_id
            )
            .distinct()
            .all()
        )

        permissions = {
            row[0]
            for row in rows
        }

        if "*" in permissions:
            return {"*"}

        return permissions

    def has_permission(
        self,
        db,
        user_id,
        permission
    ):

        permissions = self.get_user_permissions(
            db,
            user_id
        )

        return (
            "*",
            permission
        ) in {
            (item, permission)
            for item in permissions
        } or permission in permissions


alvex_permission_engine = AlvexPermissionEngine()


# ------------------------------------------------------------
# 8. PERMISSION DEPENDENCY
# ------------------------------------------------------------

def alvex_require_permission(permission):

    def dependency(
        db: Session = Depends(get_db),
        user=Depends(get_current_user)
    ):

        allowed = (
            alvex_permission_engine.has_permission(
                db,
                user.id,
                permission
            )
        )

        if not allowed:

            raise HTTPException(
                status_code=403,
                detail="Permission denied."
            )

        return user

    return dependency


