# ------------------------------------------------------------
# 4. IP ADDRESS VALIDATOR
# ------------------------------------------------------------

class AlvexIPValidator:

    def validate(self, value):

        if not value:
            return None

        try:

            address = ipaddress.ip_address(value)

            return str(address)

        except ValueError:

            return None

    def hash_ip(self, value):

        if not value:
            return None

        return hashlib.sha256(
            value.encode("utf-8")
        ).hexdigest()


alvex_ip_validator = AlvexIPValidator()


# ------------------------------------------------------------
# 5. SENSITIVE DATA REDACTION
# ------------------------------------------------------------

class AlvexSensitiveDataRedactor:

    PATTERNS = [

        (
            r"(?i)(password|passwd|token|secret)"
            r"\s*[:=]\s*[^,\s]+",
            r"\1=[REDACTED]"
        ),

        (
            r"(?i)bearer\s+[a-z0-9._\-]+",
            "Bearer [REDACTED]"
        ),

        (
            r"[A-Za-z0-9._%+-]+"
            r"@[A-Za-z0-9.-]+\.[A-Za-z]{2,}",
            "[EMAIL REDACTED]"
        )

    ]

    def redact(self, value):

        if not isinstance(value, str):
            return str(value)

        result = value

        for pattern, replacement in self.PATTERNS:

            result = re.sub(
                pattern,
                replacement,
                result
            )

        return result[:2000]


alvex_sensitive_data_redactor = (
    AlvexSensitiveDataRedactor()
)


# ------------------------------------------------------------
# 6. SECURITY INCIDENT MANAGER
# ------------------------------------------------------------

class AlvexSecurityIncidentManager:

    def create(
        self,
        db,
        event_type,
        description,
        severity="low",
        user_id=None,
        source_ip=None,
        metadata=None
    ):

        if event_type not in ALVEX_SECURITY_EVENT_TYPES:

            raise ValueError(
                "Unknown security event type."
            )

        allowed_severities = {
            "info",
            "low",
            "medium",
            "high",
            "critical"
        }

        if severity not in allowed_severities:

            raise ValueError(
                "Invalid severity."
            )

        safe_description = (
            alvex_sensitive_data_redactor.redact(
                description
            )
        )

        safe_metadata = None

        if metadata is not None:

            import json

            safe_metadata = json.dumps(
                metadata,
                ensure_ascii=False,
                default=str
            )[:5000]

        incident = AlvexSecurityIncident(

            incident_id=str(uuid.uuid4()),

            user_id=user_id,

            event_type=event_type,

            severity=severity,

            source_ip=(
                alvex_ip_validator.hash_ip(
                    source_ip
                )
            ),

            description=safe_description,

            event_metadata=safe_metadata

        )

        db.add(incident)

        db.commit()

        db.refresh(incident)

        return incident

    def list_incidents(
        self,
        db,
        limit=100,
        unresolved_only=False
    ):

        query = db.query(
            AlvexSecurityIncident
        )

        if unresolved_only:

            query = query.filter(
                AlvexSecurityIncident.resolved == False
            )

        return (
            query.order_by(
                AlvexSecurityIncident.created_at.desc()
            )
            .limit(limit)
            .all()
        )

    def resolve(
        self,
        db,
        incident_id
    ):

        incident = (
            db.query(AlvexSecurityIncident)
            .filter(
                AlvexSecurityIncident.incident_id
                == incident_id
            )
            .first()
        )

        if not incident:
            return None

        incident.resolved = True

        incident.resolved_at = datetime.utcnow()

        db.commit()

        db.refresh(incident)

        return incident


alvex_security_incident_manager = (
    AlvexSecurityIncidentManager()
)


