# ------------------------------------------------------------
# 8. IP ACTIVITY TRACKER
# ------------------------------------------------------------

class AlvexIPActivityTracker:

    def register_failure(
        self,
        db,
        ip_address
    ):

        ip_hash = alvex_ip_validator.hash_ip(
            ip_address
        )

        if not ip_hash:
            return None

        record = (
            db.query(AlvexSecurityIPRecord)
            .filter(
                AlvexSecurityIPRecord.ip_hash == ip_hash
            )
            .first()
        )

        if not record:

            record = AlvexSecurityIPRecord(
                ip_hash=ip_hash
            )

            db.add(record)

        record.failed_attempts += 1

        record.last_seen = datetime.utcnow()

        if record.failed_attempts >= (
            ALVEX_SECURITY_CENTER_CONFIG[
                "maximum_failed_logins"
            ]
        ):

            record.restricted = True

            record.restriction_reason = (
                "Failed login threshold reached."
            )

        db.commit()

        return record

    def register_suspicious_event(
        self,
        db,
        ip_address
    ):

        ip_hash = alvex_ip_validator.hash_ip(
            ip_address
        )

        if not ip_hash:
            return None

        record = (
            db.query(AlvexSecurityIPRecord)
            .filter(
                AlvexSecurityIPRecord.ip_hash == ip_hash
            )
            .first()
        )

        if not record:

            record = AlvexSecurityIPRecord(
                ip_hash=ip_hash
            )

            db.add(record)

        record.suspicious_events += 1

        record.last_seen = datetime.utcnow()

        db.commit()

        return record

    def is_restricted(
        self,
        db,
        ip_address
    ):

        ip_hash = alvex_ip_validator.hash_ip(
            ip_address
        )

        if not ip_hash:
            return False

        record = (
            db.query(AlvexSecurityIPRecord)
            .filter(
                AlvexSecurityIPRecord.ip_hash == ip_hash
            )
            .first()
        )

        return bool(
            record and record.restricted
        )


alvex_ip_activity_tracker = (
    AlvexIPActivityTracker()
)


# ------------------------------------------------------------
# 9. REQUEST MONITOR
# ------------------------------------------------------------

class AlvexRequestMonitor:

    def __init__(self):

        self.request_history = defaultdict(
            lambda: deque(maxlen=500)
        )

    def register(
        self,
        ip_address,
        path
    ):

        now = time.time()

        self.request_history[ip_address].append({
            "time": now,
            "path": path
        })

        recent = [

            item

            for item in self.request_history[ip_address]

            if now - item["time"] <= 60

        ]

        self.request_history[ip_address] = deque(
            recent,
            maxlen=500
        )

        return len(recent)

    def suspicious(self, request_count):

        return request_count >= (
            ALVEX_SECURITY_CENTER_CONFIG[
                "suspicious_request_threshold"
            ]
        )


alvex_request_monitor = AlvexRequestMonitor()


# ------------------------------------------------------------
# 10. SECURITY MIDDLEWARE
# ------------------------------------------------------------

@app.middleware("http")
async def alvex_security_center_middleware(
    request: Request,
    call_next
):

    if not ALVEX_SECURITY_CENTER_CONFIG["enabled"]:

        return await call_next(request)

    content_length = request.headers.get(
        "content-length"
    )

    if content_length:

        try:

            if int(content_length) > (
                ALVEX_SECURITY_CENTER_CONFIG[
                    "maximum_request_body"
                ]
            ):

                from fastapi.responses import JSONResponse

                return JSONResponse(
                    status_code=413,
                    content={
                        "detail": "Request body too large."
                    }
                )

        except ValueError:

            from fastapi.responses import JSONResponse

            return JSONResponse(
                status_code=400,
                content={
                    "detail": "Invalid content length."
                }
            )

    client_ip = (
        request.client.host
        if request.client
        else "unknown"
    )

    request_count = alvex_request_monitor.register(
        client_ip,
        request.url.path
    )

    if alvex_request_monitor.suspicious(
        request_count
    ):

        from fastapi.responses import JSONResponse

        return JSONResponse(
            status_code=429,
            content={
                "detail": "Request frequency limit reached."
            }
        )

    response = await call_next(request)

    if ALVEX_SECURITY_CENTER_CONFIG[
        "enable_security_headers"
    ]:

        response.headers[
            "X-Content-Type-Options"
        ] = "nosniff"

        response.headers[
            "X-Frame-Options"
        ] = "DENY"

        response.headers[
            "Referrer-Policy"
        ] = "strict-origin-when-cross-origin"

        response.headers[
            "Cache-Control"
        ] = "no-store"

        response.headers[
            "Permissions-Policy"
        ] = "camera=(), microphone=(), geolocation=()"

    return response


