@app.post("/api/admin/security/audit-search")
def alvex_admin_security_audit_search(
    data: AlvexSecurityAuditSearch,
    db: Session = Depends(get_db),
    user=Depends(get_current_user)
):

    alvex_security_admin(user)

    query = db.query(
        AlvexSecurityAuditEntry
    )

    if data.action:

        query = query.filter(
            AlvexSecurityAuditEntry.action == data.action
        )

    if data.result:

        query = query.filter(
            AlvexSecurityAuditEntry.result == data.result
        )

    entries = (
        query.order_by(
            AlvexSecurityAuditEntry.created_at.desc()
        )
        .limit(data.limit)
        .all()
    )

    return {
        "count": len(entries),
        "entries": [
            {
                "audit_id": item.audit_id,
                "user_id": item.user_id,
                "action": item.action,
                "resource": item.resource,
                "result": item.result,
                "created_at": item.created_at
            }
            for item in entries
        ]
    }


