class AlvexPlanService:

    def get_plan(self, plan_name):

        return ALVEX_SUBSCRIPTION_PLANS.get(
            plan_name
        )

    def validate_plan(self, plan_name):

        return plan_name in (
            ALVEX_SUBSCRIPTION_PLANS
        )

    def get_all_plans(self):

        return ALVEX_SUBSCRIPTION_PLANS


alvex_plan_service = AlvexPlanService()


# ------------------------------------------------------------
# 6. SUBSCRIPTION REPOSITORY
# ------------------------------------------------------------

class AlvexSubscriptionRepository:

    def get_active(
        self,
        db,
        user_id
    ):

        return (
            db.query(AlvexSubscription)
            .filter(
                AlvexSubscription.user_id == user_id,
                AlvexSubscription.status == "active"
            )
            .order_by(
                AlvexSubscription.created_at.desc()
            )
            .first()
        )

    def create(
        self,
        db,
        user_id,
        plan,
        duration_days=None
    ):

        existing = self.get_active(
            db,
            user_id
        )

        if existing:

            existing.status = "replaced"

        expires_at = None

        if duration_days:

            expires_at = (
                datetime.utcnow()
                + timedelta(days=duration_days)
            )

        subscription = AlvexSubscription(

            subscription_id=str(uuid.uuid4()),

            user_id=user_id,

            plan=plan,

            status="active",

            expires_at=expires_at

        )

        db.add(subscription)

        db.commit()

        db.refresh(subscription)

        return subscription


alvex_subscription_repository = (
    AlvexSubscriptionRepository()
)


# ------------------------------------------------------------
# 7. SUBSCRIPTION SERVICE
# ------------------------------------------------------------

class AlvexSubscriptionService:

    def get_subscription(
        self,
        db,
        user_id
    ):

        subscription = (
            alvex_subscription_repository.get_active(
                db,
                user_id
            )
        )

        if not subscription:

            return {
                "plan": ALVEX_SUBSCRIPTION_CONFIG[
                    "default_plan"
                ],
                "status": "active",
                "subscription_id": None
            }

        if (
            subscription.expires_at
            and subscription.expires_at <= datetime.utcnow()
        ):

            subscription.status = "expired"

            db.commit()

            return {
                "plan": "free",
                "status": "expired",
                "subscription_id": subscription.subscription_id
            }

        return {
            "plan": subscription.plan,
            "status": subscription.status,
            "subscription_id": subscription.subscription_id,
            "expires_at": subscription.expires_at
        }

    def change_plan(
        self,
        db,
        user_id,
        plan,
        duration_days=None
    ):

        if not alvex_plan_service.validate_plan(
            plan
        ):

            raise ValueError(
                "Invalid subscription plan."
            )

        return alvex_subscription_repository.create(
            db,
            user_id,
            plan,
            duration_days
        )


alvex_subscription_service = (
    AlvexSubscriptionService()
)


