class AlvexUsagePeriodCalculator:

    def daily_key(self):

        return datetime.utcnow().strftime(
            "%Y-%m-%d"
        )

    def monthly_key(self):

        return datetime.utcnow().strftime(
            "%Y-%m"
        )


alvex_usage_period_calculator = (
    AlvexUsagePeriodCalculator()
)


# ------------------------------------------------------------
# 9. USAGE COUNTER SERVICE
# ------------------------------------------------------------

class AlvexUsageCounterService:

    def get_counter(
        self,
        db,
        user_id,
        period_type,
        period_key
    ):

        return (
            db.query(AlvexUsageCounter)
            .filter(
                AlvexUsageCounter.user_id == user_id,
                AlvexUsageCounter.period_type == period_type,
                AlvexUsageCounter.period_key == period_key
            )
            .first()
        )

    def increment(
        self,
        db,
        user_id,
        period_type,
        period_key,
        tokens=0
    ):

        counter = self.get_counter(
            db,
            user_id,
            period_type,
            period_key
        )

        if not counter:

            counter = AlvexUsageCounter(

                user_id=user_id,

                period_type=period_type,

                period_key=period_key,

                request_count=0,

                tokens_used=0

            )

            db.add(counter)

        counter.request_count += 1

        counter.tokens_used += max(
            0,
            int(tokens)
        )

        counter.updated_at = datetime.utcnow()

        db.commit()

        db.refresh(counter)

        return counter


alvex_usage_counter_service = (
    AlvexUsageCounterService()
)


# ------------------------------------------------------------
# 10. QUOTA MANAGER
# ------------------------------------------------------------

class AlvexQuotaManager:

    def check(
        self,
        db,
        user_id
    ):

        subscription = (
            alvex_subscription_service.get_subscription(
                db,
                user_id
            )
        )

        plan_name = subscription["plan"]

        plan = alvex_plan_service.get_plan(
            plan_name
        )

        if not plan:

            raise ValueError(
                "Subscription plan configuration missing."
            )

        daily_counter = (
            alvex_usage_counter_service.get_counter(
                db,
                user_id,
                "daily",
                alvex_usage_period_calculator.daily_key()
            )
        )

        monthly_counter = (
            alvex_usage_counter_service.get_counter(
                db,
                user_id,
                "monthly",
                alvex_usage_period_calculator.monthly_key()
            )
        )

        daily_used = (
            daily_counter.request_count
            if daily_counter
            else 0
        )

        monthly_used = (
            monthly_counter.request_count
            if monthly_counter
            else 0
        )

        daily_limit = plan["daily_requests"]

        monthly_limit = plan["monthly_requests"]

        return {

            "allowed": (
                daily_used < daily_limit
                and monthly_used < monthly_limit
            ),

            "plan": plan_name,

            "daily_used": daily_used,

            "daily_limit": daily_limit,

            "monthly_used": monthly_used,

            "monthly_limit": monthly_limit,

            "daily_remaining": max(
                0,
                daily_limit - daily_used
            ),

            "monthly_remaining": max(
                0,
                monthly_limit - monthly_used
            )

        }

    def consume(
        self,
        db,
        user_id,
        tokens=0
    ):

        quota = self.check(
            db,
            user_id
        )

        if not quota["allowed"]:

            raise HTTPException(
                status_code=429,
                detail={
                    "message": "Usage quota exceeded.",
                    "plan": quota["plan"],
                    "daily_remaining": quota[
                        "daily_remaining"
                    ],
                    "monthly_remaining": quota[
                        "monthly_remaining"
                    ]
                }
            )

        alvex_usage_counter_service.increment(
            db,
            user_id,
            "daily",
            alvex_usage_period_calculator.daily_key(),
            tokens
        )

        alvex_usage_counter_service.increment(
            db,
            user_id,
            "monthly",
            alvex_usage_period_calculator.monthly_key(),
            tokens
        )

        return quota


alvex_quota_manager = AlvexQuotaManager()


