@app.post("/api/subscriptions/change")
def alvex_change_subscription(
    data: AlvexPlanChangeRequest,
    db: Session = Depends(get_db),
    user=Depends(get_current_user)
):

    if not ALVEX_SUBSCRIPTION_CONFIG[
        "allow_plan_changes"
    ]:

        raise HTTPException(
            status_code=403,
            detail="Plan changes are disabled."
        )

    if data.plan != "free":

        raise HTTPException(
            status_code=403,
            detail=(
                "Paid plans require a verified payment "
                "provider transaction."
            )
        )

    try:

        subscription = (
            alvex_subscription_service.change_plan(
                db,
                user.id,
                data.plan
            )
        )

        alvex_billing_event_logger.create(
            db,
            user.id,
            "plan_changed",
            amount=0,
            description="User changed to Free plan."
        )

        return {
            "success": True,
            "subscription_id": subscription.subscription_id,
            "plan": subscription.plan
        }

    except ValueError as exc:

        raise HTTPException(
            status_code=400,
            detail=str(exc)
        )


