@app.get("/api/usage/me")
def alvex_get_my_usage(
    db: Session = Depends(get_db),
    user=Depends(get_current_user)
):

    return alvex_quota_manager.check(
        db,
        user.id
    )


@app.post("/api/usage/query")
def alvex_query_usage(
    data: AlvexUsageQueryRequest,
    db: Session = Depends(get_db),
    user=Depends(get_current_user)
):

    since = (
        datetime.utcnow()
        - timedelta(days=data.days)
    )

    records = (
        db.query(AlvexUsageRecord)
        .filter(
            AlvexUsageRecord.user_id == user.id,
            AlvexUsageRecord.created_at >= since
        )
        .order_by(
            AlvexUsageRecord.created_at.desc()
        )
        .limit(5000)
        .all()
    )

    total_requests = len(records)

    total_tokens = sum(
        item.tokens_used
        for item in records
    )

    average_response_time = (

        sum(
            item.response_time_ms
            for item in records
        ) / total_requests

        if total_requests
        else 0

    )

    return {
        "period_days": data.days,
        "total_requests": total_requests,
        "total_tokens": total_tokens,
        "average_response_time_ms": round(
            average_response_time,
            2
        )
    }


