@app.get("/api/admin/subscriptions")
def alvex_admin_list_subscriptions(
    limit: int = 100,
    db: Session = Depends(get_db),
    user=Depends(get_current_user)
):

    alvex_security_admin(user)

    limit = max(
        1,
        min(limit, 500)
    )

    subscriptions = (
        db.query(AlvexSubscription)
        .order_by(
            AlvexSubscription.created_at.desc()
        )
        .limit(limit)
        .all()
    )

    return {
        "count": len(subscriptions),
        "subscriptions": [
            {
                "subscription_id": item.subscription_id,
                "user_id": item.user_id,
                "plan": item.plan,
                "status": item.status,
                "started_at": item.started_at,
                "expires_at": item.expires_at
            }
            for item in subscriptions
        ]
    }


@app.post("/api/admin/subscriptions/update")
def alvex_admin_update_subscription(
    data: AlvexAdminSubscriptionUpdate,
    db: Session = Depends(get_db),
    user=Depends(get_current_user)
):

    alvex_security_admin(user)

    if not alvex_plan_service.validate_plan(
        data.plan
    ):

        raise HTTPException(
            status_code=400,
            detail="Invalid plan."
        )

    target_user = (
        db.query(User)
        .filter(User.id == data.user_id)
        .first()
    )

    if not target_user:

        raise HTTPException(
            status_code=404,
            detail="User not found."
        )

    subscription = (
        alvex_subscription_service.change_plan(
            db,
            data.user_id,
            data.plan,
            data.duration_days
        )
    )

    alvex_security_audit_logger.log(
        db=db,
        action="subscription_updated",
        user_id=user.id,
        resource=str(data.user_id)
    )

    return {
        "success": True,
        "subscription_id": subscription.subscription_id,
        "user_id": data.user_id,
        "plan": subscription.plan
    }


