# ------------------------------------------------------------
# 4. DATASET VALIDATOR
# ------------------------------------------------------------

class AlvexDatasetValidator:

    ALLOWED_EXTENSIONS = {
        ".jsonl",
        ".json",
        ".csv"
    }

    def validate_extension(self, filename):

        extension = Path(filename).suffix.lower()

        if extension not in self.ALLOWED_EXTENSIONS:

            raise ValueError(
                "Unsupported dataset format."
            )

        return extension

    def validate_size(self, file_size):

        maximum = (
            ALVEX_TRAINING_CONFIG[
                "maximum_dataset_size_mb"
            ] * 1024 * 1024
        )

        if file_size > maximum:

            raise ValueError(
                "Dataset exceeds maximum allowed size."
            )

    def calculate_hash(self, content):

        return hashlib.sha256(
            content
        ).hexdigest()


alvex_dataset_validator = AlvexDatasetValidator()


# ------------------------------------------------------------
# 5. DATASET PROCESSOR
# ------------------------------------------------------------

class AlvexDatasetProcessor:

    def read_jsonl(self, content):

        records = []

        for line_number, line in enumerate(
            content.decode("utf-8-sig").splitlines(),
            start=1
        ):

            if not line.strip():
                continue

            try:

                item = json.loads(line)

            except json.JSONDecodeError:

                raise ValueError(
                    f"Invalid JSON at line {line_number}."
                )

            if not isinstance(item, dict):

                raise ValueError(
                    "Each JSONL record must be an object."
                )

            records.append(item)

        return records

    def read_json(self, content):

        data = json.loads(
            content.decode("utf-8-sig")
        )

        if isinstance(data, dict):

            data = [data]

        if not isinstance(data, list):

            raise ValueError(
                "JSON dataset must contain objects."
            )

        if not all(
            isinstance(item, dict)
            for item in data
        ):

            raise ValueError(
                "Dataset entries must be objects."
            )

        return data

    def read_csv(self, content):

        import csv
        import io

        text = content.decode(
            "utf-8-sig"
        )

        reader = csv.DictReader(
            io.StringIO(text)
        )

        if not reader.fieldnames:

            raise ValueError(
                "CSV header is missing."
            )

        return list(reader)

    def process(self, content, extension):

        if extension == ".jsonl":

            records = self.read_jsonl(
                content
            )

        elif extension == ".json":

            records = self.read_json(
                content
            )

        elif extension == ".csv":

            records = self.read_csv(
                content
            )

        else:

            raise ValueError(
                "Unsupported dataset format."
            )

        if not records:

            raise ValueError(
                "Dataset is empty."
            )

        if len(records) > 100000:

            raise ValueError(
                "Dataset contains too many records."
            )

        return records


alvex_dataset_processor = AlvexDatasetProcessor()


# ------------------------------------------------------------
# 6. DATASET REPOSITORY
