class AlvexDatasetRepository:

    def create(
        self,
        db,
        owner_id,
        name,
        description,
        file_path,
        file_hash,
        sample_count
    ):

        dataset = AlvexTrainingDataset(

            dataset_id=str(uuid.uuid4()),

            owner_id=owner_id,

            name=name,

            description=description,

            file_path=file_path,

            file_hash=file_hash,

            sample_count=sample_count,

            status="ready"

        )

        db.add(dataset)

        db.commit()

        db.refresh(dataset)

        return dataset

    def get(
        self,
        db,
        dataset_id,
        owner_id
    ):

        return (
            db.query(AlvexTrainingDataset)
            .filter(
                AlvexTrainingDataset.dataset_id == dataset_id,
                AlvexTrainingDataset.owner_id == owner_id
            )
            .first()
        )

    def list(
        self,
        db,
        owner_id
    ):

        return (
            db.query(AlvexTrainingDataset)
            .filter(
                AlvexTrainingDataset.owner_id == owner_id
            )
            .order_by(
                AlvexTrainingDataset.created_at.desc()
            )
            .all()
        )


alvex_dataset_repository = AlvexDatasetRepository()


