# ------------------------------------------------------------
# 9. MODEL VERSION MANAGER
# ------------------------------------------------------------

class AlvexModelVersionManager:

    def calculate_file_hash(self, file_path):

        digest = hashlib.sha256()

        with open(file_path, "rb") as file:

            for chunk in iter(
                lambda: file.read(1024 * 1024),
                b""
            ):

                digest.update(chunk)

        return digest.hexdigest()

    def register(
        self,
        db,
        model_name,
        version,
        experiment_id=None,
        checkpoint_path=None
    ):

        checkpoint_hash = None

        if checkpoint_path:

            path = Path(checkpoint_path).resolve()

            allowed_root = Path(
                ALVEX_TRAINING_CONFIG[
                    "checkpoint_directory"
                ]
            ).resolve()

            if (
                allowed_root not in path.parents
                or not path.is_file()
            ):

                raise ValueError(
                    "Invalid checkpoint path."
                )

            checkpoint_hash = (
                self.calculate_file_hash(
                    str(path)
                )
            )

        model_version = AlvexModelVersion(

            version_id=str(uuid.uuid4()),

            model_name=model_name,

            version=version,

            experiment_id=experiment_id,

            checkpoint_path=checkpoint_path,

            checkpoint_hash=checkpoint_hash,

            status="registered"

        )

        db.add(model_version)

        db.commit()

        db.refresh(model_version)

        return model_version

    def get(
        self,
        db,
        version_id
    ):

        return (
            db.query(AlvexModelVersion)
            .filter(
                AlvexModelVersion.version_id == version_id
            )
            .first()
        )

    def list(
        self,
        db,
        model_name=None
    ):

        query = db.query(
            AlvexModelVersion
        )

        if model_name:

            query = query.filter(
                AlvexModelVersion.model_name == model_name
            )

        return (
            query.order_by(
                AlvexModelVersion.created_at.desc()
            )
            .all()
        )


alvex_model_version_manager = (
    AlvexModelVersionManager()
)


# ------------------------------------------------------------
# 10. MODEL EVALUATION ENGINE
# ------------------------------------------------------------

class AlvexModelEvaluationEngine:

    def evaluate(
        self,
        db,
        data
    ):

        version = alvex_model_version_manager.get(
            db,
            data.version_id
        )

        if not version:

            raise ValueError(
                "Model version not found."
            )

        evaluation = AlvexModelEvaluation(

            evaluation_id=str(uuid.uuid4()),

            version_id=data.version_id,

            accuracy=data.accuracy,

            response_quality=data.response_quality,

            latency_ms=data.latency_ms,

            notes=data.notes

        )

        db.add(evaluation)

        db.commit()

        db.refresh(evaluation)

        return evaluation

    def calculate_score(
        self,
        accuracy,
        response_quality,
        latency_ms
    ):

        latency_score = (
            1 / (1 + latency_ms / 1000)
        )

        return round(
            (
                accuracy * 0.4
                + response_quality * 0.4
                + latency_score * 0.2
            ) * 100,
            2
        )


alvex_model_evaluation_engine = (
    AlvexModelEvaluationEngine()
)


# ------------------------------------------------------------
# 11. TRAINING JOB MANAGER
# ------------------------------------------------------------

class AlvexTrainingJobManager:

    def start(
        self,
        db,
        experiment_id,
        owner_id
    ):

        experiment = alvex_experiment_manager.get(
            db,
            experiment_id,
            owner_id
        )

        if not experiment:

            raise ValueError(
                "Experiment not found."
            )

        if experiment.status in {
            "running",
            "completed"
        }:

            raise ValueError(
                "Experiment cannot be started."
            )

        experiment.status = "queued"

        db.commit()

        return experiment

    def mark_running(
        self,
        db,
        experiment_id
    ):

        experiment = (
            db.query(AlvexTrainingExperiment)
            .filter(
                AlvexTrainingExperiment.experiment_id
                == experiment_id
            )
            .first()
        )

        if not experiment:
            return None

        experiment.status = "running"

        db.commit()

        return experiment

    def complete(
        self,
        db,
        experiment_id
    ):

        experiment = (
            db.query(AlvexTrainingExperiment)
            .filter(
                AlvexTrainingExperiment.experiment_id
                == experiment_id
            )
            .first()
        )

        if not experiment:
            return None

        experiment.status = "completed"

        experiment.completed_at = datetime.utcnow()

        db.commit()

        return experiment

    def fail(
        self,
        db,
        experiment_id,
        error
    ):

        experiment = (
            db.query(AlvexTrainingExperiment)
            .filter(
                AlvexTrainingExperiment.experiment_id
                == experiment_id
            )
            .first()
        )

        if not experiment:
            return None

        experiment.status = "failed"

        experiment.error_message = str(error)[:2000]

        experiment.completed_at = datetime.utcnow()

        db.commit()

        return experiment


alvex_training_job_manager = (
    AlvexTrainingJobManager()
)


