@app.post("/api/training/datasets/upload")
async def alvex_upload_training_dataset(
    file: UploadFile,
    name: str,
    description: str = "",
    db: Session = Depends(get_db),
    user=Depends(get_current_user)
):

    try:

        extension = (
            alvex_dataset_validator.validate_extension(
                file.filename or ""
            )
        )

        content = await file.read(
            ALVEX_TRAINING_CONFIG[
                "maximum_dataset_size_mb"
            ] * 1024 * 1024 + 1
        )

        alvex_dataset_validator.validate_size(
            len(content)
        )

        records = alvex_dataset_processor.process(
            content,
            extension
        )

        file_hash = (
            alvex_dataset_validator.calculate_hash(
                content
            )
        )

        dataset_id = str(uuid.uuid4())

        destination = Path(
            ALVEX_TRAINING_CONFIG[
                "dataset_directory"
            ]
        ) / f"{dataset_id}{extension}"

        destination.write_bytes(
            content
        )

        dataset = alvex_dataset_repository.create(

            db=db,

            owner_id=user.id,

            name=name[:200],

            description=description[:2000],

            file_path=str(destination),

            file_hash=file_hash,

            sample_count=len(records)

        )

        return {
            "success": True,
            "dataset_id": dataset.dataset_id,
            "sample_count": dataset.sample_count,
            "file_hash": dataset.file_hash
        }

    except ValueError as exc:

        raise HTTPException(
            status_code=400,
            detail=str(exc)
        )

    finally:

        await file.close()


