# ------------------------------------------------------------
# 4. CONNECTION MANAGER
# ------------------------------------------------------------

class AlvexRealtimeConnectionManager:

    def __init__(self):

        self.connections = {}

        self.user_connections = {}

        self.lock = asyncio.Lock()

    async def connect(
        self,
        websocket,
        user_id
    ):

        async with self.lock:

            user_connections = (
                self.user_connections.get(
                    user_id,
                    set()
                )
            )

            if len(user_connections) >= (
                ALVEX_REALTIME_CONFIG[
                    "maximum_connections_per_user"
                ]
            ):

                raise ValueError(
                    "Maximum connection limit reached."
                )

            connection_id = str(uuid.uuid4())

            await websocket.accept()

            self.connections[
                connection_id
            ] = websocket

            self.user_connections.setdefault(
                user_id,
                set()
            ).add(connection_id)

            return connection_id

    async def disconnect(
        self,
        connection_id,
        user_id
    ):

        async with self.lock:

            self.connections.pop(
                connection_id,
                None
            )

            user_connections = (
                self.user_connections.get(
                    user_id,
                    set()
                )
            )

            user_connections.discard(
                connection_id
            )

            if not user_connections:

                self.user_connections.pop(
                    user_id,
                    None
                )

    async def send_personal(
        self,
        user_id,
        payload
    ):

        connections = list(
            self.user_connections.get(
                user_id,
                set()
            )
        )

        failed = []

        for connection_id in connections:

            websocket = self.connections.get(
                connection_id
            )

            if not websocket:
                continue

            try:

                await websocket.send_json(
                    payload
                )

            except Exception:

                failed.append(
                    connection_id
                )

        for connection_id in failed:

            await self.disconnect(
                connection_id,
                user_id
            )

    async def broadcast(
        self,
        payload
    ):

        for user_id in list(
            self.user_connections.keys()
        ):

            await self.send_personal(
                user_id,
                payload
            )

    def connection_count(self):

        return len(
            self.connections
        )

    def user_connection_count(
        self,
        user_id
    ):

        return len(
            self.user_connections.get(
                user_id,
                set()
            )
        )


alvex_realtime_connection_manager = (
    AlvexRealtimeConnectionManager()
)


# ------------------------------------------------------------
# 5. CONNECTION DATABASE SERVICE
# ------------------------------------------------------------

class AlvexRealtimeConnectionService:

    def create(
        self,
        db,
        connection_id,
        user_id
    ):

        record = AlvexRealtimeConnection(

            connection_id=connection_id,

            user_id=user_id,

            status="connected"

        )

        db.add(record)

        db.commit()

        return record

    def disconnect(
        self,
        db,
        connection_id,
        user_id
    ):

        record = (
            db.query(AlvexRealtimeConnection)
            .filter(
                AlvexRealtimeConnection.connection_id
                == connection_id,
                AlvexRealtimeConnection.user_id
                == user_id
            )
            .first()
        )

        if not record:
            return

        record.status = "disconnected"

        record.disconnected_at = datetime.utcnow()

        db.commit()


alvex_realtime_connection_service = (
    AlvexRealtimeConnectionService()
)


# ------------------------------------------------------------
# 6. REALTIME EVENT SERVICE
# ------------------------------------------------------------

class AlvexRealtimeEventService:

    ALLOWED_EVENTS = {

        "typing",

        "stop_typing",

        "message_received",

        "message_completed",

        "heartbeat",

        "status"

    }

    def save(
        self,
        db,
        user_id,
        event_type,
        payload=None
    ):

        if event_type not in self.ALLOWED_EVENTS:

            raise ValueError(
                "Unsupported realtime event."
            )

        safe_payload = json.dumps(
            payload or {},
            ensure_ascii=False,
            default=str
        )[:5000]

        event = AlvexRealtimeEvent(

            event_id=str(uuid.uuid4()),

            user_id=user_id,

            event_type=event_type,

            payload=safe_payload

        )

        db.add(event)

        db.commit()

        return event


alvex_realtime_event_service = (
    AlvexRealtimeEventService()
)


# ------------------------------------------------------------
# 7. REALTIME MESSAGE SERVICE
# ------------------------------------------------------------

class AlvexRealtimeMessageService:

    def save(
        self,
        db,
        user_id,
        content,
        role,
        conversation_id=None,
        status="completed"
    ):

        if role not in {
            "user",
            "assistant"
        }:

            raise ValueError(
                "Invalid message role."
            )

        message = AlvexRealtimeMessage(

            message_id=str(uuid.uuid4()),

            conversation_id=conversation_id,

            user_id=user_id,

            role=role,

            content=content,

            status=status

        )

        db.add(message)

        db.commit()

        db.refresh(message)

        return message

    def history(
        self,
        db,
        user_id,
        conversation_id=None,
        limit=50
    ):

        query = db.query(
            AlvexRealtimeMessage
        ).filter(
            AlvexRealtimeMessage.user_id == user_id
        )

        if conversation_id:

            query = query.filter(
                AlvexRealtimeMessage.conversation_id
                == conversation_id
            )

        return (
            query.order_by(
                AlvexRealtimeMessage.created_at.desc()
            )
            .limit(limit)
            .all()
        )


alvex_realtime_message_service = (
    AlvexRealtimeMessageService()
)


# ------------------------------------------------------------
# 8. STREAMING TEXT PROCESSOR
# ------------------------------------------------------------

class AlvexStreamingTextProcessor:

    def split(
        self,
        content,
        chunk_size=100
    ):

        if not content:
            return []

        return [
            content[index:index + chunk_size]

            for index in range(
                0,
                len(content),
                chunk_size
            )
        ]

    async def stream(
        self,
        websocket,
        content,
        request_id
    ):

        chunks = self.split(
            content,
            ALVEX_REALTIME_CONFIG[
                "stream_chunk_size"
            ]
        )

        for index, chunk in enumerate(chunks):

            await websocket.send_json({

                "type": "token",

                "request_id": request_id,

                "index": index,

                "content": chunk

            })

            await asyncio.sleep(
                ALVEX_REALTIME_CONFIG[
                    "stream_delay"
                ]
            )

        await websocket.send_json({

            "type": "stream_complete",

            "request_id": request_id,

            "total_chunks": len(chunks)

        })


alvex_streaming_text_processor = (
    AlvexStreamingTextProcessor()
)


