import json
import uuid
import logging

from datetime import datetime
from typing import Optional, Dict, List, Any

from fastapi import Depends, HTTPException
from pydantic import BaseModel, Field, field_validator


# ------------------------------------------------------------
# 1. FRONTEND CONFIGURATION
# ------------------------------------------------------------

ALVEX_FRONTEND_CONFIG = {

    "version": "1.0.0",

    "application_name": "ALVEX AI",

    "default_language": "tr",

    "supported_languages": [
        "tr",
        "en",
        "de",
        "fr",
        "es"
    ],

    "default_theme": "dark",

    "supported_themes": [
        "dark",
        "light",
        "system"
    ],

    "notifications_enabled": True,

    "maximum_notifications": 100,

    "maximum_devices_per_user": 10,

    "enable_dashboard": True,

    "enable_accessibility": True

}


# ------------------------------------------------------------
# 2. DATABASE MODELS
# ------------------------------------------------------------

class AlvexUserInterfaceSettings(Base):

    __tablename__ = "alvex_user_interface_settings"

    id = Column(
        Integer,
        primary_key=True,
        index=True
    )

    user_id = Column(
        Integer,
        ForeignKey("users.id"),
        unique=True,
        nullable=False,
        index=True
    )

    theme = Column(
        String(20),
        default="dark"
    )

    language = Column(
        String(10),
        default="tr"
    )

    font_size = Column(
        String(20),
        default="medium"
    )

    compact_mode = Column(
        Boolean,
        default=False
    )

    animations_enabled = Column(
        Boolean,
        default=True
    )

    sound_enabled = Column(
        Boolean,
        default=True
    )

    updated_at = Column(
        DateTime,
        default=datetime.utcnow,
        onupdate=datetime.utcnow
    )


class AlvexNotification(Base):

    __tablename__ = "alvex_notifications"

    id = Column(
        Integer,
        primary_key=True,
        index=True
    )

    notification_id = Column(
        String(100),
        unique=True,
        nullable=False,
        index=True
    )

    user_id = Column(
        Integer,
        ForeignKey("users.id"),
        nullable=False,
        index=True
    )

    title = Column(
        String(200),
        nullable=False
    )

    message = Column(
        Text,
        nullable=False
    )

    notification_type = Column(
        String(40),
        default="info"
    )

    is_read = Column(
        Boolean,
        default=False
    )

    action_url = Column(
        String(500),
        nullable=True
    )

    created_at = Column(
        DateTime,
        default=datetime.utcnow
    )

    read_at = Column(
        DateTime,
        nullable=True
    )


class AlvexUserDevice(Base):

    __tablename__ = "alvex_user_devices"

    id = Column(
        Integer,
        primary_key=True,
        index=True
    )

