@app.get("/api/frontend/bootstrap")
def alvex_frontend_bootstrap(
    db: Session = Depends(get_db),
    user=Depends(get_current_user)
):

    settings = (
        alvex_interface_settings_manager.get_settings(
            db,
            user.id
        )
    )

    unread = (
        alvex_notification_manager.unread_count(
            db,
            user.id
        )
    )

    model_status = "available"

    try:

        if "alvex_ai_gateway" in globals():

            model_status = "available"

        else:

            model_status = "unavailable"

    except Exception:

        model_status = "unavailable"

    return alvex_frontend_response_builder.build(
        user,
        settings,
        unread,
        model_status
    )


