# ------------------------------------------------------------
# 4. EVENT TRACKING SERVICE
# ------------------------------------------------------------

class AlvexAnalyticsEventManager:

    ALLOWED_CATEGORIES = {

        "chat",
        "account",
        "model",
        "document",
        "training",
        "subscription",
        "system",
        "api"

    }

    def record(
        self,
        db,
        event_type,
        category,
        user_id=None,
        metadata=None
    ):

        if category not in self.ALLOWED_CATEGORIES:

            raise ValueError(
                "Invalid analytics category."
            )

        safe_metadata = json.dumps(
            metadata or {},
            ensure_ascii=False,
            default=str
        )[:5000]

        event = AlvexAnalyticsEvent(

            event_id=str(uuid.uuid4()),

            user_id=user_id,

            event_type=event_type,

            category=category,

            metadata_json=safe_metadata

        )

        db.add(event)
        db.commit()
        db.refresh(event)

        return event

    def get_events(
        self,
        db,
        start_date,
        end_date,
        category=None,
        limit=1000
    ):

        query = db.query(
            AlvexAnalyticsEvent
        ).filter(
            AlvexAnalyticsEvent.created_at >= start_date,
            AlvexAnalyticsEvent.created_at <= end_date
        )

        if category:

            query = query.filter(
                AlvexAnalyticsEvent.category == category
            )

        return (
            query.order_by(
                AlvexAnalyticsEvent.created_at.desc()
            )
            .limit(limit)
            .all()
        )


alvex_analytics_event_manager = (
    AlvexAnalyticsEventManager()
)


# ------------------------------------------------------------
# 5. API PERFORMANCE MANAGER
# ------------------------------------------------------------

class AlvexAPIPerformanceManager:

    def record(
        self,
        db,
        endpoint,
        method,
        status_code,
        response_time_ms,
        user_id=None
    ):

        record = AlvexAPIPerformance(

            request_id=str(uuid.uuid4()),

            user_id=user_id,

            endpoint=endpoint[:300],

            method=method.upper()[:15],

            status_code=status_code,

            response_time_ms=response_time_ms

        )

        db.add(record)
        db.commit()

        return record

    def get_statistics(
        self,
        db,
        start_date,
        end_date
    ):

        records = (
            db.query(AlvexAPIPerformance)
            .filter(
                AlvexAPIPerformance.created_at >= start_date,
                AlvexAPIPerformance.created_at <= end_date
            )
            .limit(
                ALVEX_ANALYTICS_CONFIG[
                    "maximum_report_records"
                ]
            )
            .all()
        )

        if not records:

            return {

                "total_requests": 0,

                "average_response_ms": 0,

                "minimum_response_ms": 0,

                "maximum_response_ms": 0,

                "error_count": 0,

                "error_rate": 0

            }

        durations = [
            item.response_time_ms
            for item in records
        ]

        errors = [
            item
            for item in records
            if item.status_code >= 400
        ]

        return {

            "total_requests": len(records),

            "average_response_ms": round(
                statistics.mean(durations),
                2
            ),

            "minimum_response_ms": round(
                min(durations),
                2
            ),

            "maximum_response_ms": round(
                max(durations),
                2
            ),

            "error_count": len(errors),

            "error_rate": round(
                len(errors) / len(records) * 100,
                2
            )

        }


alvex_api_performance_manager = (
    AlvexAPIPerformanceManager()
)


