# ------------------------------------------------------------
# 7. SYSTEM INFORMATION COLLECTOR
# ------------------------------------------------------------

class AlvexSystemInformationCollector:

    def collect(self):

        information = {

            "platform": platform.system(),

            "platform_release": platform.release(),

            "architecture": platform.machine(),

            "python_version": platform.python_version(),

            "processor": platform.processor(),

            "cpu_count": os.cpu_count(),

            "timestamp": datetime.utcnow().isoformat()

        }

        try:

            import psutil

            memory = psutil.virtual_memory()

            information["memory"] = {

                "total_bytes": memory.total,

                "available_bytes": memory.available,

                "used_percent": memory.percent

            }

            information["cpu_percent"] = (
                psutil.cpu_percent(interval=None)
            )

            disk = psutil.disk_usage(
                os.path.abspath(os.sep)
            )

            information["disk"] = {

                "total_bytes": disk.total,

                "used_bytes": disk.used,

                "free_bytes": disk.free,

                "used_percent": disk.percent

            }

        except ImportError:

            information["resource_monitoring"] = (
                "psutil_not_installed"
            )

        except Exception:

            logging.exception(
                "System information collection failed."
            )

            information["resource_monitoring"] = (
                "temporarily_unavailable"
            )

        return information


alvex_system_information_collector = (
    AlvexSystemInformationCollector()
)


# ------------------------------------------------------------
# 8. ANALYTICS REPORT GENERATOR
# ------------------------------------------------------------

class AlvexAnalyticsReportGenerator:

    def generate(
        self,
        db,
        user_id,
        report_type="general",
        period_days=7
    ):

        if not 1 <= period_days <= 365:

            raise ValueError(
                "Invalid report period."
            )

        end_date = datetime.utcnow()

        start_date = (
            end_date - timedelta(days=period_days)
        )

        api_statistics = (
            alvex_api_performance_manager.get_statistics(
                db,
                start_date,
                end_date
            )
        )

        events = (
            alvex_analytics_event_manager.get_events(
                db,
                start_date,
                end_date,
                limit=5000
            )
        )

        category_counts = {}

        event_counts = {}

        for event in events:

            category_counts[event.category] = (
                category_counts.get(
                    event.category,
                    0
                ) + 1
            )

            event_counts[event.event_type] = (
                event_counts.get(
                    event.event_type,
                    0
                ) + 1
            )

        report = {

            "report_type": report_type,

            "period": {

                "start": start_date.isoformat(),

                "end": end_date.isoformat(),

                "days": period_days

            },

            "api": api_statistics,

            "events": {

                "total": len(events),

                "categories": category_counts,

                "types": event_counts

            },

            "generated_at": datetime.utcnow().isoformat()

        }

        record = AlvexAnalyticsReport(

            report_id=str(uuid.uuid4()),

            created_by=user_id,

            report_type=report_type,

            period_days=period_days,

            report_data=json.dumps(
                report,
                ensure_ascii=False
            )

        )

        db.add(record)
        db.commit()
        db.refresh(record)

        return record


alvex_analytics_report_generator = (
    AlvexAnalyticsReportGenerator()
)


