class AlvexUserAnalyticsService:

    def get_user_statistics(
        self,
        db,
        user_id,
        period_days=30
    ):

        start_date = (
            datetime.utcnow()
            - timedelta(days=period_days)
        )

        event_count = (
            db.query(AlvexAnalyticsEvent)
            .filter(
                AlvexAnalyticsEvent.user_id == user_id,
                AlvexAnalyticsEvent.created_at >= start_date
            )
            .count()
        )

        message_count = (
            db.query(AlvexRealtimeMessage)
            .filter(
                AlvexRealtimeMessage.user_id == user_id,
                AlvexRealtimeMessage.created_at >= start_date
            )
            .count()
        )

        notification_count = (
            db.query(AlvexNotification)
            .filter(
                AlvexNotification.user_id == user_id,
                AlvexNotification.created_at >= start_date
            )
            .count()
        )

        return {

            "period_days": period_days,

            "events": event_count,

            "messages": message_count,

            "notifications": notification_count

        }


alvex_user_analytics_service = (
    AlvexUserAnalyticsService()
)


