# ------------------------------------------------------------
# 4. API KEY CRYPTOGRAPHIC UTILITIES
# ------------------------------------------------------------

class AlvexAPIKeyCrypto:

    @staticmethod
    def generate():

        random_part = secrets.token_urlsafe(
            ALVEX_DEVELOPER_CONFIG["key_length"]
        )

        return (
            ALVEX_DEVELOPER_CONFIG["key_prefix"]
            + random_part
        )

    @staticmethod
    def hash_key(api_key):

        return hashlib.sha256(
            api_key.encode("utf-8")
        ).hexdigest()

    @staticmethod
    def verify(
        api_key,
        stored_hash
    ):

        calculated_hash = (
            AlvexAPIKeyCrypto.hash_key(
                api_key
            )
        )

        return hmac.compare_digest(
            calculated_hash,
            stored_hash
        )

    @staticmethod
    def get_prefix(api_key):

        return api_key[:12]


alvex_api_key_crypto = AlvexAPIKeyCrypto()


# ------------------------------------------------------------
# 5. API KEY MANAGER
# ------------------------------------------------------------

class AlvexAPIKeyManager:

    ALLOWED_SCOPES = {

        "ai.generate",
        "ai.models.read",
        "chat.read",
        "chat.write",
        "documents.read",
        "documents.write",
        "analytics.read"

    }

    def create(
        self,
        db,
        user_id,
        data
    ):

        existing_count = (
            db.query(AlvexDeveloperAPIKey)
            .filter(
                AlvexDeveloperAPIKey.user_id == user_id,
                AlvexDeveloperAPIKey.is_active.is_(True)
            )
            .count()
        )

        if existing_count >= (
            ALVEX_DEVELOPER_CONFIG[
                "maximum_keys_per_user"
            ]
        ):

            raise HTTPException(
                status_code=400,
                detail="API key limit reached."
            )

        if not set(data.scopes).issubset(
            self.ALLOWED_SCOPES
        ):

            raise HTTPException(
                status_code=400,
                detail="Invalid API permissions."
            )

        api_key = alvex_api_key_crypto.generate()

        key_id = str(uuid.uuid4())

        expires_at = None

        if data.lifetime_days is not None:

            expires_at = (
                datetime.utcnow()
                + timedelta(days=data.lifetime_days)
            )

        record = AlvexDeveloperAPIKey(

            key_id=key_id,

            user_id=user_id,

            name=data.name,

            key_hash=(
                alvex_api_key_crypto.hash_key(
                    api_key
                )
            ),

            key_prefix=(
                alvex_api_key_crypto.get_prefix(
                    api_key
                )
            ),

            scopes=json.dumps(
                data.scopes
            ),

            rate_limit=data.rate_limit,

            expires_at=expires_at

        )

        db.add(record)
        db.commit()
        db.refresh(record)

        return {

            "key_id": key_id,

            "api_key": api_key,

            "name": record.name,

            "scopes": data.scopes,

            "expires_at": expires_at,

            "warning": (
                "This API key is displayed only once."
            )

        }

    def authenticate(
        self,
        db,
        api_key
    ):

        if not api_key or len(api_key) > 200:

            return None

        key_hash = (
            alvex_api_key_crypto.hash_key(
                api_key
            )
        )

        record = (
            db.query(AlvexDeveloperAPIKey)
            .filter(
                AlvexDeveloperAPIKey.key_hash
                == key_hash,
                AlvexDeveloperAPIKey.is_active.is_(True)
            )
            .first()
        )

        if not record:
            return None

        if record.expires_at:

            if record.expires_at <= datetime.utcnow():

                return None

        record.last_used_at = datetime.utcnow()

        db.commit()

        return record

    def revoke(
        self,
        db,
        user_id,
        key_id
    ):

        record = (
            db.query(AlvexDeveloperAPIKey)
            .filter(
                AlvexDeveloperAPIKey.key_id == key_id,
                AlvexDeveloperAPIKey.user_id == user_id
            )
            .first()
        )

        if not record:

            raise HTTPException(
                status_code=404,
                detail="API key not found."
            )

        record.is_active = False

        record.revoked_at = datetime.utcnow()

        db.commit()

        return True

    def list_keys(
        self,
        db,
        user_id
    ):

        records = (
            db.query(AlvexDeveloperAPIKey)
            .filter(
                AlvexDeveloperAPIKey.user_id == user_id
            )
            .order_by(
                AlvexDeveloperAPIKey.created_at.desc()
            )
            .all()
        )

        return [

            {

                "key_id": item.key_id,

                "name": item.name,

                "prefix": item.key_prefix,

                "scopes": json.loads(
                    item.scopes
                ),

                "rate_limit": item.rate_limit,

                "is_active": item.is_active,

                "expires_at": item.expires_at,

                "last_used_at": item.last_used_at,

                "created_at": item.created_at

            }

            for item in records

        ]


alvex_api_key_manager = AlvexAPIKeyManager()


# ------------------------------------------------------------
# 6. API KEY AUTHENTICATION DEPENDENCY
# ------------------------------------------------------------

def alvex_require_api_key(
    db: Session = Depends(get_db),
    authorization: Optional[str] = Header(
        default=None
    )
):

    if not authorization:

        raise HTTPException(
            status_code=401,
            detail="API key required."
        )

    scheme, separator, token = (
        authorization.partition(" ")
    )

    if (
        scheme.lower() != "bearer"
        or not separator
        or not token
    ):

        raise HTTPException(
            status_code=401,
            detail="Invalid authorization format."
        )

    record = alvex_api_key_manager.authenticate(
        db,
        token.strip()
    )

    if not record:

        raise HTTPException(
            status_code=401,
            detail="Invalid or expired API key."
        )

    return record


# ------------------------------------------------------------
# 7. SCOPE VALIDATION
# ------------------------------------------------------------

def alvex_require_scope(
    required_scope
):

    def dependency(
        api_key=Depends(
            alvex_require_api_key
        )
    ):

        scopes = set(
            json.loads(api_key.scopes)
        )

        if required_scope not in scopes:

            raise HTTPException(
                status_code=403,
                detail="API permission denied."
            )

        return api_key

    return dependency


# ------------------------------------------------------------
# 8. API USAGE TRACKER
# ------------------------------------------------------------

class AlvexDeveloperUsageManager:

    def record(
        self,
        db,
        api_key,
        endpoint,
        method,
        status_code,
        response_time_ms=0
    ):

        record = AlvexDeveloperAPIUsage(

            usage_id=str(uuid.uuid4()),

            key_id=api_key.key_id,

            user_id=api_key.user_id,

            endpoint=endpoint[:300],

            method=method.upper()[:15],

            status_code=status_code,

            response_time_ms=max(
                0,
                float(response_time_ms)
            )

        )

        db.add(record)
        db.commit()

        return record

    def statistics(
        self,
        db,
        user_id,
        period_days=30
    ):

        start_date = (
            datetime.utcnow()
            - timedelta(days=period_days)
        )

        records = (
            db.query(AlvexDeveloperAPIUsage)
            .filter(
                AlvexDeveloperAPIUsage.user_id == user_id,
                AlvexDeveloperAPIUsage.created_at >= start_date
            )
            .all()
        )

        total = len(records)

        errors = sum(
            1
            for item in records
            if item.status_code >= 400
        )

        average_time = (

            sum(
                item.response_time_ms
                for item in records
            ) / total

            if total else 0

        )

        return {

            "period_days": period_days,

            "total_requests": total,

            "error_count": errors,

            "average_response_ms": round(
                average_time,
                2
            )

        }


alvex_developer_usage_manager = (
    AlvexDeveloperUsageManager()
)


# ------------------------------------------------------------
# 9. WEBHOOK MANAGER
# ------------------------------------------------------------

class AlvexWebhookManager:

    ALLOWED_EVENTS = {

        "chat.completed",
        "model.updated",
        "document.processed",
        "subscription.changed",
        "account.updated"

    }

    def create(
        self,
        db,
        user_id,
        data
    ):

        from urllib.parse import urlparse
        import ipaddress
        import socket

        parsed = urlparse(
            data.target_url
        )

        if (
            parsed.scheme != "https"
            or not parsed.hostname
            or parsed.username
            or parsed.password
        ):

            raise HTTPException(
                status_code=400,
                detail="Webhook URL must use HTTPS."
            )

        try:

            addresses = socket.getaddrinfo(
                parsed.hostname,
                None
            )

            for address in addresses:

                ip = ipaddress.ip_address(
                    address[4][0]
                )

                if not ip.is_global:

                    raise HTTPException(
                        status_code=400,
                        detail="Webhook host is not publicly routable."
                    )

        except HTTPException:

            raise

        except Exception:

            raise HTTPException(
                status_code=400,
                detail="Webhook hostname could not be validated."
            )

        if not set(
            data.subscribed_events
        ).issubset(
            self.ALLOWED_EVENTS
        ):

            raise HTTPException(
                status_code=400,
                detail="Unsupported webhook event."
            )

        record = AlvexDeveloperWebhook(

            webhook_id=str(uuid.uuid4()),

            user_id=user_id,

            name=data.name,

            target_url=data.target_url,

            subscribed_events=json.dumps(
                data.subscribed_events
            )

        )

        db.add(record)
        db.commit()
        db.refresh(record)

        return record

    def list(
        self,
        db,
        user_id
    ):

        return (
            db.query(AlvexDeveloperWebhook)
            .filter(
                AlvexDeveloperWebhook.user_id == user_id
            )
            .order_by(
                AlvexDeveloperWebhook.created_at.desc()
            )
            .all()
        )

    def delete(
        self,
        db,
        user_id,
        webhook_id
    ):

        record = (
            db.query(AlvexDeveloperWebhook)
            .filter(
                AlvexDeveloperWebhook.webhook_id == webhook_id,
                AlvexDeveloperWebhook.user_id == user_id
            )
            .first()
        )

        if not record:

            raise HTTPException(
                status_code=404,
                detail="Webhook not found."
            )

        db.delete(record)
        db.commit()

        return True


alvex_webhook_manager = AlvexWebhookManager()


