# ------------------------------------------------------------
# 12. DEVELOPER API EXAMPLE
# ------------------------------------------------------------

@app.post("/api/developer/v1/generate")
async def alvex_developer_generate(
    data: AlvexRealtimeMessageRequest,
    request: Request,
    db: Session = Depends(get_db),
    api_key=Depends(
        alvex_require_scope("ai.generate")
    )
):

    started = time.perf_counter()

    status_code = 200

    try:

        ai_request = AlvexLLMRequest(

            messages=[
                {
                    "role": "user",
                    "content": data.content
                }
            ],

            temperature=0.5,

            max_tokens=1500,

            stream=False

        )

        response = await alvex_ai_gateway.execute(
            request=ai_request,
            user_id=api_key.user_id,
            db=db
        )

        if not response.success:

            status_code = 502

            raise HTTPException(
                status_code=502,
                detail="AI provider unavailable."
            )

        return {

            "success": True,

            "model": response.model,

            "provider": response.provider,

            "content": response.content

        }

    finally:

        elapsed = (
            time.perf_counter() - started
        ) * 1000

        try:

            alvex_developer_usage_manager.record(
                db=db,
                api_key=api_key,
                endpoint=request.url.path,
                method=request.method,
                status_code=status_code,
                response_time_ms=elapsed
            )

        except Exception:

            logging.exception(
                "Developer API usage logging failed."
            )


