# ------------------------------------------------------------
# 4. FILE NAME VALIDATOR
# ------------------------------------------------------------

class AlvexFileValidator:

    def validate_filename(
        self,
        filename
    ):

        if not filename:

            raise HTTPException(
                status_code=400,
                detail="Filename is required."
            )

        normalized = Path(
            filename.replace("\\", "/")
        ).name

        if normalized in {
            "",
            ".",
            ".."
        }:

            raise HTTPException(
                status_code=400,
                detail="Invalid filename."
            )

        extension = Path(
            normalized
        ).suffix.lower()

        if extension not in (
            ALVEX_STORAGE_CONFIG[
                "allowed_extensions"
            ]
        ):

            raise HTTPException(
                status_code=415,
                detail="File extension is not supported."
            )

        return normalized, extension

    def validate_size(
        self,
        size
    ):

        if size <= 0:

            raise HTTPException(
                status_code=400,
                detail="Empty files are not allowed."
            )

        if size > (
            ALVEX_STORAGE_CONFIG[
                "maximum_file_size"
            ]
        ):

            raise HTTPException(
                status_code=413,
                detail="Maximum file size exceeded."
            )


alvex_file_validator = AlvexFileValidator()


# ------------------------------------------------------------
# 5. STORAGE QUOTA MANAGER
# ------------------------------------------------------------

class AlvexStorageQuotaManager:

    def get_or_create(
        self,
        db,
        user_id
    ):

        quota = (
            db.query(AlvexUserStorageQuota)
            .filter(
                AlvexUserStorageQuota.user_id
                == user_id
            )
            .first()
        )

        if quota:
            return quota

        quota = AlvexUserStorageQuota(

            user_id=user_id,

            quota_bytes=(
                ALVEX_STORAGE_CONFIG[
                    "default_user_quota"
                ]
            ),

            used_bytes=0

        )

        db.add(quota)
        db.commit()
        db.refresh(quota)

        return quota

    def check(
        self,
        db,
        user_id,
        additional_bytes
    ):

        quota = self.get_or_create(
            db,
            user_id
        )

        if (
            quota.used_bytes + additional_bytes
            > quota.quota_bytes
        ):

            raise HTTPException(
                status_code=413,
                detail="Storage quota exceeded."
            )

        return quota

    def add_usage(
        self,
        db,
        user_id,
        file_size
    ):

        quota = self.get_or_create(
            db,
            user_id
        )

        quota.used_bytes += file_size

        quota.updated_at = datetime.utcnow()

        db.commit()

        return quota

    def remove_usage(
        self,
        db,
        user_id,
        file_size
    ):

        quota = self.get_or_create(
            db,
            user_id
        )

        quota.used_bytes = max(
            0,
            quota.used_bytes - file_size
        )

        quota.updated_at = datetime.utcnow()

        db.commit()

        return quota

    def get_usage(
        self,
        db,
        user_id
    ):

        quota = self.get_or_create(
            db,
            user_id
        )

        percentage = (

            quota.used_bytes
            / quota.quota_bytes
            * 100

            if quota.quota_bytes else 0

        )

        return {

            "used_bytes": quota.used_bytes,

            "quota_bytes": quota.quota_bytes,

            "remaining_bytes": max(
                0,
                quota.quota_bytes - quota.used_bytes
            ),

            "used_percent": round(
                percentage,
                2
            )

        }


alvex_storage_quota_manager = (
    AlvexStorageQuotaManager()
)


# ------------------------------------------------------------
# 6. FILE HASH SERVICE
# ------------------------------------------------------------

class AlvexFileHashService:

    @staticmethod
    def calculate(content):

        return hashlib.sha256(
            content
        ).hexdigest()


alvex_file_hash_service = (
    AlvexFileHashService()
)


# ------------------------------------------------------------
# 7. FILE STORAGE SERVICE
# ------------------------------------------------------------

class AlvexFileStorageService:

    def user_directory(
        self,
        user_id
    ):

        directory = (
            ALVEX_STORAGE_ROOT
            / str(user_id)
        ).resolve()

        if not directory.is_relative_to(
            ALVEX_STORAGE_ROOT
        ):

            raise HTTPException(
                status_code=400,
                detail="Invalid storage directory."
            )

        directory.mkdir(
            parents=True,
            exist_ok=True
        )

        return directory

    async def upload(
        self,
        db,
        user_id,
        upload_file
    ):

        filename, extension = (
            alvex_file_validator.validate_filename(
                upload_file.filename
            )
        )

        existing_count = (
            db.query(AlvexStoredFile)
            .filter(
                AlvexStoredFile.user_id == user_id,
                AlvexStoredFile.status == "active"
            )
            .count()
        )

        if existing_count >= (
            ALVEX_STORAGE_CONFIG[
                "maximum_files_per_user"
            ]
        ):

            raise HTTPException(
                status_code=400,
                detail="File count limit reached."
            )

        directory = self.user_directory(
            user_id
        )

        stored_name = (
            str(uuid.uuid4())
            + extension
        )

        destination = (
            directory / stored_name
        ).resolve()

        if not destination.is_relative_to(
            directory
        ):

            raise HTTPException(
                status_code=400,
                detail="Invalid storage path."
            )

        total_size = 0

        file_hash = hashlib.sha256()

        temporary_path = (
            directory
            / f".{stored_name}.uploading"
        )

        try:

            with temporary_path.open("xb") as output:

                while True:

                    chunk = await upload_file.read(
                        ALVEX_STORAGE_CONFIG[
                            "chunk_size"
                        ]
                    )

                    if not chunk:
                        break

                    total_size += len(chunk)

                    if total_size > (
                        ALVEX_STORAGE_CONFIG[
                            "maximum_file_size"
                        ]
                    ):

                        raise HTTPException(
                            status_code=413,
                            detail="Maximum file size exceeded."
                        )

                    file_hash.update(chunk)

                    output.write(chunk)

            alvex_file_validator.validate_size(
                total_size
            )

            quota = (
                alvex_storage_quota_manager.check(
                    db,
                    user_id,
                    total_size
                )
            )

            os.replace(
                temporary_path,
                destination
            )

            record = AlvexStoredFile(

                file_id=str(uuid.uuid4()),

                user_id=user_id,

                original_name=filename,

                stored_name=stored_name,

                extension=extension,

                mime_type=(
                    upload_file.content_type
                    or mimetypes.guess_type(filename)[0]
                ),

                file_size=total_size,

                sha256_hash=file_hash.hexdigest(),

                storage_path=str(destination),

                status="active"

            )

            db.add(record)

            quota.used_bytes += total_size

            quota.updated_at = datetime.utcnow()

            db.commit()

            db.refresh(record)

            self.log_access(
                db,
                record.file_id,
                user_id,
                "upload"
            )

            return record

        except Exception:

            db.rollback()

            if temporary_path.exists():

                temporary_path.unlink()

            if destination.exists():

                destination.unlink()

            raise

        finally:

            await upload_file.close()

    def get_file(
        self,
        db,
        user_id,
        file_id
    ):

        record = (
            db.query(AlvexStoredFile)
            .filter(
                AlvexStoredFile.file_id == file_id,
                AlvexStoredFile.user_id == user_id,
                AlvexStoredFile.status == "active"
            )
            .first()
        )

        if not record:

            raise HTTPException(
                status_code=404,
                detail="File not found."
            )

        path = Path(
            record.storage_path
        ).resolve()

        user_directory = self.user_directory(
            user_id
        )

        if not path.is_relative_to(
            user_directory
        ):

            raise HTTPException(
                status_code=403,
                detail="Invalid file location."
            )

        if not path.is_file():

            raise HTTPException(
                status_code=404,
                detail="Stored file is missing."
            )

        return record

    def log_access(
        self,
        db,
        file_id,
        user_id,
        action
    ):

        record = AlvexFileAccessLog(

            access_id=str(uuid.uuid4()),

            file_id=file_id,

            user_id=user_id,

            action=action

        )

        db.add(record)
        db.commit()

    def delete(
        self,
        db,
        user_id,
        file_id
    ):

        record = self.get_file(
            db,
            user_id,
            file_id
        )

        if ALVEX_STORAGE_CONFIG[
            "enable_soft_delete"
        ]:

            record.status = "deleted"

            record.deleted_at = datetime.utcnow()

            quota = (
                alvex_storage_quota_manager.get_or_create(
                    db,
                    user_id
                )
            )

            quota.used_bytes = max(
                0,
                quota.used_bytes - record.file_size
            )

            db.commit()

            self.log_access(
                db,
                file_id,
                user_id,
                "delete"
            )

            return True

        path = Path(
            record.storage_path
        )

        path.unlink(
            missing_ok=True
        )

        alvex_storage_quota_manager.remove_usage(
            db,
            user_id,
            record.file_size
        )

        db.delete(record)

        db.commit()

        return True

    def list_files(
        self,
        db,
        user_id,
        limit=100
    ):

        return (
            db.query(AlvexStoredFile)
            .filter(
                AlvexStoredFile.user_id == user_id,
                AlvexStoredFile.status == "active"
            )
            .order_by(
                AlvexStoredFile.created_at.desc()
            )
            .limit(limit)
            .all()
        )


alvex_file_storage_service = (
    AlvexFileStorageService()
)


