# ============================================================
# ALVEX AI - PART 22
# BACKUP / RECOVERY / INTEGRITY ENGINE
# ============================================================

import os
import json
import uuid
import shutil
import hashlib
import sqlite3
import logging
import threading

from pathlib import Path
from datetime import datetime, timedelta
from typing import Optional, List

from pydantic import BaseModel, Field
from fastapi import Depends, HTTPException, Query
from sqlalchemy import Column, Integer, String, DateTime, BigInteger, Text


# ------------------------------------------------------------
# 1. CONFIGURATION
# ------------------------------------------------------------

ALVEX_BACKUP_CONFIG = {

    "version": "1.0.0",

    "backup_directory": "storage/alvex_backups",

    "maximum_backups": 30,

    "maximum_backup_size": 2 * 1024 * 1024 * 1024,

    "automatic_backup_enabled": True,

    "backup_interval_hours": 24,

    "compression_enabled": True,

    "integrity_algorithm": "sha256",

    "require_admin_restore": True,

    "keep_failed_backups": False

}


ALVEX_BACKUP_ROOT = Path(
    ALVEX_BACKUP_CONFIG["backup_directory"]
).resolve()

ALVEX_BACKUP_ROOT.mkdir(
    parents=True,
    exist_ok=True
)


# ------------------------------------------------------------
# 2. DATABASE MODEL
# ------------------------------------------------------------

class AlvexBackupRecord(Base):

    __tablename__ = "alvex_backup_records"

    id = Column(
        Integer,
        primary_key=True,
        index=True
    )

    backup_id = Column(
        String(100),
        unique=True,
        nullable=False,
        index=True
    )

    filename = Column(
        String(255),
        nullable=False
    )

    backup_type = Column(
        String(30),
        default="manual"
    )

    file_size = Column(
        BigInteger,
        default=0
    )

    sha256_hash = Column(
        String(64),
        nullable=False
    )

    status = Column(
        String(30),
        default="completed"
    )

    created_by = Column(
        Integer,
        nullable=True
    )

    created_at = Column(
        DateTime,
        default=datetime.utcnow
    )

    verified_at = Column(
        DateTime,
        nullable=True
    )

    description = Column(
        Text,
        nullable=True
    )


Base.metadata.create_all(bind=engine)


# ------------------------------------------------------------
# 3. SCHEMAS
# ------------------------------------------------------------

class AlvexBackupCreateRequest(BaseModel):

    description: Optional[str] = Field(
        default=None,
        max_length=500
    )


class AlvexBackupVerifyRequest(BaseModel):

    backup_id: str = Field(
        min_length=10,
        max_length=100
    )


class AlvexBackupRestoreRequest(BaseModel):

    backup_id: str = Field(
        min_length=10,
        max_length=100
    )

    confirmation: str = Field(
        min_length=1,
        max_length=100
    )


# ------------------------------------------------------------
# 4. HASH SERVICE
# ------------------------------------------------------------

class AlvexBackupHashService:

    @staticmethod
    def calculate_file_hash(path):

        digest = hashlib.sha256()

        with open(path, "rb") as file:

            for chunk in iter(
                lambda: file.read(1024 * 1024),
                b""
            ):

                digest.update(chunk)

        return digest.hexdigest()

    @staticmethod
    def verify_file(path, expected_hash):

        actual_hash = (
            AlvexBackupHashService.calculate_file_hash(
                path
            )
        )

        return hashlib.compare_digest(
            actual_hash,
            expected_hash
        )


alvex_backup_hash_service = (
    AlvexBackupHashService()
)


# ------------------------------------------------------------
# 5. DATABASE PATH RESOLVER
# ------------------------------------------------------------

class AlvexDatabasePathResolver:

    @staticmethod
    def get_sqlite_path():

        database_url = str(
            engine.url
        )

        if not database_url.startswith(
            "sqlite:///"
        ):

            raise RuntimeError(
                "This backup adapter supports SQLite only."
            )

        raw_path = database_url.replace(
            "sqlite:///",
            "",
            1
        )

        if raw_path == ":memory:":

            raise RuntimeError(
                "In-memory SQLite cannot be backed up using this adapter."
            )

        return Path(raw_path).resolve()


alvex_database_path_resolver = (
    AlvexDatabasePathResolver()
)


# ------------------------------------------------------------
# 6. BACKUP REPOSITORY
# ------------------------------------------------------------

class AlvexBackupRepository:

    def create(
        self,
        db,
        backup_id,
        filename,
        backup_type,
        file_size,
        sha256_hash,
        created_by,
        description=None
    ):

        record = AlvexBackupRecord(

            backup_id=backup_id,

            filename=filename,

            backup_type=backup_type,

            file_size=file_size,

            sha256_hash=sha256_hash,

            created_by=created_by,

            description=description,

            status="completed"

        )

        db.add(record)
        db.commit()
        db.refresh(record)

        return record

    def get(
        self,
        db,
        backup_id
    ):

        return (
            db.query(AlvexBackupRecord)
            .filter(
                AlvexBackupRecord.backup_id
                == backup_id
            )
            .first()
        )

    def list(
        self,
        db,
        limit=50
    ):

        return (
            db.query(AlvexBackupRecord)
            .order_by(
                AlvexBackupRecord.created_at.desc()
            )
            .limit(limit)
            .all()
        )

    def delete(
        self,
        db,
        record
    ):

        db.delete(record)
        db.commit()


alvex_backup_repository = (
    AlvexBackupRepository()
)


# ------------------------------------------------------------
# 7. BACKUP ENGINE
# ------------------------------------------------------------

class AlvexBackupEngine:

    def __init__(self):

        self.lock = threading.Lock()

    def create_backup(
        self,
        db,
        user_id,
        backup_type="manual",
        description=None
    ):

        if not self.lock.acquire(
            blocking=False
        ):

            raise HTTPException(
                status_code=409,
                detail="Another backup operation is running."
            )

        backup_id = str(uuid.uuid4())

        filename = (
            f"alvex_{backup_id}.sqlite3"
        )

        destination = (
            ALVEX_BACKUP_ROOT / filename
        ).resolve()

        temporary = (
            ALVEX_BACKUP_ROOT
            / f".{backup_id}.temporary"
        )

        try:

            source = (
                alvex_database_path_resolver.get_sqlite_path()
            )

            if not source.is_file():

                raise HTTPException(
                    status_code=404,
                    detail="Database file not found."
                )

            source_connection = sqlite3.connect(
                str(source)
            )

            target_connection = sqlite3.connect(
                str(temporary)
            )

            try:

                source_connection.backup(
                    target_connection
                )

            finally:

                target_connection.close()
                source_connection.close()

            if not temporary.exists():

                raise RuntimeError(
                    "Backup file was not created."
                )

            file_size = temporary.stat().st_size

            if file_size > (
                ALVEX_BACKUP_CONFIG[
                    "maximum_backup_size"
                ]
            ):

                raise HTTPException(
                    status_code=413,
                    detail="Backup exceeds maximum size."
                )

            digest = (
                alvex_backup_hash_service.calculate_file_hash(
                    temporary
                )
            )

            os.replace(
                temporary,
                destination
            )

            record = alvex_backup_repository.create(

                db=db,

                backup_id=backup_id,

                filename=filename,

                backup_type=backup_type,

                file_size=file_size,

                sha256_hash=digest,

                created_by=user_id,

                description=description

            )

            self.cleanup_old_backups(db)

            return record

        except Exception:

            db.rollback()

            temporary.unlink(
                missing_ok=True
            )

            destination.unlink(
                missing_ok=True
            )

            raise

        finally:

            self.lock.release()

    def verify_backup(
        self,
        db,
        backup_id
    ):

        record = alvex_backup_repository.get(
            db,
            backup_id
        )

        if not record:

            raise HTTPException(
                status_code=404,
                detail="Backup not found."
            )

        path = (
            ALVEX_BACKUP_ROOT
            / record.filename
        ).resolve()

        if not path.is_relative_to(
            ALVEX_BACKUP_ROOT
        ):

            raise HTTPException(
                status_code=403,
                detail="Invalid backup path."
            )

        if not path.is_file():

            raise HTTPException(
                status_code=404,
                detail="Backup file is missing."
            )

        valid = (
            alvex_backup_hash_service.verify_file(
                path,
                record.sha256_hash
            )
        )

        if valid:

            record.verified_at = datetime.utcnow()

            record.status = "verified"

        else:

            record.status = "integrity_failed"

        db.commit()

        return {

            "backup_id": backup_id,

            "valid": valid,

            "expected_hash": record.sha256_hash,

            "status": record.status

        }

    def cleanup_old_backups(
        self,
        db
    ):

        records = (
            db.query(AlvexBackupRecord)
            .order_by(
                AlvexBackupRecord.created_at.desc()
            )
            .all()
        )

        maximum = ALVEX_BACKUP_CONFIG[
            "maximum_backups"
        ]

        for record in records[maximum:]:

            path = (
                ALVEX_BACKUP_ROOT
                / record.filename
            ).resolve()

            if path.is_relative_to(
                ALVEX_BACKUP_ROOT
            ):

                path.unlink(
                    missing_ok=True
                )

            alvex_backup_repository.delete(
                db,
                record
            )


alvex_backup_engine = AlvexBackupEngine()


# ------------------------------------------------------------
# 8. RECOVERY VALIDATOR
# ------------------------------------------------------------

class AlvexRecoveryValidator:

    def validate_backup(
        self,
        path
    ):

        path = Path(path).resolve()

        if not path.is_relative_to(
            ALVEX_BACKUP_ROOT
        ):

            raise HTTPException(
                status_code=403,
                detail="Invalid backup location."
            )

        if not path.is_file():

            raise HTTPException(
                status_code=404,
                detail="Backup does not exist."
            )

        try:

            connection = sqlite3.connect(
                f"file:{path}?mode=ro",
                uri=True
            )

            result = connection.execute(
                "PRAGMA quick_check"
            ).fetchone()

            connection.close()

            return bool(
                result and result[0] == "ok"
            )

        except sqlite3.Error:

            return False


alvex_recovery_validator = (
    AlvexRecoveryValidator()
)


# ------------------------------------------------------------
# 9. RESTORE SAFETY SERVICE
# ------------------------------------------------------------

class AlvexRecoveryService:

    def prepare_restore(
        self,
        db,
        backup_id
    ):

        record = alvex_backup_repository.get(
            db,
            backup_id
        )

        if not record:

            raise HTTPException(
                status_code=404,
                detail="Backup not found."
            )

        path = (
            ALVEX_BACKUP_ROOT
            / record.filename
        ).resolve()

        if not alvex_backup_hash_service.verify_file(
            path,
            record.sha256_hash
        ):

            raise HTTPException(
                status_code=400,
                detail="Backup integrity verification failed."
            )

        if not alvex_recovery_validator.validate_backup(
            path
        ):

            raise HTTPException(
                status_code=400,
                detail="SQLite backup validation failed."
            )

        return {

            "backup_id": backup_id,

            "restore_ready": True,

            "message": (
                "Backup passed integrity and database checks. "
                "Live database replacement is not performed by this endpoint."
            )

        }


alvex_recovery_service = AlvexRecoveryService()


