@app.delete("/api/admin/backups/{backup_id}")
def alvex_delete_backup(
    backup_id: str,
    db: Session = Depends(get_db),
    user=Depends(get_current_user)
):

    alvex_backup_require_admin(user)

    record = alvex_backup_repository.get(
        db,
        backup_id
    )

    if not record:

        raise HTTPException(
            status_code=404,
            detail="Backup not found."
        )

    path = (
        ALVEX_BACKUP_ROOT
        / record.filename
    ).resolve()

    if not path.is_relative_to(
        ALVEX_BACKUP_ROOT
    ):

        raise HTTPException(
            status_code=403,
            detail="Invalid backup path."
        )

    path.unlink(
        missing_ok=True
    )

    alvex_backup_repository.delete(
        db,
        record
    )

    return {
        "success": True,
        "message": "Backup deleted."
    }


