# ------------------------------------------------------------

@app.get("/api/admin/backups/health")
def alvex_backup_health(
    db: Session = Depends(get_db),
    user=Depends(get_current_user)
):

    alvex_backup_require_admin(user)

    total = (
        db.query(AlvexBackupRecord)
        .count()
    )

    completed = (
        db.query(AlvexBackupRecord)
        .filter(
            AlvexBackupRecord.status.in_(
                ["completed", "verified"]
            )
        )
        .count()
    )

    total_size = (
        db.query(
            func.coalesce(
                func.sum(
                    AlvexBackupRecord.file_size
                ),
                0
            )
        ).scalar()
    )

    return {

        "service": "ALVEX Backup Engine",

        "version": ALVEX_BACKUP_CONFIG[
            "version"
        ],

        "status": "available",

        "backup_count": total,

        "completed_backups": completed,

        "total_size_bytes": total_size,

        "backup_directory_exists": (
            ALVEX_BACKUP_ROOT.exists()
        ),

        "automatic_backup_enabled": (
            ALVEX_BACKUP_CONFIG[
                "automatic_backup_enabled"
            ]
        )

    }


