# ------------------------------------------------------------
# 4. SYSTEM METRICS COLLECTOR
# ------------------------------------------------------------

class AlvexSystemMetricsCollector:

    def collect(self):

        metrics = {

            "cpu_percent": None,

            "memory_percent": None,

            "disk_percent": None,

            "process_id": os.getpid(),

            "platform": platform.platform(),

            "python_version": platform.python_version(),

            "timestamp": datetime.utcnow().isoformat()

        }

        try:

            import psutil

            metrics["cpu_percent"] = (
                psutil.cpu_percent(interval=None)
            )

            metrics["memory_percent"] = (
                psutil.virtual_memory().percent
            )

            metrics["disk_percent"] = (
                psutil.disk_usage(
                    str(Path.cwd())
                ).percent
            )

            process = psutil.Process(
                os.getpid()
            )

            metrics["process_memory_mb"] = round(
                process.memory_info().rss
                / (1024 * 1024),
                2
            )

            metrics["process_threads"] = (
                process.num_threads()
            )

        except ImportError:

            metrics["psutil_available"] = False

        except Exception:

            logging.exception(
                "System metrics collection failed."
            )

        return metrics


alvex_system_metrics_collector = (
    AlvexSystemMetricsCollector()
)


# ------------------------------------------------------------
# 5. METRIC REPOSITORY
# ------------------------------------------------------------

class AlvexMetricRepository:

    def create(
        self,
        db,
        name,
        value,
        unit=None,
        source=None
    ):

        record = AlvexMonitoringMetric(

            metric_id=str(uuid.uuid4()),

            metric_name=name,

            metric_value=value,

            metric_unit=unit,

            source=source

        )

        db.add(record)
        db.commit()
        db.refresh(record)

        return record

    def latest(
        self,
        db,
        limit=100
    ):

        return (
            db.query(AlvexMonitoringMetric)
            .order_by(
                AlvexMonitoringMetric.created_at.desc()
            )
            .limit(limit)
            .all()
        )

    def get_by_name(
        self,
        db,
        name,
        hours=24
    ):

        start_time = (
            datetime.utcnow()
            - timedelta(hours=hours)
        )

        return (
            db.query(AlvexMonitoringMetric)
            .filter(
                AlvexMonitoringMetric.metric_name == name,
                AlvexMonitoringMetric.created_at >= start_time
            )
            .order_by(
                AlvexMonitoringMetric.created_at.asc()
            )
            .all()
        )


alvex_metric_repository = AlvexMetricRepository()


# ------------------------------------------------------------
# 6. ERROR TRACKING SERVICE
# ------------------------------------------------------------

class AlvexErrorTrackingService:

    def record(
        self,
        db,
        error_type,
        message,
        endpoint=None,
        severity="error"
    ):

        message = str(message)[
            :ALVEX_MONITORING_CONFIG[
                "maximum_error_message_length"
            ]
        ]

        record = AlvexMonitoringError(

            error_id=str(uuid.uuid4()),

            error_type=error_type,

            message=message,

            endpoint=endpoint,

            severity=severity

        )

        db.add(record)
        db.commit()
        db.refresh(record)

        logging.error(
            "ALVEX error recorded: %s",
            error_type
        )

        return record

    def list_errors(
        self,
        db,
        limit=100,
        unresolved_only=False
    ):

        query = db.query(
            AlvexMonitoringError
        )

        if unresolved_only:

            query = query.filter(
                AlvexMonitoringError.resolved == False
            )

        return (
            query.order_by(
                AlvexMonitoringError.created_at.desc()
            )
            .limit(limit)
            .all()
        )

    def resolve(
        self,
        db,
        error_id
    ):

        record = (
            db.query(AlvexMonitoringError)
            .filter(
                AlvexMonitoringError.error_id
                == error_id
            )
            .first()
        )

        if not record:

            raise HTTPException(
                status_code=404,
                detail="Error record not found."
            )

        record.resolved = True

        record.resolved_at = datetime.utcnow()

        db.commit()

        return record


alvex_error_tracking = AlvexErrorTrackingService()


# ------------------------------------------------------------
# 7. ALERT ENGINE
# ------------------------------------------------------------

class AlvexAlertEngine:

    def create_alert(
        self,
        db,
        title,
        message,
        severity="warning"
    ):

        existing = (
            db.query(AlvexMonitoringAlert)
            .filter(
                AlvexMonitoringAlert.title == title,
                AlvexMonitoringAlert.status == "active"
            )
            .first()
        )

        if existing:
            return existing

        alert = AlvexMonitoringAlert(

            alert_id=str(uuid.uuid4()),

            title=title,

            message=message,

            severity=severity

        )

        db.add(alert)
        db.commit()
        db.refresh(alert)

        return alert

    def acknowledge(
        self,
        db,
        alert_id,
        user_id
    ):

        alert = (
            db.query(AlvexMonitoringAlert)
            .filter(
                AlvexMonitoringAlert.alert_id
                == alert_id
            )
            .first()
        )

        if not alert:

            raise HTTPException(
                status_code=404,
                detail="Alert not found."
            )

        alert.status = "acknowledged"

        alert.acknowledged_at = datetime.utcnow()

        alert.acknowledged_by = user_id

        db.commit()

        return alert

    def evaluate_metrics(
        self,
        db,
        metrics
    ):

        thresholds = {

            "cpu_percent": (
                ALVEX_MONITORING_CONFIG[
                    "cpu_warning_percent"
                ]
            ),

            "memory_percent": (
                ALVEX_MONITORING_CONFIG[
                    "memory_warning_percent"
                ]
            ),

            "disk_percent": (
                ALVEX_MONITORING_CONFIG[
                    "disk_warning_percent"
                ]
            )

        }

        generated = []

        for name, threshold in thresholds.items():

            value = metrics.get(name)

            if value is None:
                continue

            if value >= threshold:

                alert = self.create_alert(

                    db=db,

                    title=f"High {name}",

                    message=(
                        f"{name} is at {value}%. "
                        f"Configured threshold: {threshold}%."
                    ),

                    severity="critical"

                )

                generated.append(
                    alert.alert_id
                )

        return generated


alvex_alert_engine = AlvexAlertEngine()


# ------------------------------------------------------------
# 8. SERVICE HEALTH REGISTRY
# ------------------------------------------------------------

class AlvexServiceHealthRegistry:

    DEFAULT_SERVICES = [

        "database",

        "ai_gateway",

        "document_storage",

        "backup_engine",

        "monitoring"

    ]

    def check_database(self, db):

        db.execute(
            __import__("sqlalchemy").text(
                "SELECT 1"
            )
        )

        return True

    def check_service(
        self,
        db,
        service_name
    ):

        started = time.perf_counter()

        error = None

        try:

            if service_name == "database":

                self.check_database(db)

            elif service_name == "ai_gateway":

                if "alvex_ai_gateway" not in globals():

                    raise RuntimeError(
                        "AI gateway is unavailable."
                    )

            elif service_name == "document_storage":

                if not Path(
                    "storage/alvex_documents"
                ).exists():

                    raise RuntimeError(
                        "Document storage directory is missing."
                    )

            elif service_name == "backup_engine":

                if not ALVEX_BACKUP_ROOT.exists():

                    raise RuntimeError(
                        "Backup directory is missing."
                    )

            elif service_name == "monitoring":

                if not ALVEX_MONITORING_ROOT.exists():

                    raise RuntimeError(
                        "Monitoring directory is missing."
                    )

            else:

                raise ValueError(
                    "Unknown service."
                )

            status = "healthy"

        except Exception as exc:

            status = "unhealthy"

            error = str(exc)[:1000]

        elapsed = (
            time.perf_counter() - started
        ) * 1000

        record = (
            db.query(AlvexMonitoringService)
            .filter(
                AlvexMonitoringService.service_name
                == service_name
            )
            .first()
        )

        if not record:

            record = AlvexMonitoringService(

                service_id=str(uuid.uuid4()),

                service_name=service_name

            )

            db.add(record)

        record.status = status

        record.response_time_ms = round(
            elapsed,
            2
        )

        record.last_checked_at = datetime.utcnow()

        record.last_error = error

        db.commit()

        return {

            "service": service_name,

            "status": status,

            "response_time_ms": round(
                elapsed,
                2
            ),

            "error": error

        }

    def check_all(self, db):

        return [

            self.check_service(
                db,
                service_name
            )

            for service_name in self.DEFAULT_SERVICES

        ]


alvex_service_health_registry = (
    AlvexServiceHealthRegistry()
)


# ------------------------------------------------------------
# 9. PERFORMANCE ANALYZER
# ------------------------------------------------------------

class AlvexPerformanceAnalyzer:

    def analyze(
        self,
        db,
        hours=24
    ):

        start = (
            datetime.utcnow()
            - timedelta(hours=hours)
        )

        records = (
            db.query(AlvexAPIPerformance)
            .filter(
                AlvexAPIPerformance.created_at >= start
            )
            .all()
        )

        if not records:

            return {

                "request_count": 0,

                "average_latency_ms": 0,

                "maximum_latency_ms": 0,

                "minimum_latency_ms": 0

            }

        latencies = [

            float(item.response_time_ms)

            for item in records

        ]

        return {

            "request_count": len(latencies),

            "average_latency_ms": round(
                sum(latencies) / len(latencies),
                2
            ),

            "maximum_latency_ms": max(
                latencies
            ),

            "minimum_latency_ms": min(
                latencies
            )

        }


alvex_performance_analyzer = (
    AlvexPerformanceAnalyzer()
)


