# ------------------------------------------------------------
# 4. PREFERENCE MANAGER
# ------------------------------------------------------------

class AlvexNotificationPreferenceManager:

    def get_or_create(
        self,
        db,
        user_id
    ):

        preference = (
            db.query(AlvexNotificationPreference)
            .filter(
                AlvexNotificationPreference.user_id
                == user_id
            )
            .first()
        )

        if preference:
            return preference

        preference = AlvexNotificationPreference(
            user_id=user_id
        )

        db.add(preference)
        db.commit()
        db.refresh(preference)

        return preference

    def update(
        self,
        db,
        user_id,
        data
    ):

        preference = self.get_or_create(
            db,
            user_id
        )

        values = data.model_dump()

        for key, value in values.items():

            setattr(
                preference,
                key,
                value
            )

        preference.updated_at = datetime.utcnow()

        db.commit()
        db.refresh(preference)

        return preference

    def allows(
        self,
        preference,
        event_type,
        channel
    ):

        if channel == "in_app":

            if not preference.in_app_enabled:
                return False

        elif channel == "email":

            if not preference.email_enabled:
                return False

        else:

            return False

        if event_type == "security":

            return preference.security_alerts

        if event_type == "system":

            return preference.system_updates

        if event_type == "product":

            return preference.product_updates

        return True


alvex_notification_preferences = (
    AlvexNotificationPreferenceManager()
)


# ------------------------------------------------------------
# 5. NOTIFICATION REPOSITORY
# ------------------------------------------------------------

class AlvexNotificationRepository:

    def create(
        self,
        db,
        user_id,
        title,
        message,
        event_type,
        priority,
        channel
    ):

        event = AlvexEventDelivery(

            event_id=str(uuid.uuid4()),

            user_id=user_id,

            title=title,

            message=message,

            event_type=event_type,

            priority=priority,

            channel=channel,

            status="pending",

            attempts=0,

            next_attempt_at=datetime.utcnow()

        )

        db.add(event)
        db.commit()
        db.refresh(event)

        return event

    def get_user_event(
        self,
        db,
        user_id,
        event_id
    ):

        return (
            db.query(AlvexEventDelivery)
            .filter(
                AlvexEventDelivery.event_id == event_id,
                AlvexEventDelivery.user_id == user_id
            )
            .first()
        )

    def list_user_events(
        self,
        db,
        user_id,
        limit=50,
        unread_only=False
    ):

        query = (
            db.query(AlvexEventDelivery)
            .filter(
                AlvexEventDelivery.user_id == user_id,
                AlvexEventDelivery.channel == "in_app"
            )
        )

        if unread_only:

            query = query.filter(
                AlvexEventDelivery.read_at.is_(None)
            )

        return (
            query.order_by(
                AlvexEventDelivery.created_at.desc()
            )
            .limit(limit)
            .all()
        )

    def pending(
        self,
        db,
        limit=50
    ):

        now = datetime.utcnow()

        return (
            db.query(AlvexEventDelivery)
            .filter(
                AlvexEventDelivery.status == "pending",
                or_(
                    AlvexEventDelivery.next_attempt_at.is_(None),
                    AlvexEventDelivery.next_attempt_at <= now
                )
            )
            .order_by(
                AlvexEventDelivery.created_at.asc()
            )
            .limit(limit)
            .all()
        )


alvex_notification_repository = (
    AlvexNotificationRepository()
)


