# ------------------------------------------------------------
# 7. EMAIL DELIVERY PROVIDER
# ------------------------------------------------------------

class AlvexEmailProvider:

    def is_configured(self):

        required = [

            ALVEX_NOTIFICATION_CONFIG[
                "smtp_host"
            ],

            ALVEX_NOTIFICATION_CONFIG[
                "smtp_username"
            ],

            ALVEX_NOTIFICATION_CONFIG[
                "smtp_password"
            ],

            ALVEX_NOTIFICATION_CONFIG[
                "smtp_sender"
            ]

        ]

        return all(required)

    def send(
        self,
        recipient,
        subject,
        body
    ):

        if not self.is_configured():

            raise RuntimeError(
                "SMTP provider is not configured."
            )

        if not recipient or "@" not in recipient:

            raise ValueError(
                "Invalid recipient email address."
            )

        message = EmailMessage()

        message["From"] = (
            ALVEX_NOTIFICATION_CONFIG[
                "smtp_sender"
            ]
        )

        message["To"] = recipient

        message["Subject"] = subject

        message.set_content(body)

        host = ALVEX_NOTIFICATION_CONFIG[
            "smtp_host"
        ]

        port = ALVEX_NOTIFICATION_CONFIG[
            "smtp_port"
        ]

        username = ALVEX_NOTIFICATION_CONFIG[
            "smtp_username"
        ]

        password = ALVEX_NOTIFICATION_CONFIG[
            "smtp_password"
        ]

        with smtplib.SMTP(
            host,
            port,
            timeout=15
        ) as server:

            if ALVEX_NOTIFICATION_CONFIG[
                "smtp_use_tls"
            ]:

                server.starttls()

            server.login(
                username,
                password
            )

            server.send_message(
                message
            )

        return True


alvex_email_provider = AlvexEmailProvider()


# ------------------------------------------------------------
# 8. EVENT DELIVERY ENGINE
# ------------------------------------------------------------

class AlvexEventDeliveryEngine:

    def create_user_notification(
        self,
        db,
        user_id,
        title,
        message,
        event_type="general",
        priority="normal"
    ):

        preference = (
            alvex_notification_preferences.get_or_create(
                db,
                user_id
            )
        )

        if not alvex_notification_preferences.allows(
            preference,
            event_type,
            "in_app"
        ):

            return {

                "created": False,

                "reason": "User disabled in-app notifications."

            }

        event = alvex_notification_repository.create(

            db=db,

            user_id=user_id,

            title=title,

            message=message,

            event_type=event_type,

            priority=priority,

            channel="in_app"

        )

        return {

            "created": True,

            "event_id": event.event_id,

            "status": event.status

        }

    def create_email_event(
        self,
        db,
        user_id,
        title,
        message,
        event_type="general"
    ):

        preference = (
            alvex_notification_preferences.get_or_create(
                db,
                user_id
            )
        )

        if not alvex_notification_preferences.allows(
            preference,
            event_type,
            "email"
        ):

            return {

                "created": False,

                "reason": "Email notifications are disabled."

            }

        event = alvex_notification_repository.create(

            db=db,

            user_id=user_id,

            title=title,

            message=message,

            event_type=event_type,

            priority="normal",

            channel="email"

        )

        return {

            "created": True,

            "event_id": event.event_id,

            "status": event.status

        }

    def deliver_email(
        self,
        db,
        event
    ):

        user = (
            db.query(User)
            .filter(
                User.id == event.user_id
            )
            .first()
        )

        if not user:

            raise RuntimeError(
                "Notification recipient does not exist."
            )

        recipient = getattr(
            user,
            "email",
            None
        )

        if not recipient:

            raise RuntimeError(
                "Recipient email is unavailable."
            )

        alvex_email_provider.send(
            recipient=recipient,
            subject=event.title,
            body=event.message
        )

        return True

    def process_event(
        self,
        db,
        event
    ):

        try:

            if event.channel == "email":

                self.deliver_email(
                    db,
                    event
                )

            elif event.channel == "in_app":

                pass

            else:

                raise ValueError(
                    "Unsupported delivery channel."
                )

            event.status = "delivered"

            event.delivered_at = datetime.utcnow()

            event.last_error = None

            db.commit()

            alvex_notification_logs.write(
                db,
                event,
                "delivered"
            )

            return True

        except Exception as exc:

            event.attempts += 1

            event.last_error = str(exc)[:2000]

            if event.attempts >= (
                ALVEX_NOTIFICATION_CONFIG[
                    "maximum_attempts"
                ]
            ):

                event.status = "failed"

            else:

                event.status = "pending"

                delay = (
                    ALVEX_NOTIFICATION_CONFIG[
                        "retry_delay_seconds"
                    ]
                    * (2 ** (event.attempts - 1))
                )

                event.next_attempt_at = (
                    datetime.utcnow()
                    + timedelta(seconds=delay)
                )

            db.commit()

            alvex_notification_logs.write(
                db,
                event,
                "failed",
                str(exc)
            )

            return False

    def process_pending(
        self,
        db,
        limit=50
    ):

        events = (
            alvex_notification_repository.pending(
                db,
                limit
            )
        )

        results = {

            "processed": 0,

            "delivered": 0,

            "failed": 0

        }

        for event in events:

            results["processed"] += 1

            if self.process_event(
                db,
                event
            ):

                results["delivered"] += 1

            else:

                results["failed"] += 1

        return results


alvex_event_delivery_engine = (
    AlvexEventDeliveryEngine()
)


