Base.metadata.create_all(bind=engine)


# ------------------------------------------------------------
# 3. SEARCH SCHEMAS
# ------------------------------------------------------------

class AlvexSearchRequest(BaseModel):

    query: str = Field(
        min_length=2,
        max_length=300
    )

    search_type: str = Field(
        default="all",
        pattern="^(all|conversations|documents|messages|memory)$"
    )

    limit: int = Field(
        default=20,
        ge=1,
        le=100
    )

    offset: int = Field(
        default=0,
        ge=0,
        le=10000
    )

    sort_order: str = Field(
        default="newest",
        pattern="^(newest|oldest|relevance)$"
    )


class AlvexSearchIndexRequest(BaseModel):

    source_type: str = Field(
        min_length=2,
        max_length=50
    )

    source_id: str = Field(
        min_length=1,
        max_length=100
    )

    title: Optional[str] = Field(
        default=None,
        max_length=500
    )

    content: str = Field(
        min_length=1,
        max_length=50000
    )


# ------------------------------------------------------------
# 4. QUERY PROCESSOR
# ------------------------------------------------------------

class AlvexSearchQueryProcessor:

    STOP_WORDS = {

        "the",
        "and",
        "for",
        "with",
        "that",
        "this",
        "from",
        "have",
        "what",
        "when",
        "where",
        "how",
        "are",
        "was",
        "were",
        "you",
        "your",
        "bir",
        "ve",
        "ile",
        "için",
        "ama",
        "fakat",
        "şu",
        "bu",
        "ne",
        "nasıl",
        "neden",
        "hangi"

    }

    def normalize(self, query):

        query = str(query).strip().lower()

        query = re.sub(
            r"\s+",
            " ",
            query
        )

        query = re.sub(
            r"[^\w\s-]",
            " ",
            query,
            flags=re.UNICODE
        )

        return query.strip()

    def tokenize(self, query):

        normalized = self.normalize(
            query
        )

        words = normalized.split()

        return [

            word

            for word in words

            if (
                len(word) >= 2
                and word not in self.STOP_WORDS
            )

        ]

    def validate(self, query):

        normalized = self.normalize(
            query
        )

        if len(normalized) < (
            ALVEX_SEARCH_CONFIG[
                "minimum_query_length"
            ]
        ):

            raise HTTPException(
                status_code=400,
                detail="Search query is too short."
            )

        if len(normalized) > (
            ALVEX_SEARCH_CONFIG[
                "maximum_query_length"
            ]
        ):

            raise HTTPException(
                status_code=400,
                detail="Search query is too long."
            )

        return normalized


alvex_search_query_processor = (
    AlvexSearchQueryProcessor()
)


# ------------------------------------------------------------
# 5. RELEVANCE SCORER
# ------------------------------------------------------------

class AlvexSearchRelevanceScorer:

    def score(
        self,
        query,
        title,
        content
    ):

        terms = (
            alvex_search_query_processor.tokenize(
                query
            )
        )

        if not terms:
            return 0.0

        title_text = (
            title or ""
        ).lower()

        content_text = (
            content or ""
        ).lower()

        score = 0.0

        for term in terms:

            title_count = title_text.count(
                term
            )

            content_count = content_text.count(
                term
            )

            score += title_count * 4

            score += min(
                content_count,
                20
            )

            if title_text.startswith(term):

                score += 2

        if query.lower() in title_text:

            score += 10

        if query.lower() in content_text:

            score += 5

        return round(
            score,
            4
        )


alvex_search_relevance_scorer = (
    AlvexSearchRelevanceScorer()
)


# ------------------------------------------------------------
# 6. SNIPPET GENERATOR
# ------------------------------------------------------------

class AlvexSearchSnippetGenerator:

    def generate(
        self,
        content,
        query,
        maximum_length=250
    ):

        content = str(
            content or ""
        )

        if len(content) <= maximum_length:

            return content

        terms = (
            alvex_search_query_processor.tokenize(
                query
            )
        )

        lower_content = content.lower()

        positions = [

            lower_content.find(term)

            for term in terms

            if lower_content.find(term) >= 0

        ]

        if not positions:

            return (
                content[:maximum_length]
                + "..."
            )

        start = max(
            0,
            min(positions) - 60
        )

        end = min(
            len(content),
            start + maximum_length
        )

        prefix = (
            "..."
            if start > 0 else ""
        )

        suffix = (
            "..."
            if end < len(content) else ""
        )

        return (
            prefix
            + content[start:end]
            + suffix
        )


alvex_search_snippet_generator = (
    AlvexSearchSnippetGenerator()
)


# ------------------------------------------------------------
# 7. INDEX REPOSITORY
# ------------------------------------------------------------

class AlvexSearchIndexRepository:

    def upsert(
        self,
        db,
        user_id,
        source_type,
        source_id,
        title,
        content
    ):

        digest = hashlib.sha256(
            content.encode("utf-8")
        ).hexdigest()

        record = (
            db.query(AlvexSearchIndex)
            .filter(
                AlvexSearchIndex.user_id == user_id,
                AlvexSearchIndex.source_type == source_type,
                AlvexSearchIndex.source_id == source_id
            )
            .first()
        )

        if record:

            if record.content_hash == digest:

                return record

            record.title = title

            record.content = content

            record.content_hash = digest

            record.updated_at = datetime.utcnow()

        else:

            record = AlvexSearchIndex(

                index_id=str(uuid.uuid4()),

                user_id=user_id,

                source_type=source_type,

                source_id=source_id,

                title=title,

                content=content,

                content_hash=digest

            )

            db.add(record)

        db.commit()
        db.refresh(record)

        return record

    def delete(
        self,
        db,
        user_id,
        source_type,
        source_id
    ):

        record = (
            db.query(AlvexSearchIndex)
            .filter(
                AlvexSearchIndex.user_id == user_id,
                AlvexSearchIndex.source_type == source_type,
                AlvexSearchIndex.source_id == source_id
            )
            .first()
        )

        if not record:
            return False

        db.delete(record)
        db.commit()

        return True


alvex_search_index_repository = (
    AlvexSearchIndexRepository()
)


# ------------------------------------------------------------
# 8. SEARCH HISTORY SERVICE
# ------------------------------------------------------------

class AlvexSearchHistoryService:

    def save(
        self,
        db,
        user_id,
        query,
        search_type,
        result_count
    ):

        record = AlvexSearchHistory(

            search_id=str(uuid.uuid4()),

            user_id=user_id,

            query=query,

            search_type=search_type,

            result_count=result_count

        )

        db.add(record)
        db.commit()

        self.cleanup(
            db,
            user_id
        )

        return record

    def cleanup(
        self,
        db,
        user_id
    ):

        records = (
            db.query(AlvexSearchHistory)
            .filter(
                AlvexSearchHistory.user_id == user_id
            )
            .order_by(
                AlvexSearchHistory.created_at.desc()
            )
            .all()
        )

        maximum = ALVEX_SEARCH_CONFIG[
            "maximum_history"
        ]

        for record in records[maximum:]:

            db.delete(record)

        db.commit()

    def list_history(
        self,
        db,
        user_id,
        limit=50
    ):

        return (
            db.query(AlvexSearchHistory)
            .filter(
                AlvexSearchHistory.user_id == user_id
            )
            .order_by(
                AlvexSearchHistory.created_at.desc()
            )
            .limit(limit)
            .all()
        )


alvex_search_history_service = (
    AlvexSearchHistoryService()
)


# ------------------------------------------------------------
# 9. UNIFIED SEARCH ENGINE
# ------------------------------------------------------------

class AlvexUnifiedSearchEngine:

    def search_indexes(
        self,
        db,
        user_id,
        query,
        limit,
        offset,
        sort_order
    ):

        normalized = (
            alvex_search_query_processor.validate(
                query
            )
        )

        terms = (
            alvex_search_query_processor.tokenize(
                normalized
            )
        )

        if not terms:

            return []

        filters = [

            AlvexSearchIndex.user_id == user_id

        ]

        term_filters = []

        for term in terms:

            pattern = f"%{term}%"

            term_filters.append(

                or_(

                    AlvexSearchIndex.title.ilike(
                        pattern
                    ),

                    AlvexSearchIndex.content.ilike(
                        pattern
                    )

                )

            )

        query_builder = (
            db.query(AlvexSearchIndex)
            .filter(
                *filters,
                or_(*term_filters)
            )
        )

        if sort_order == "newest":

            query_builder = query_builder.order_by(
                AlvexSearchIndex.updated_at.desc()
            )

        elif sort_order == "oldest":

            query_builder = query_builder.order_by(
                AlvexSearchIndex.updated_at.asc()
            )

        records = (
            query_builder
            .offset(offset)
            .limit(limit)
            .all()
        )

        results = []

        for record in records:

            score = (
                alvex_search_relevance_scorer.score(

                    normalized,

                    record.title,

                    record.content

                )
            )

            results.append({

                "source_type": record.source_type,

                "source_id": record.source_id,

                "title": record.title,

                "snippet": (
                    alvex_search_snippet_generator.generate(
                        record.content,
                        normalized
                    )
                ),

                "score": score,

                "updated_at": record.updated_at

            })

        if sort_order == "relevance":

            results.sort(
                key=lambda item: item["score"],
                reverse=True
            )

        return results

    def search(
        self,
        db,
        user_id,
        request
    ):

        normalized = (
            alvex_search_query_processor.validate(
                request.query
            )
        )

        query_builder = (
            db.query(AlvexSearchIndex)
            .filter(
                AlvexSearchIndex.user_id == user_id
            )
        )

        if request.search_type != "all":

            query_builder = query_builder.filter(
                AlvexSearchIndex.source_type
                == request.search_type
            )

        terms = (
            alvex_search_query_processor.tokenize(
                normalized
            )
        )

        if not terms:

            results = []

        else:

            conditions = [

                or_(

                    AlvexSearchIndex.title.ilike(
                        f"%{term}%"
                    ),

                    AlvexSearchIndex.content.ilike(
                        f"%{term}%"
                    )

                )

                for term in terms

            ]

            query_builder = query_builder.filter(
                or_(*conditions)
            )

            total = query_builder.count()

            records = (
                query_builder
                .offset(request.offset)
                .limit(request.limit)
                .all()
            )

            results = [

                {

                    "source_type": record.source_type,

                    "source_id": record.source_id,

                    "title": record.title,

                    "snippet": (
                        alvex_search_snippet_generator.generate(
                            record.content,
                            normalized
                        )
                    ),

                    "score": (
                        alvex_search_relevance_scorer.score(
                            normalized,
                            record.title,
                            record.content
                        )
                    ),

                    "updated_at": record.updated_at

                }

                for record in records

            ]

            if request.sort_order == "relevance":

                results.sort(
                    key=lambda item: item["score"],
                    reverse=True
                )

            elif request.sort_order == "newest":

                results.sort(
                    key=lambda item: (
                        item["updated_at"]
                        or datetime.min
                    ),
                    reverse=True
                )

            elif request.sort_order == "oldest":

                results.sort(
                    key=lambda item: (
                        item["updated_at"]
                        or datetime.min
                    )
                )

        if not terms:

            total = 0

        alvex_search_history_service.save(

            db=db,

            user_id=user_id,

            query=normalized,

            search_type=request.search_type,

            result_count=len(results)

        )

        return {

            "query": normalized,

            "search_type": request.search_type,

            "count": len(results),

            "total": total,

            "offset": request.offset,

            "limit": request.limit,

            "results": results

        }


alvex_unified_search_engine = (
    AlvexUnifiedSearchEngine()
)


# ------------------------------------------------------------
# 10. SEARCH INDEXING SERVICE
# ------------------------------------------------------------

class AlvexSearchIndexingService:

    ALLOWED_SOURCE_TYPES = {

        "documents",

        "conversations",

        "messages",

        "memory"

    }

    def index_content(
        self,
        db,
        user_id,
        request
    ):

        if request.source_type not in (
            self.ALLOWED_SOURCE_TYPES
        ):

            raise HTTPException(
                status_code=400,
                detail="Unsupported source type."
            )

        return alvex_search_index_repository.upsert(

            db=db,

            user_id=user_id,

            source_type=request.source_type,

            source_id=request.source_id,

            title=request.title,

            content=request.content

        )

    def remove_index(
        self,
        db,
        user_id,
        source_type,
        source_id
    ):

        return alvex_search_index_repository.delete(

            db,

            user_id,

            source_type,

            source_id

        )


alvex_search_indexing_service = (
    AlvexSearchIndexingService()
)


