# ------------------------------------------------------------
# 1. DEVELOPER PLATFORM CONFIGURATION
# ------------------------------------------------------------

ALVEX_DEVELOPER_CONFIG = {

    "platform_name": "ALVEX Developer Platform",

    "version": "1.0.0",

    "api_prefix": "/api/v1",

    "default_api_version": "v1",

    "supported_versions": [
        "v1"
    ],

    "maximum_api_keys": 10,

    "maximum_request_size": 2 * 1024 * 1024,

    "sdk_name": "alvex-python",

    "sdk_version": "1.0.0",

    "documentation_enabled": True,

    "developer_portal_enabled": True

}


# ------------------------------------------------------------
# 2. API VERSION REGISTRY
# ------------------------------------------------------------

class AlvexAPIVersionRegistry:

    def __init__(self):

        self.versions = {

            "v1": {

                "status": "stable",

                "released": "2026-01-01",

                "deprecated": False,

                "prefix": "/api/v1"

            }

        }

    def get_version(self, version):

        return self.versions.get(
            version
        )

    def is_supported(self, version):

        return version in self.versions

    def list_versions(self):

        return [

            {

                "version": key,

                **value

            }

            for key, value in self.versions.items()

        ]

    def register_version(
        self,
        version,
        prefix,
        status="development"
    ):

        if not version.startswith("v"):

            raise ValueError(
                "Version must start with v."
            )

        if version in self.versions:

            raise ValueError(
                "Version already exists."
            )

        self.versions[version] = {

            "status": status,

            "released": None,

            "deprecated": False,

            "prefix": prefix

        }

        return self.versions[version]


alvex_api_version_registry = (
    AlvexAPIVersionRegistry()
)


# ------------------------------------------------------------
# 3. API RESPONSE STANDARD
# ------------------------------------------------------------

class AlvexAPIResponse:

    @staticmethod
    def success(
        data=None,
        message="Request completed successfully",
        request_id=None
    ):

        return {

            "success": True,

            "message": message,

            "request_id": (
                request_id
                or str(uuid.uuid4())
            ),

            "timestamp": datetime.utcnow().isoformat(),

            "data": data

        }

    @staticmethod
    def error(
        message,
        code="ALVEX_ERROR",
        request_id=None
    ):

        return {

            "success": False,

            "error": {

                "code": code,

                "message": message

            },

            "request_id": (
                request_id
                or str(uuid.uuid4())
            ),

            "timestamp": datetime.utcnow().isoformat()

        }


