# ------------------------------------------------------------
# 7. APPLICATION MANAGER
# ------------------------------------------------------------

class AlvexDeveloperApplicationManager:

    def create(
        self,
        db,
        user_id,
        request
    ):

        count = (
            db.query(AlvexDeveloperApplication)
            .filter(
                AlvexDeveloperApplication.user_id
                == user_id
            )
            .count()
        )

        if count >= 20:

            raise HTTPException(
                status_code=400,
                detail="Application limit reached."
            )

        application = AlvexDeveloperApplication(

            application_id=str(uuid.uuid4()),

            user_id=user_id,

            name=request.name,

            description=request.description,

            website=request.website,

            status="active"

        )

        db.add(application)
        db.commit()
        db.refresh(application)

        return application

    def get(
        self,
        db,
        user_id,
        application_id
    ):

        application = (
            db.query(AlvexDeveloperApplication)
            .filter(
                AlvexDeveloperApplication.application_id
                == application_id,
                AlvexDeveloperApplication.user_id
                == user_id
            )
            .first()
        )

        if not application:

            raise HTTPException(
                status_code=404,
                detail="Application not found."
            )

        return application

    def list(
        self,
        db,
        user_id
    ):

        return (
            db.query(AlvexDeveloperApplication)
            .filter(
                AlvexDeveloperApplication.user_id
                == user_id
            )
            .order_by(
                AlvexDeveloperApplication.created_at.desc()
            )
            .all()
        )

    def delete(
        self,
        db,
        user_id,
        application_id
    ):

        application = self.get(
            db,
            user_id,
            application_id
        )

        application.status = "disabled"

        db.commit()

        return application


alvex_developer_application_manager = (
    AlvexDeveloperApplicationManager()
)


# ------------------------------------------------------------
# 8. SDK REGISTRATION SERVICE
# ------------------------------------------------------------

class AlvexSDKRegistrationService:

    SUPPORTED_LANGUAGES = {

        "python",

        "javascript",

        "typescript"

    }

    def register(
        self,
        db,
        user_id,
        request
    ):

        application = (
            alvex_developer_application_manager.get(

                db,

                user_id,

                request.application_id

            )
        )

        if application.status != "active":

            raise HTTPException(
                status_code=403,
                detail="Application is disabled."
            )

        if request.language not in (
            self.SUPPORTED_LANGUAGES
        ):

            raise HTTPException(
                status_code=400,
                detail="Unsupported SDK language."
            )

        registration = AlvexSDKRegistration(

            sdk_id=str(uuid.uuid4()),

            user_id=user_id,

            application_id=request.application_id,

            language=request.language,

            sdk_version=request.sdk_version

        )

        db.add(registration)
        db.commit()
        db.refresh(registration)

        return registration


alvex_sdk_registration_service = (
    AlvexSDKRegistrationService()
)


