# ------------------------------------------------------------
# 11. API REQUEST VALIDATOR
# ------------------------------------------------------------

class AlvexDeveloperRequestValidator:

    def validate_content_length(
        self,
        content_length
    ):

        if content_length is None:

            return True

        try:

            size = int(content_length)

        except (TypeError, ValueError):

            raise HTTPException(
                status_code=400,
                detail="Invalid content length."
            )

        if size < 0:

            raise HTTPException(
                status_code=400,
                detail="Invalid content length."
            )

        if size > ALVEX_DEVELOPER_CONFIG[
            "maximum_request_size"
        ]:

            raise HTTPException(
                status_code=413,
                detail="Request payload too large."
            )

        return True

    def validate_version(
        self,
        version
    ):

        if not alvex_api_version_registry.is_supported(
            version
        ):

            raise HTTPException(
                status_code=400,
                detail="Unsupported API version."
            )

        return True


alvex_developer_request_validator = (
    AlvexDeveloperRequestValidator()
)


# ------------------------------------------------------------
# 12. REQUEST IDENTIFICATION MIDDLEWARE
# ------------------------------------------------------------

@app.middleware("http")
async def alvex_developer_request_middleware(
    request: Request,
    call_next
):

    request_id = str(
        uuid.uuid4()
    )

    try:

        alvex_developer_request_validator.validate_content_length(

            request.headers.get(
                "content-length"
            )

        )

        response = await call_next(
            request
        )

        response.headers[
            "X-Alvex-Request-ID"
        ] = request_id

        response.headers[
            "X-Alvex-Platform"
        ] = "ALVEX AI"

        return response

    except HTTPException as exc:

        return JSONResponse(

            status_code=exc.status_code,

            content=AlvexAPIResponse.error(

                message=str(exc.detail),

                code="REQUEST_VALIDATION_ERROR",

                request_id=request_id

            )

        )

    except Exception:

        logging.exception(
            "ALVEX developer middleware error"
        )

        return JSONResponse(

            status_code=500,

            content=AlvexAPIResponse.error(

                message="Internal server error",

                code="INTERNAL_SERVER_ERROR",

                request_id=request_id

            )

        )


