# ------------------------------------------------------------
# 7. MANIFEST VALIDATOR
# ------------------------------------------------------------

class AlvexPluginManifestValidator:

    REQUIRED_FIELDS = {

        "name",

        "version",

        "description",

        "permissions"

    }

    ALLOWED_PERMISSIONS = {

        "ai.generate",

        "documents.read",

        "documents.write",

        "search.read",

        "memory.read",

        "notifications.create"

    }

    def validate(self, manifest):

        if not isinstance(manifest, dict):

            raise HTTPException(
                status_code=400,
                detail="Manifest must be an object."
            )

        missing = (
            self.REQUIRED_FIELDS
            - set(manifest.keys())
        )

        if missing:

            raise HTTPException(
                status_code=400,
                detail={
                    "message": "Missing manifest fields.",
                    "missing": sorted(missing)
                }
            )

        permissions = manifest.get(
            "permissions"
        )

        if not isinstance(permissions, list):

            raise HTTPException(
                status_code=400,
                detail="Permissions must be a list."
            )

        if len(permissions) > 10:

            raise HTTPException(
                status_code=400,
                detail="Too many permissions."
            )

        invalid = (
            set(permissions)
            - self.ALLOWED_PERMISSIONS
        )

        if invalid:

            raise HTTPException(
                status_code=400,
                detail={
                    "message": "Unsupported permissions.",
                    "invalid": sorted(invalid)
                }
            )

        for field in (
            "name",
            "version",
            "description"
        ):

            if not isinstance(
                manifest.get(field),
                str
            ):

                raise HTTPException(
                    status_code=400,
                    detail=f"Invalid manifest field: {field}"
                )

        encoded = json.dumps(
            manifest,
            sort_keys=True,
            ensure_ascii=False
        )

        if len(encoded.encode("utf-8")) > 50000:

            raise HTTPException(
                status_code=413,
                detail="Manifest is too large."
            )

        return manifest


alvex_plugin_manifest_validator = (
    AlvexPluginManifestValidator()
)


