import uuid
import json
import logging
import hashlib

from datetime import datetime
from typing import Optional, Dict, Any, List

from pydantic import BaseModel, Field
from fastapi import Depends, HTTPException, Query


# ------------------------------------------------------------
# 1. CONFIGURATION
# ------------------------------------------------------------

ALVEX_WORKFLOW_CONFIG = {

    "version": "1.0.0",

    "enabled": True,

    "maximum_workflows_per_user": 100,

    "maximum_steps_per_workflow": 30,

    "maximum_execution_time": 120,

    "maximum_retries": 3,

    "supported_triggers": [
        "manual",
        "api",
        "scheduled"
    ],

    "supported_actions": [
        "text_transform",
        "text_analyze",
        "ai_generate",
        "search",
        "condition",
        "save_result"
    ],

    "execution_statuses": [
        "pending",
        "running",
        "completed",
        "failed",
        "cancelled"
    ]

}


# ------------------------------------------------------------
# 2. DATABASE MODELS
# ------------------------------------------------------------

class AlvexWorkflowDefinition(Base):

    __tablename__ = "alvex_workflow_definitions"

    id = Column(Integer, primary_key=True, index=True)

    workflow_id = Column(
        String(100),
        unique=True,
        nullable=False,
        index=True
    )

    user_id = Column(
        Integer,
        ForeignKey("users.id"),
        nullable=False,
        index=True
    )

    name = Column(String(150), nullable=False)

    description = Column(Text, nullable=True)

    trigger_type = Column(
        String(30),
        default="manual"
    )

    steps = Column(Text, nullable=False)

    enabled = Column(Boolean, default=True)

    version = Column(Integer, default=1)

    created_at = Column(
        DateTime,
        default=datetime.utcnow
    )

    updated_at = Column(
        DateTime,
        default=datetime.utcnow,
        onupdate=datetime.utcnow
    )


class AlvexWorkflowExecution(Base):

    __tablename__ = "alvex_workflow_executions"

    id = Column(Integer, primary_key=True, index=True)

    execution_id = Column(
        String(100),
        unique=True,
        nullable=False,
        index=True
    )

    workflow_id = Column(
        String(100),
        nullable=False,
        index=True
    )

    user_id = Column(
        Integer,
        ForeignKey("users.id"),
        nullable=False,
        index=True
    )

    status = Column(
        String(30),
        default="pending",
        index=True
    )

    input_data = Column(Text, nullable=True)

    output_data = Column(Text, nullable=True)

    error_message = Column(Text, nullable=True)

    total_steps = Column(Integer, default=0)

    completed_steps = Column(Integer, default=0)

    started_at = Column(DateTime, nullable=True)

    finished_at = Column(DateTime, nullable=True)

    created_at = Column(
        DateTime,
        default=datetime.utcnow
    )


class AlvexWorkflowStepLog(Base):

    __tablename__ = "alvex_workflow_step_logs"

    id = Column(Integer, primary_key=True, index=True)

    log_id = Column(
        String(100),
        unique=True,
        nullable=False
    )

    execution_id = Column(
        String(100),
        nullable=False,
        index=True
    )

    step_id = Column(String(100), nullable=False)

    action = Column(String(50), nullable=False)

    status = Column(String(30), nullable=False)

    duration_ms = Column(Integer, default=0)

    result_summary = Column(Text, nullable=True)

    created_at = Column(
        DateTime,
        default=datetime.utcnow
    )


Base.metadata.create_all(bind=engine)


# ------------------------------------------------------------
# 3. REQUEST SCHEMAS
# ------------------------------------------------------------

class AlvexWorkflowStepSchema(BaseModel):

    step_id: str = Field(
        min_length=1,
        max_length=100
    )

    action: str = Field(
        min_length=3,
        max_length=50
    )

    parameters: Dict[str, Any] = Field(
        default_factory=dict
    )

    enabled: bool = True


class AlvexWorkflowCreateRequest(BaseModel):

    name: str = Field(
        min_length=3,
        max_length=150
    )

    description: Optional[str] = Field(
        default=None,
        max_length=2000
    )

    trigger_type: str = Field(
        default="manual",
        pattern="^(manual|api|scheduled)$"
    )

    steps: List[AlvexWorkflowStepSchema] = Field(
        min_length=1,
        max_length=30
    )


class AlvexWorkflowExecuteRequest(BaseModel):

    input_data: Dict[str, Any] = Field(
        default_factory=dict
    )


class AlvexWorkflowUpdateRequest(BaseModel):

    name: Optional[str] = Field(
        default=None,
        min_length=3,
        max_length=150
    )

    description: Optional[str] = Field(
        default=None,
        max_length=2000
    )

    enabled: Optional[bool] = None


# ------------------------------------------------------------
# 4. WORKFLOW VALIDATOR
# ------------------------------------------------------------

class AlvexWorkflowValidator:

    ALLOWED_PARAMETER_TYPES = (
        str,
        int,
        float,
        bool,
        dict,
        list,
        type(None)
    )

    def validate_steps(self, steps):

        if not steps:

            raise HTTPException(
                status_code=400,
                detail="Workflow requires at least one step."
            )

        if len(steps) > ALVEX_WORKFLOW_CONFIG[
            "maximum_steps_per_workflow"
        ]:

            raise HTTPException(
                status_code=400,
                detail="Too many workflow steps."
            )

        step_ids = set()

        for step in steps:

            if step.step_id in step_ids:

                raise HTTPException(
                    status_code=400,
                    detail="Duplicate step ID."
                )

            step_ids.add(
                step.step_id
            )

            if step.action not in (
                ALVEX_WORKFLOW_CONFIG[
                    "supported_actions"
                ]
            ):

                raise HTTPException(
                    status_code=400,
                    detail=f"Unsupported action: {step.action}"
                )

            self.validate_parameters(
                step.parameters
            )

        return True

    def validate_parameters(self, parameters):

        if not isinstance(parameters, dict):

            raise HTTPException(
                status_code=400,
                detail="Parameters must be an object."
            )

        try:

            encoded = json.dumps(
                parameters,
                ensure_ascii=False
            )

        except (TypeError, ValueError):

            raise HTTPException(
                status_code=400,
                detail="Invalid workflow parameters."
            )

        if len(encoded.encode("utf-8")) > 20000:

            raise HTTPException(
                status_code=413,
                detail="Workflow parameters too large."
            )

        return True


alvex_workflow_validator = (
    AlvexWorkflowValidator()
)


# ------------------------------------------------------------
# 5. VARIABLE CONTEXT
# ------------------------------------------------------------

class AlvexWorkflowContext:

    def __init__(self, input_data=None):

        self.variables = {

            "input": input_data or {},

            "results": {},

            "metadata": {

                "started_at": datetime.utcnow().isoformat(),

                "platform": "ALVEX AI"

            }

        }

    def set(self, key, value):

        self.variables["results"][key] = value

    def get(self, key, default=None):

        if key == "input":

            return self.variables["input"]

        return self.variables["results"].get(
            key,
            default
        )

    def export(self):

        return self.variables


# ------------------------------------------------------------
# 6. ACTION REGISTRY
# ------------------------------------------------------------

class AlvexWorkflowActionRegistry:

    def __init__(self):

        self.actions = {}

    def register(self, name, handler):

        if name in self.actions:

            raise ValueError(
                "Action already registered."
            )

        if not callable(handler):

            raise TypeError(
                "Handler must be callable."
            )

        self.actions[name] = handler

    def get(self, name):

        return self.actions.get(name)

    def list_actions(self):

        return list(
            self.actions.keys()
        )


alvex_workflow_action_registry = (
    AlvexWorkflowActionRegistry()
)


# ------------------------------------------------------------
# 7. TEXT TRANSFORM ACTION
# ------------------------------------------------------------

def alvex_workflow_text_transform(
    context,
    parameters
):

    source = parameters.get(
        "source",
        "input"
    )

    text_value = context.get(
        source,
        ""
    )

    if isinstance(text_value, dict):

        text_value = json.dumps(
            text_value,
            ensure_ascii=False
        )

    text_value = str(
        text_value
    )

    operation = parameters.get(
        "operation",
        "uppercase"
    )

    if operation == "uppercase":

        result = text_value.upper()

    elif operation == "lowercase":

        result = text_value.lower()

    elif operation == "strip":

        result = text_value.strip()

    elif operation == "reverse":

        result = text_value[::-1]

    elif operation == "word_count":

        result = len(
            text_value.split()
        )

    else:

        raise ValueError(
            "Unsupported text transformation."
        )

    return result


# ------------------------------------------------------------
# 8. TEXT ANALYSIS ACTION
# ------------------------------------------------------------

def alvex_workflow_text_analyze(
    context,
    parameters
):

    source = parameters.get(
        "source",
        "input"
    )

    value = context.get(
        source,
        ""
    )

    if isinstance(value, dict):

        value = json.dumps(
            value,
            ensure_ascii=False
        )

    value = str(value)

    words = value.split()

    return {

        "characters": len(value),

        "words": len(words),

        "lines": len(value.splitlines()),

        "unique_words": len(
            set(
                word.lower()
                for word in words
            )
        ),

        "sha256": hashlib.sha256(
            value.encode("utf-8")
        ).hexdigest()

    }


# ------------------------------------------------------------
# 9. CONDITION ACTION
# ------------------------------------------------------------

def alvex_workflow_condition(
    context,
    parameters
):

    variable = parameters.get(
        "variable",
        "input"
    )

    expected = parameters.get(
        "equals"
    )

    actual = context.get(
        variable
    )

    operator = parameters.get(
        "operator",
        "equals"
    )

    if operator == "equals":

        result = actual == expected

    elif operator == "not_equals":

        result = actual != expected

    elif operator == "contains":

        result = (
            expected in actual
            if isinstance(actual, (str, list, dict))
            else False
        )

    elif operator == "greater_than":

        result = (
            isinstance(actual, (int, float))
            and not isinstance(actual, bool)
            and actual > expected
        )

    elif operator == "less_than":

        result = (
            isinstance(actual, (int, float))
            and not isinstance(actual, bool)
            and actual < expected
        )

    else:

        raise ValueError(
            "Unsupported condition operator."
        )

    return {

        "condition": operator,

        "result": bool(result),

        "actual": actual,

        "expected": expected

    }


# ------------------------------------------------------------
# 10. SAVE RESULT ACTION
# ------------------------------------------------------------

def alvex_workflow_save_result(
    context,
    parameters
):

    source = parameters.get(
        "source",
        "input"
    )

    target = parameters.get(
        "target",
        "saved_result"
    )

    value = context.get(
        source
    )

    context.set(
        target,
        value
    )

    return {

        "saved": True,

        "target": target

    }


# ------------------------------------------------------------
# 11. SEARCH ACTION
# ------------------------------------------------------------

def alvex_workflow_search(
    context,
    parameters
):

    query = parameters.get(
        "query"
    )

    if not isinstance(query, str):

        raise ValueError(
            "Search query must be text."
        )

    if len(query.strip()) < 2:

        raise ValueError(
            "Search query is too short."
        )

    # Search action is deliberately limited to
    # workflow context data. It does not bypass
    # the user's database permissions.

    source = context.get(
        parameters.get(
            "source",
            "input"
        ),
        ""
    )

    source_text = json.dumps(
        source,
        ensure_ascii=False
    )

    terms = query.lower().split()

    matches = [

        term

        for term in terms

        if term in source_text.lower()

    ]

    return {

        "query": query,

        "matched_terms": matches,

        "match_count": len(matches),

        "total_terms": len(terms)

    }


# ------------------------------------------------------------
# 12. REGISTER BUILT-IN ACTIONS
# ------------------------------------------------------------

alvex_workflow_action_registry.register(
    "text_transform",
    alvex_workflow_text_transform
)

alvex_workflow_action_registry.register(
    "text_analyze",
    alvex_workflow_text_analyze
)

alvex_workflow_action_registry.register(
    "condition",
    alvex_workflow_condition
)

alvex_workflow_action_registry.register(
    "save_result",
    alvex_workflow_save_result
)

alvex_workflow_action_registry.register(
    "search",
    alvex_workflow_search
)


# ------------------------------------------------------------
# 13. WORKFLOW REPOSITORY
# ------------------------------------------------------------

class AlvexWorkflowRepository:

    def create(
        self,
        db,
        user_id,
        request
    ):

        alvex_workflow_validator.validate_steps(
            request.steps
        )

        count = (
            db.query(AlvexWorkflowDefinition)
            .filter(
                AlvexWorkflowDefinition.user_id
                == user_id
            )
            .count()
        )

        if count >= ALVEX_WORKFLOW_CONFIG[
            "maximum_workflows_per_user"
        ]:

            raise HTTPException(
                status_code=400,
                detail="Workflow limit reached."
            )

        definition = AlvexWorkflowDefinition(

            workflow_id=str(uuid.uuid4()),

            user_id=user_id,

            name=request.name,

            description=request.description,

            trigger_type=request.trigger_type,

            steps=json.dumps(
                [
                    step.model_dump()
                    for step in request.steps
                ],
                ensure_ascii=False
            ),

            enabled=True

        )

        db.add(definition)
        db.commit()
        db.refresh(definition)

        return definition

    def get(
        self,
        db,
        user_id,
        workflow_id
    ):

        workflow = (
            db.query(AlvexWorkflowDefinition)
            .filter(
                AlvexWorkflowDefinition.workflow_id
                == workflow_id,
                AlvexWorkflowDefinition.user_id
                == user_id
            )
            .first()
        )

        if not workflow:

            raise HTTPException(
                status_code=404,
                detail="Workflow not found."
            )

        return workflow

    def list(
        self,
        db,
        user_id,
        limit=50
    ):

        return (
            db.query(AlvexWorkflowDefinition)
            .filter(
                AlvexWorkflowDefinition.user_id
                == user_id
            )
            .order_by(
                AlvexWorkflowDefinition.created_at.desc()
            )
            .limit(limit)
            .all()
        )

    def delete(
        self,
        db,
        user_id,
        workflow_id
    ):

        workflow = self.get(
            db,
            user_id,
            workflow_id
        )

        db.delete(workflow)
        db.commit()

        return True


alvex_workflow_repository = (
    AlvexWorkflowRepository()
)


# ------------------------------------------------------------
# 14. EXECUTION LOGGER
# ------------------------------------------------------------

class AlvexWorkflowExecutionLogger:

    def write(
        self,
        db,
        execution_id,
        step_id,
        action,
        status,
        duration_ms,
        result=None
    ):

        summary = json.dumps(
            result,
            ensure_ascii=False,
            default=str
        )[:2000] if result is not None else None

        record = AlvexWorkflowStepLog(

            log_id=str(uuid.uuid4()),

            execution_id=execution_id,

            step_id=step_id,

            action=action,

            status=status,

            duration_ms=duration_ms,

            result_summary=summary

        )

        db.add(record)
        db.commit()

        return record


alvex_workflow_execution_logger = (
    AlvexWorkflowExecutionLogger()
)


# ------------------------------------------------------------
# 15. EXECUTION ENGINE
# ------------------------------------------------------------

class AlvexWorkflowExecutionEngine:

    def execute(
        self,
        db,
        user_id,
        workflow,
        input_data
    ):

        if not workflow.enabled:

            raise HTTPException(
                status_code=403,
                detail="Workflow is disabled."
            )

        steps = json.loads(
            workflow.steps
        )

        execution = AlvexWorkflowExecution(

            execution_id=str(uuid.uuid4()),

            workflow_id=workflow.workflow_id,

            user_id=user_id,

            status="running",

            input_data=json.dumps(
                input_data,
                ensure_ascii=False
            ),

            total_steps=len(steps),

            completed_steps=0,

            started_at=datetime.utcnow()

        )

        db.add(execution)
        db.commit()
        db.refresh(execution)

        context = AlvexWorkflowContext(
            input_data
        )

        execution_started = time.monotonic()

        try:

            for step in steps:

                if not step.get("enabled", True):

                    continue

                elapsed = (
                    time.monotonic()
                    - execution_started
                )

                if elapsed > ALVEX_WORKFLOW_CONFIG[
                    "maximum_execution_time"
                ]:

                    raise TimeoutError(
                        "Workflow execution time exceeded."
                    )

                action_name = step["action"]

                handler = (
                    alvex_workflow_action_registry.get(
                        action_name
                    )
                )

                if not handler:

                    raise ValueError(
                        f"Action not found: {action_name}"
                    )

                step_started = time.monotonic()

                try:

                    result = handler(

                        context,

                        step.get(
                            "parameters",
                            {}
                        )

                    )

                    result_key = step.get(
                        "step_id"
                    )

                    context.set(
                        result_key,
                        result
                    )

                    duration = int(
                        (
                            time.monotonic()
                            - step_started
                        ) * 1000
                    )

                    alvex_workflow_execution_logger.write(

                        db,

                        execution.execution_id,

                        result_key,

                        action_name,

                        "completed",

                        duration,

                        result

                    )

                    execution.completed_steps += 1

                    db.commit()

                except Exception as step_error:

                    duration = int(
                        (
                            time.monotonic()
                            - step_started
                        ) * 1000
                    )

                    alvex_workflow_execution_logger.write(

                        db,

                        execution.execution_id,

                        step.get("step_id", "unknown"),

                        action_name,

                        "failed",

                        duration,

                        {

                            "error": str(step_error)

                        }

                    )

                    raise

            output = context.export()

            execution.status = "completed"

            execution.output_data = json.dumps(
                output,
                ensure_ascii=False,
                default=str
            )

            execution.finished_at = datetime.utcnow()

            db.commit()

            return {

                "execution_id": execution.execution_id,

                "status": execution.status,

                "completed_steps": execution.completed_steps,

                "total_steps": execution.total_steps,

                "output": output

            }

        except Exception as exc:

            execution.status = "failed"

            execution.error_message = str(exc)[:2000]

            execution.finished_at = datetime.utcnow()

            db.commit()

            logging.exception(
                "ALVEX workflow execution failed"
            )

            raise HTTPException(

                status_code=500,

                detail={

                    "message": "Workflow execution failed.",

                    "execution_id": execution.execution_id

                }

            )


alvex_workflow_execution_engine = (
    AlvexWorkflowExecutionEngine()
)


# ------------------------------------------------------------
# 16. WORKFLOW MANAGEMENT SERVICE
# ------------------------------------------------------------

class AlvexWorkflowManagementService:

    def create(
        self,
        db,
        user_id,
        request
    ):

        return alvex_workflow_repository.create(

            db,

            user_id,

            request

        )

    def execute(
        self,
        db,
        user_id,
        workflow_id,
        input_data
    ):

        workflow = alvex_workflow_repository.get(

            db,

            user_id,

            workflow_id

        )

        if workflow.trigger_type not in (
            "manual",
            "api",
            "scheduled"
        ):

            raise HTTPException(
                status_code=400,
                detail="Invalid workflow trigger."
            )

        return alvex_workflow_execution_engine.execute(

            db,

            user_id,

            workflow,

            input_data

        )


alvex_workflow_management_service = (
    AlvexWorkflowManagementService()
)


