# 17. CREATE WORKFLOW API
# ------------------------------------------------------------

@app.post("/api/workflows")
def alvex_create_workflow(
    request: AlvexWorkflowCreateRequest,
    db: Session = Depends(get_db),
    user=Depends(get_current_user)
):

    workflow = alvex_workflow_management_service.create(

        db,

        user.id,

        request

    )

    return {

        "success": True,

        "workflow_id": workflow.workflow_id,

        "name": workflow.name,

        "version": workflow.version,

        "enabled": workflow.enabled

    }


