@app.post(
    "/api/workflows/{workflow_id}/execute"
)
def alvex_execute_workflow(
    workflow_id: str,
    request: AlvexWorkflowExecuteRequest,
    db: Session = Depends(get_db),
    user=Depends(get_current_user)
):

    return alvex_workflow_management_service.execute(

        db,

        user.id,

        workflow_id,

        request.input_data

    )


# ------------------------------------------------------------
# 21. UPDATE WORKFLOW API
# ------------------------------------------------------------

@app.patch(
    "/api/workflows/{workflow_id}"
)
def alvex_update_workflow(
    workflow_id: str,
    request: AlvexWorkflowUpdateRequest,
    db: Session = Depends(get_db),
    user=Depends(get_current_user)
):

    workflow = alvex_workflow_repository.get(

        db,

        user.id,

        workflow_id

    )

    if request.name is not None:

        workflow.name = request.name

    if request.description is not None:

        workflow.description = request.description

    if request.enabled is not None:

        workflow.enabled = request.enabled

    workflow.version += 1

    workflow.updated_at = datetime.utcnow()

    db.commit()

    return {

        "success": True,

        "workflow_id": workflow.workflow_id,

        "version": workflow.version,

        "enabled": workflow.enabled

    }


