# ------------------------------------------------------------
# 23. EXECUTION HISTORY API
# ------------------------------------------------------------

@app.get(
    "/api/workflows/{workflow_id}/executions"
)
def alvex_workflow_execution_history(
    workflow_id: str,
    limit: int = Query(
        default=30,
        ge=1,
        le=100
    ),
    db: Session = Depends(get_db),
    user=Depends(get_current_user)
):

    workflow = alvex_workflow_repository.get(

        db,

        user.id,

        workflow_id

    )

    executions = (
        db.query(AlvexWorkflowExecution)
        .filter(
            AlvexWorkflowExecution.workflow_id
            == workflow.workflow_id,
            AlvexWorkflowExecution.user_id
            == user.id
        )
        .order_by(
            AlvexWorkflowExecution.created_at.desc()
        )
        .limit(limit)
        .all()
    )

    return {

        "count": len(executions),

        "executions": [

            {

                "execution_id": item.execution_id,

                "status": item.status,

                "total_steps": item.total_steps,

                "completed_steps": item.completed_steps,

                "created_at": item.created_at,

                "finished_at": item.finished_at

            }

            for item in executions

        ]

    }


# ------------------------------------------------------------
# 24. EXECUTION DETAIL API
# ------------------------------------------------------------

@app.get(
    "/api/workflows/executions/{execution_id}"
)
def alvex_workflow_execution_detail(
    execution_id: str,
    db: Session = Depends(get_db),
    user=Depends(get_current_user)
):

    execution = (
        db.query(AlvexWorkflowExecution)
        .filter(
            AlvexWorkflowExecution.execution_id
            == execution_id,
            AlvexWorkflowExecution.user_id
            == user.id
        )
        .first()
    )

    if not execution:

        raise HTTPException(
            status_code=404,
            detail="Execution not found."
        )

    logs = (
        db.query(AlvexWorkflowStepLog)
        .filter(
            AlvexWorkflowStepLog.execution_id
            == execution_id
        )
        .order_by(
            AlvexWorkflowStepLog.created_at.asc()
        )
        .all()
    )

    return {

        "execution_id": execution.execution_id,

        "status": execution.status,

        "input": json.loads(
            execution.input_data or "{}"
        ),

        "output": json.loads(
            execution.output_data or "{}"
        ),

        "error": execution.error_message,

        "steps": [

            {

                "step_id": item.step_id,

                "action": item.action,

                "status": item.status,

                "duration_ms": item.duration_ms,

                "result": item.result_summary

            }

            for item in logs

        ]

    }


