# ------------------------------------------------------------
# 4. DATA VALIDATOR
# ------------------------------------------------------------

class AlvexKnowledgeValidator:

    def validate_entity_type(self, entity_type):

        if entity_type not in (
            ALVEX_KNOWLEDGE_GRAPH_CONFIG[
                "allowed_entity_types"
            ]
        ):

            raise HTTPException(
                status_code=400,
                detail="Unsupported entity type."
            )

        return True

    def validate_relation_type(self, relation_type):

        if relation_type not in (
            ALVEX_KNOWLEDGE_GRAPH_CONFIG[
                "allowed_relation_types"
            ]
        ):

            raise HTTPException(
                status_code=400,
                detail="Unsupported relation type."
            )

        return True

    def validate_properties(self, properties):

        if not isinstance(properties, dict):

            raise HTTPException(
                status_code=400,
                detail="Properties must be an object."
            )

        try:

            encoded = json.dumps(
                properties,
                ensure_ascii=False
            )

        except (TypeError, ValueError):

            raise HTTPException(
                status_code=400,
                detail="Invalid properties."
            )

        if len(encoded.encode("utf-8")) > (
            ALVEX_KNOWLEDGE_GRAPH_CONFIG[
                "maximum_properties_size"
            ]
        ):

            raise HTTPException(
                status_code=413,
                detail="Properties are too large."
            )

        return encoded

    def normalize_name(self, name):

        return " ".join(
            name.strip().casefold().split()
        )


alvex_knowledge_validator = (
    AlvexKnowledgeValidator()
)


# ------------------------------------------------------------
# 5. ENTITY REPOSITORY
# ------------------------------------------------------------

class AlvexKnowledgeEntityRepository:

    def create(
        self,
        db,
        user_id,
        request
    ):

        alvex_knowledge_validator.validate_entity_type(
            request.entity_type
        )

        properties = (
            alvex_knowledge_validator.validate_properties(
                request.properties
            )
        )

        normalized = (
            alvex_knowledge_validator.normalize_name(
                request.name
            )
        )

        existing = (
            db.query(AlvexKnowledgeEntity)
            .filter(
                AlvexKnowledgeEntity.user_id == user_id,
                AlvexKnowledgeEntity.normalized_name
                == normalized,
                AlvexKnowledgeEntity.entity_type
                == request.entity_type
            )
            .first()
        )

        if existing:

            raise HTTPException(
                status_code=409,
                detail="Entity already exists."
            )

        count = (
            db.query(AlvexKnowledgeEntity)
            .filter(
                AlvexKnowledgeEntity.user_id == user_id
            )
            .count()
        )

        if count >= ALVEX_KNOWLEDGE_GRAPH_CONFIG[
            "maximum_entities_per_user"
        ]:

            raise HTTPException(
                status_code=400,
                detail="Entity limit reached."
            )

        entity = AlvexKnowledgeEntity(

            entity_id=str(uuid.uuid4()),

            user_id=user_id,

            name=request.name.strip(),

            normalized_name=normalized,

            entity_type=request.entity_type,

            description=request.description,

            properties_json=properties,

            source=request.source,

            confidence=request.confidence

        )

        db.add(entity)
        db.commit()
        db.refresh(entity)

        return entity

    def get(
        self,
        db,
        user_id,
        entity_id
    ):

        entity = (
            db.query(AlvexKnowledgeEntity)
            .filter(
                AlvexKnowledgeEntity.entity_id
                == entity_id,
                AlvexKnowledgeEntity.user_id
                == user_id
            )
            .first()
        )

        if not entity:

            raise HTTPException(
                status_code=404,
                detail="Knowledge entity not found."
            )

        return entity

    def list(
        self,
        db,
        user_id,
        entity_type=None,
        limit=50
    ):

        query = (
            db.query(AlvexKnowledgeEntity)
            .filter(
                AlvexKnowledgeEntity.user_id
                == user_id
            )
        )

        if entity_type:

            query = query.filter(
                AlvexKnowledgeEntity.entity_type
                == entity_type
            )

        return (
            query.order_by(
                AlvexKnowledgeEntity.created_at.desc()
            )
            .limit(limit)
            .all()
        )

    def update(
        self,
        db,
        user_id,
        entity_id,
        request
    ):

        entity = self.get(
            db,
            user_id,
            entity_id
        )

        if request.name is not None:

            normalized = (
                alvex_knowledge_validator.normalize_name(
                    request.name
                )
            )

            duplicate = (
                db.query(AlvexKnowledgeEntity)
                .filter(
                    AlvexKnowledgeEntity.user_id
                    == user_id,
                    AlvexKnowledgeEntity.normalized_name
                    == normalized,
                    AlvexKnowledgeEntity.entity_type
                    == entity.entity_type,
                    AlvexKnowledgeEntity.id
                    != entity.id
                )
                .first()
            )

            if duplicate:

                raise HTTPException(
                    status_code=409,
                    detail="Another entity has this name."
                )

            entity.name = request.name.strip()

            entity.normalized_name = normalized

        if request.description is not None:

            entity.description = request.description

        if request.properties is not None:

            entity.properties_json = (
                alvex_knowledge_validator.validate_properties(
                    request.properties
                )
            )

        if request.confidence is not None:

            entity.confidence = request.confidence

        entity.updated_at = datetime.utcnow()

        db.commit()
        db.refresh(entity)

        return entity

    def delete(
        self,
        db,
        user_id,
        entity_id
    ):

        entity = self.get(
            db,
            user_id,
            entity_id
        )

        (
            db.query(AlvexKnowledgeRelation)
            .filter(
                AlvexKnowledgeRelation.user_id == user_id
            )
            .filter(
                (
                    AlvexKnowledgeRelation.source_entity_id
                    == entity_id
                )
                |
                (
                    AlvexKnowledgeRelation.target_entity_id
                    == entity_id
                )
            )
            .delete(synchronize_session=False)
        )

        db.delete(entity)
        db.commit()

        return True


alvex_knowledge_entity_repository = (
    AlvexKnowledgeEntityRepository()
)


# ------------------------------------------------------------
# 6. RELATION REPOSITORY
# ------------------------------------------------------------

class AlvexKnowledgeRelationRepository:

    def create(
        self,
        db,
        user_id,
        request
    ):

        alvex_knowledge_validator.validate_relation_type(
            request.relation_type
        )

        properties = (
            alvex_knowledge_validator.validate_properties(
                request.properties
            )
        )

        source = alvex_knowledge_entity_repository.get(
            db,
            user_id,
            request.source_entity_id
        )

        target = alvex_knowledge_entity_repository.get(
            db,
            user_id,
            request.target_entity_id
        )

        existing = (
            db.query(AlvexKnowledgeRelation)
            .filter(
                AlvexKnowledgeRelation.user_id == user_id,
                AlvexKnowledgeRelation.source_entity_id
                == source.entity_id,
                AlvexKnowledgeRelation.target_entity_id
                == target.entity_id,
                AlvexKnowledgeRelation.relation_type
                == request.relation_type
            )
            .first()
        )

        if existing:

            raise HTTPException(
                status_code=409,
                detail="Relation already exists."
            )

        count = (
            db.query(AlvexKnowledgeRelation)
            .filter(
                AlvexKnowledgeRelation.user_id == user_id
            )
            .count()
        )

        if count >= ALVEX_KNOWLEDGE_GRAPH_CONFIG[
            "maximum_relations_per_user"
        ]:

            raise HTTPException(
                status_code=400,
                detail="Relation limit reached."
            )

        relation = AlvexKnowledgeRelation(

            relation_id=str(uuid.uuid4()),

            user_id=user_id,

            source_entity_id=source.entity_id,

            target_entity_id=target.entity_id,

            relation_type=request.relation_type,

            description=request.description,

            properties_json=properties,

            confidence=request.confidence

        )

        db.add(relation)
        db.commit()
        db.refresh(relation)

        return relation

    def get(
        self,
        db,
        user_id,
        relation_id
    ):

        relation = (
            db.query(AlvexKnowledgeRelation)
            .filter(
                AlvexKnowledgeRelation.relation_id
                == relation_id,
                AlvexKnowledgeRelation.user_id
                == user_id
            )
            .first()
        )

        if not relation:

            raise HTTPException(
                status_code=404,
                detail="Relation not found."
            )

        return relation

    def list_for_entity(
        self,
        db,
        user_id,
        entity_id
    ):

        return (
            db.query(AlvexKnowledgeRelation)
            .filter(
                AlvexKnowledgeRelation.user_id == user_id
            )
            .filter(
                (
                    AlvexKnowledgeRelation.source_entity_id
                    == entity_id
                )
                |
                (
                    AlvexKnowledgeRelation.target_entity_id
                    == entity_id
                )
            )
            .all()
        )

    def delete(
        self,
        db,
        user_id,
        relation_id
    ):

        relation = self.get(
            db,
            user_id,
            relation_id
        )

        db.delete(relation)
        db.commit()

        return True


alvex_knowledge_relation_repository = (
    AlvexKnowledgeRelationRepository()
)


# ------------------------------------------------------------
# 7. GRAPH BUILDER
# ------------------------------------------------------------

class AlvexKnowledgeGraphBuilder:

    def build(
        self,
        db,
        user_id,
        entity_ids=None,
        limit=100
    ):

        query = (
            db.query(AlvexKnowledgeEntity)
            .filter(
                AlvexKnowledgeEntity.user_id == user_id
            )
        )

        if entity_ids is not None:

            if not entity_ids:

                return {
                    "nodes": [],
                    "edges": []
                }

            query = query.filter(
                AlvexKnowledgeEntity.entity_id.in_(
                    entity_ids
                )
            )

        entities = query.limit(limit).all()

        selected_ids = {
            entity.entity_id
            for entity in entities
        }

        relations = (
            db.query(AlvexKnowledgeRelation)
            .filter(
                AlvexKnowledgeRelation.user_id
                == user_id,
                AlvexKnowledgeRelation.source_entity_id.in_(
                    selected_ids
                ),
                AlvexKnowledgeRelation.target_entity_id.in_(
                    selected_ids
                )
            )
            .limit(limit * 3)
            .all()
        ) if selected_ids else []

        return {

            "nodes": [

                {

                    "id": entity.entity_id,

                    "label": entity.name,

                    "type": entity.entity_type,

                    "description": entity.description,

                    "confidence": entity.confidence

                }

                for entity in entities

            ],

            "edges": [

                {

                    "id": relation.relation_id,

                    "source": relation.source_entity_id,

                    "target": relation.target_entity_id,

                    "label": relation.relation_type,

                    "confidence": relation.confidence

                }

                for relation in relations

            ]

        }


alvex_knowledge_graph_builder = (
    AlvexKnowledgeGraphBuilder()
)


# ------------------------------------------------------------
# 8. GRAPH TRAVERSAL ENGINE
# ------------------------------------------------------------

class AlvexKnowledgeTraversalEngine:

    def traverse(
        self,
        db,
        user_id,
        start_entity_id,
        depth=2,
        max_nodes=100
    ):

        start = alvex_knowledge_entity_repository.get(
            db,
            user_id,
            start_entity_id
        )

        max_depth = min(
            depth,
            ALVEX_KNOWLEDGE_GRAPH_CONFIG[
                "maximum_graph_depth"
            ]
        )

        max_nodes = min(
            max_nodes,
            ALVEX_KNOWLEDGE_GRAPH_CONFIG[
                "maximum_graph_nodes"
            ]
        )

        visited = {
            start.entity_id
        }

        queue = [
            (start.entity_id, 0)
        ]

        discovered_relations = []

        while queue and len(visited) < max_nodes:

            current_id, current_depth = queue.pop(0)

            if current_depth >= max_depth:

                continue

            relations = (
                db.query(AlvexKnowledgeRelation)
                .filter(
                    AlvexKnowledgeRelation.user_id
                    == user_id
                )
                .filter(
                    (
                        AlvexKnowledgeRelation.source_entity_id
                        == current_id
                    )
                    |
                    (
                        AlvexKnowledgeRelation.target_entity_id
                        == current_id
                    )
                )
                .all()
            )

            for relation in relations:

                discovered_relations.append(
                    relation
                )

                if relation.source_entity_id == current_id:

                    neighbor = relation.target_entity_id

                else:

                    neighbor = relation.source_entity_id

                if neighbor not in visited:

                    if len(visited) >= max_nodes:

                        break

                    visited.add(neighbor)

                    queue.append(
                        (
                            neighbor,
                            current_depth + 1
                        )
                    )

        entities = (
            db.query(AlvexKnowledgeEntity)
            .filter(
                AlvexKnowledgeEntity.user_id == user_id,
                AlvexKnowledgeEntity.entity_id.in_(
                    visited
                )
            )
            .all()
        )

        unique_relations = {
            relation.relation_id: relation
            for relation in discovered_relations
        }

        return {

            "start_entity": start_entity_id,

            "depth": max_depth,

            "nodes": [

                {

                    "id": entity.entity_id,

                    "name": entity.name,

                    "type": entity.entity_type

                }

                for entity in entities

            ],

            "edges": [

                {

                    "id": relation.relation_id,

                    "source": relation.source_entity_id,

                    "target": relation.target_entity_id,

                    "type": relation.relation_type

                }

                for relation in unique_relations.values()

            ]

        }


alvex_knowledge_traversal_engine = (
    AlvexKnowledgeTraversalEngine()
)


# ------------------------------------------------------------
# 9. KNOWLEDGE SEARCH ENGINE
# ------------------------------------------------------------

class AlvexKnowledgeSearchEngine:

    def search(
        self,
        db,
        user_id,
        query,
        entity_type=None,
        limit=30
    ):

        normalized_query = (
            alvex_knowledge_validator.normalize_name(
                query
            )
        )

        if not normalized_query:

            return []

        search_terms = normalized_query.split()

        db_query = (
            db.query(AlvexKnowledgeEntity)
            .filter(
                AlvexKnowledgeEntity.user_id == user_id
            )
        )

        if entity_type:

            alvex_knowledge_validator.validate_entity_type(
                entity_type
            )

            db_query = db_query.filter(
                AlvexKnowledgeEntity.entity_type
                == entity_type
            )

        entities = db_query.limit(1000).all()

        scored = []

        for entity in entities:

            name = entity.normalized_name

            description = (
                entity.description or ""
            ).casefold()

            score = 0

            if normalized_query == name:

                score += 100

            elif normalized_query in name:

                score += 70

            for term in search_terms:

                if term in name:

                    score += 20

                if term in description:

                    score += 5

            if score > 0:

                scored.append(
                    (score, entity)
                )

        scored.sort(
            key=lambda item: item[0],
            reverse=True
        )

        return [

            {

                "entity_id": entity.entity_id,

                "name": entity.name,

                "type": entity.entity_type,

                "description": entity.description,

                "confidence": entity.confidence,

                "relevance": score

            }

            for score, entity in scored[:limit]

        ]


alvex_knowledge_search_engine = (
    AlvexKnowledgeSearchEngine()
)


# ------------------------------------------------------------
# 10. SOURCE REGISTRY
# ------------------------------------------------------------

class AlvexKnowledgeSourceRegistry:

    def create(
        self,
        db,
        user_id,
        request
    ):

        content_hash = hashlib.sha256(
            request.content.encode("utf-8")
        ).hexdigest()

        existing = (
            db.query(AlvexKnowledgeSource)
            .filter(
                AlvexKnowledgeSource.user_id == user_id,
                AlvexKnowledgeSource.content_hash
                == content_hash
            )
            .first()
        )

        if existing:

            raise HTTPException(
                status_code=409,
                detail="This source has already been registered."
            )

        source = AlvexKnowledgeSource(

            source_id=str(uuid.uuid4()),

            user_id=user_id,

            title=request.title,

            source_type=request.source_type,

            content_hash=content_hash,

            entity_count=0,

            relation_count=0

        )

        db.add(source)
        db.commit()
        db.refresh(source)

        return source

    def list(
        self,
        db,
        user_id,
        limit=50
    ):

        return (
            db.query(AlvexKnowledgeSource)
            .filter(
                AlvexKnowledgeSource.user_id
                == user_id
            )
            .order_by(
                AlvexKnowledgeSource.created_at.desc()
            )
            .limit(limit)
            .all()
        )


alvex_knowledge_source_registry = (
    AlvexKnowledgeSourceRegistry()
)


# ------------------------------------------------------------
# 11. KNOWLEDGE STATISTICS
# ------------------------------------------------------------

class AlvexKnowledgeStatistics:

    def calculate(
        self,
        db,
        user_id
    ):

        entity_count = (
            db.query(AlvexKnowledgeEntity)
            .filter(
                AlvexKnowledgeEntity.user_id
                == user_id
            )
            .count()
        )

        relation_count = (
            db.query(AlvexKnowledgeRelation)
            .filter(
                AlvexKnowledgeRelation.user_id
                == user_id
            )
            .count()
        )

        source_count = (
            db.query(AlvexKnowledgeSource)
            .filter(
                AlvexKnowledgeSource.user_id
                == user_id
            )
            .count()
        )

        entity_types = (
            db.query(
                AlvexKnowledgeEntity.entity_type,
                func.count(AlvexKnowledgeEntity.id)
            )
            .filter(
                AlvexKnowledgeEntity.user_id
                == user_id
            )
            .group_by(
                AlvexKnowledgeEntity.entity_type
            )
            .all()
        )

        relation_types = (
            db.query(
                AlvexKnowledgeRelation.relation_type,
                func.count(AlvexKnowledgeRelation.id)
            )
            .filter(
                AlvexKnowledgeRelation.user_id
                == user_id
            )
            .group_by(
                AlvexKnowledgeRelation.relation_type
            )
            .all()
        )

        return {

            "entities": entity_count,

            "relations": relation_count,

            "sources": source_count,

            "entity_types": {

                item[0]: item[1]

                for item in entity_types

            },

            "relation_types": {

                item[0]: item[1]

                for item in relation_types

            }

        }


alvex_knowledge_statistics = (
    AlvexKnowledgeStatistics()
)


