@app.post(
    "/api/autonomous-tasks/{task_id}/cancel"
)
def alvex_cancel_autonomous_task(
    task_id: str,
    db: Session = Depends(get_db),
    user=Depends(get_current_user)
):

    task = alvex_autonomous_task_repository.get(

        db,

        user.id,

        task_id

    )

    if task.status == "running":

        raise HTTPException(
            status_code=409,
            detail="Running task cancellation is not supported by this executor."
        )

    if task.status in (
        "completed",
        "cancelled"
    ):

        raise HTTPException(
            status_code=409,
            detail="Task cannot be cancelled."
        )

    task.status = "cancelled"

    task.updated_at = datetime.utcnow()

    db.commit()

    alvex_task_event_logger.log(

        db,

        user.id,

        task_id,

        "cancelled",

        "Task cancelled by user."

    )

    return {

        "success": True,

        "task_id": task.task_id,

        "status": task.status

    }


