@app.get("/api/autonomous-tasks/statistics")
def alvex_autonomous_task_statistics(
    db: Session = Depends(get_db),
    user=Depends(get_current_user)
):

    tasks = (
        db.query(AlvexAutonomousTask)
        .filter(
            AlvexAutonomousTask.user_id
            == user.id
        )
        .all()
    )

    statistics = {

        "total": len(tasks),

        "pending": 0,

        "running": 0,

        "completed": 0,

        "failed": 0,

        "cancelled": 0

    }

    for task in tasks:

        if task.status in statistics:

            statistics[task.status] += 1

    statistics["success_rate"] = (

        round(
            statistics["completed"]
            / len(tasks) * 100,
            2
        )

        if tasks else 0

    )

    return statistics


