# ------------------------------------------------------------
# 4. BENCHMARK VALIDATOR
# ------------------------------------------------------------

class AlvexBenchmarkValidator:

    def validate_tests(self, tests):

        if not tests:

            raise HTTPException(
                status_code=400,
                detail="At least one test is required."
            )

        if len(tests) > (
            ALVEX_BENCHMARK_CONFIG[
                "maximum_tests_per_run"
            ]
        ):

            raise HTTPException(
                status_code=400,
                detail="Too many tests."
            )

        for test in tests:

            if not test.input_text.strip():

                raise HTTPException(
                    status_code=400,
                    detail="Test input cannot be empty."
                )

            if test.metric not in (
                ALVEX_BENCHMARK_CONFIG[
                    "supported_metrics"
                ]
            ):

                raise HTTPException(
                    status_code=400,
                    detail="Unsupported benchmark metric."
                )

        return True


alvex_benchmark_validator = (
    AlvexBenchmarkValidator()
)


# ------------------------------------------------------------
# 5. SCORING ENGINE
# ------------------------------------------------------------

class AlvexBenchmarkScoringEngine:

    def normalize(self, value):

        return " ".join(
            str(value).casefold().split()
        )

    def exact_match(
        self,
        expected,
        actual
    ):

        if expected is None:

            return 0.0

        return 100.0 if (
            self.normalize(expected)
            == self.normalize(actual)
        ) else 0.0

    def keyword_match(
        self,
        expected,
        actual
    ):

        if not expected:

            return 0.0

        expected_words = set(
            self.normalize(expected).split()
        )

        actual_words = set(
            self.normalize(actual).split()
        )

        if not expected_words:

            return 0.0

        matched = (
            expected_words.intersection(
                actual_words
            )
        )

        return round(
            len(matched)
            / len(expected_words)
            * 100,
            2
        )

    def response_length(
        self,
        actual
    ):

        if not actual:

            return 0.0

        return min(
            len(actual) / 100,
            100
        )

    def calculate(
        self,
        metric,
        expected,
        actual
    ):

        if metric == "exact_match":

            return self.exact_match(
                expected,
                actual
            )

        if metric == "keyword_match":

            return self.keyword_match(
                expected,
                actual
            )

        if metric == "response_length":

            return self.response_length(
                actual
            )

        return 0.0


alvex_benchmark_scoring_engine = (
    AlvexBenchmarkScoringEngine()
)


# ------------------------------------------------------------
# 6. MODEL ADAPTER REGISTRY
# ------------------------------------------------------------

class AlvexBenchmarkModelRegistry:

    def __init__(self):

        self.models = {}

    def register(
        self,
        model_name,
        handler
    ):

        if not callable(handler):

            raise TypeError(
                "Model handler must be callable."
            )

        if model_name in self.models:

            raise ValueError(
                "Model is already registered."
            )

        self.models[model_name] = handler

    def get(self, model_name):

        handler = self.models.get(
            model_name
        )

        if handler is None:

            raise HTTPException(
                status_code=404,
                detail="Benchmark model is not registered."
            )

        return handler

    def list_models(self):

        return list(
            self.models.keys()
        )


alvex_benchmark_model_registry = (
    AlvexBenchmarkModelRegistry()
)


