# ------------------------------------------------------------
# 8. BENCHMARK EXECUTION ENGINE
# ------------------------------------------------------------

class AlvexBenchmarkExecutionEngine:

    def execute_test(
        self,
        model_handler,
        test
    ):

        started = time.perf_counter()

        try:

            actual_output = model_handler(
                test.input_text
            )

            latency = (
                time.perf_counter() - started
            ) * 1000

            if not isinstance(
                actual_output,
                str
            ):

                raise ValueError(
                    "Model output must be a string."
                )

            if len(actual_output) > (
                ALVEX_BENCHMARK_CONFIG[
                    "maximum_output_length"
                ]
            ):

                raise ValueError(
                    "Model output is too large."
                )

            score = (
                alvex_benchmark_scoring_engine.calculate(
                    test.metric,
                    test.expected_output,
                    actual_output
                )
            )

            return {

                "success": True,

                "actual_output": actual_output,

                "latency_ms": round(
                    latency,
                    3
                ),

                "score": score,

                "passed": score >= 70

            }

        except Exception as exc:

            latency = (
                time.perf_counter() - started
            ) * 1000

            return {

                "success": False,

                "actual_output": None,

                "latency_ms": round(
                    latency,
                    3
                ),

                "score": 0,

                "passed": False,

                "error": str(exc)[:2000]

            }


alvex_benchmark_execution_engine = (
    AlvexBenchmarkExecutionEngine()
)


# ------------------------------------------------------------
# 9. BENCHMARK REPOSITORY
# ------------------------------------------------------------

class AlvexBenchmarkRepository:

    def get_run(
        self,
        db,
        user_id,
        run_id
    ):

        run = (
            db.query(AlvexBenchmarkRun)
            .filter(
                AlvexBenchmarkRun.run_id == run_id,
                AlvexBenchmarkRun.user_id == user_id
            )
            .first()
        )

        if not run:

            raise HTTPException(
                status_code=404,
                detail="Benchmark run not found."
            )

        return run

    def create_run(
        self,
        db,
        user_id,
        model_name,
        benchmark_name,
        tests
    ):

        count = (
            db.query(AlvexBenchmarkRun)
            .filter(
                AlvexBenchmarkRun.user_id == user_id
            )
            .count()
        )

        if count >= ALVEX_BENCHMARK_CONFIG[
            "maximum_runs_per_user"
        ]:

            raise HTTPException(
                status_code=400,
                detail="Benchmark run limit reached."
            )

        run = AlvexBenchmarkRun(

            run_id=str(uuid.uuid4()),

            user_id=user_id,

            model_name=model_name,

            benchmark_name=benchmark_name,

            status="running",

            total_tests=len(tests)

        )

        db.add(run)
        db.commit()
        db.refresh(run)

        return run

    def save_test(
        self,
        db,
        user_id,
        run_id,
        test,
        result
    ):

        record = AlvexBenchmarkTest(

            test_id=str(uuid.uuid4()),

            run_id=run_id,

            user_id=user_id,

            test_name=test.name,

            input_text=test.input_text,

            expected_output=test.expected_output,

            actual_output=result.get(
                "actual_output"
            ),

            latency_ms=result.get(
                "latency_ms",
                0
            ),

            score=result.get(
                "score",
                0
            ),

            passed=result.get(
                "passed",
                False
            ),

            error_message=result.get(
                "error"
            )

        )

        db.add(record)
        db.commit()

        return record

    def list_tests(
        self,
        db,
        user_id,
        run_id
    ):

        return (
            db.query(AlvexBenchmarkTest)
            .filter(
                AlvexBenchmarkTest.user_id == user_id,
                AlvexBenchmarkTest.run_id == run_id
            )
            .order_by(
                AlvexBenchmarkTest.created_at.asc()
            )
            .all()
        )


alvex_benchmark_repository = (
    AlvexBenchmarkRepository()
)


# ------------------------------------------------------------
# 10. BENCHMARK ORCHESTRATOR
# ------------------------------------------------------------

class AlvexBenchmarkOrchestrator:

    def run(
        self,
        db,
        user_id,
        request
    ):

        alvex_benchmark_validator.validate_tests(
            request.tests
        )

        model_handler = (
            alvex_benchmark_model_registry.get(
                request.model_name
            )
        )

        run = alvex_benchmark_repository.create_run(

            db,

            user_id,

            request.model_name,

            request.benchmark_name,

            request.tests

        )

        latencies = []

        scores = []

        successful = 0

        failed = 0

        try:

            for test in request.tests:

                result = (
                    alvex_benchmark_execution_engine.execute_test(
                        model_handler,
                        test
                    )
                )

                alvex_benchmark_repository.save_test(

                    db,

                    user_id,

                    run.run_id,

                    test,

                    result

                )

                latencies.append(
                    result["latency_ms"]
                )

                scores.append(
                    result["score"]
                )

                if result["success"]:

                    successful += 1

                else:

                    failed += 1

            total = len(request.tests)

            average_latency = (
                statistics.mean(latencies)
                if latencies else 0
            )

            average_score = (
                statistics.mean(scores)
                if scores else 0
            )

            run.successful_tests = successful

            run.failed_tests = failed

            run.average_latency_ms = round(
                average_latency,
                3
            )

            run.success_rate = round(
                successful / total * 100,
                2
            )

            run.total_score = round(
                average_score,
                2
            )

            run.status = "completed"

            run.completed_at = datetime.utcnow()

            db.commit()

            return {

                "success": True,

                "run_id": run.run_id,

                "model_name": run.model_name,

                "total_tests": total,

                "successful_tests": successful,

                "failed_tests": failed,

                "average_latency_ms": run.average_latency_ms,

                "success_rate": run.success_rate,

                "average_score": run.total_score

            }

        except Exception:

            run.status = "failed"

            run.completed_at = datetime.utcnow()

            db.commit()

            logging.exception(
                "ALVEX benchmark run failed"
            )

            raise


alvex_benchmark_orchestrator = (
    AlvexBenchmarkOrchestrator()
)


# ------------------------------------------------------------
# 11. DATASET REPOSITORY
# ------------------------------------------------------------

class AlvexBenchmarkDatasetRepository:

    def create(
        self,
        db,
        user_id,
        request
    ):

        alvex_benchmark_validator.validate_tests(
            request.tests
        )

        tests_data = [
            test.model_dump()
            for test in request.tests
        ]

        dataset = AlvexBenchmarkDataset(

            dataset_id=str(uuid.uuid4()),

            user_id=user_id,

            name=request.name,

            description=request.description,

            tests_json=json.dumps(
                tests_data,
                ensure_ascii=False
            ),

            test_count=len(tests_data)

        )

        db.add(dataset)
        db.commit()
        db.refresh(dataset)

        return dataset

    def get(
        self,
        db,
        user_id,
        dataset_id
    ):

        dataset = (
            db.query(AlvexBenchmarkDataset)
            .filter(
                AlvexBenchmarkDataset.dataset_id
                == dataset_id,
                AlvexBenchmarkDataset.user_id
                == user_id
            )
            .first()
        )

        if not dataset:

            raise HTTPException(
                status_code=404,
                detail="Benchmark dataset not found."
            )

        return dataset

    def list(
        self,
        db,
        user_id,
        limit=50
    ):

        return (
            db.query(AlvexBenchmarkDataset)
            .filter(
                AlvexBenchmarkDataset.user_id
                == user_id
            )
            .order_by(
                AlvexBenchmarkDataset.created_at.desc()
            )
            .limit(limit)
            .all()
        )


alvex_benchmark_dataset_repository = (
    AlvexBenchmarkDatasetRepository()
)


