# ------------------------------------------------------------

@app.post(
    "/api/benchmarks/datasets/{dataset_id}/run"
)
def alvex_run_saved_benchmark_dataset(
    dataset_id: str,
    model_name: str = Query(
        min_length=1,
        max_length=200
    ),
    db: Session = Depends(get_db),
    user=Depends(get_current_user)
):

    dataset = alvex_benchmark_dataset_repository.get(

        db,

        user.id,

        dataset_id

    )

    raw_tests = json.loads(
        dataset.tests_json
    )

    tests = [
        AlvexBenchmarkTestInput(**item)
        for item in raw_tests
    ]

    request = AlvexBenchmarkRunCreate(

        model_name=model_name,

        benchmark_name=dataset.name,

        tests=tests

    )

    return alvex_benchmark_orchestrator.run(

        db,

        user.id,

        request

    )


