from typing import Optional, Dict, Any

from pydantic import BaseModel, Field
from fastapi import Depends, HTTPException, Query


# ------------------------------------------------------------
# 1. CONFIGURATION
# ------------------------------------------------------------

ALVEX_AUDIT_CONFIG = {
    "version": "1.0.0",
    "enabled": True,
    "maximum_metadata_length": 5000,
    "maximum_event_description": 3000,
    "suspicious_score_threshold": 70,
    "retention_days": 180,
    "sensitive_fields": [
        "password",
        "token",
        "secret",
        "api_key",
        "authorization",
        "access_token",
        "refresh_token"
    ],
    "severity_levels": [
        "info",
        "low",
        "medium",
        "high",
        "critical"
    ]
}


