# ------------------------------------------------------------
# 4. DATA REDACTION
# ------------------------------------------------------------

class AlvexAuditRedactor:

    def redact(self, value, depth=0):

        if depth > 8:
            return "[MAX_DEPTH]"

        if isinstance(value, dict):

            result = {}

            for key, item in value.items():

                normalized_key = str(key).lower()

                sensitive = any(
                    field in normalized_key
                    for field in ALVEX_AUDIT_CONFIG[
                        "sensitive_fields"
                    ]
                )

                if sensitive:
                    result[str(key)] = "[REDACTED]"
                else:
                    result[str(key)] = self.redact(
                        item,
                        depth + 1
                    )

            return result

        if isinstance(value, list):

            return [
                self.redact(item, depth + 1)
                for item in value[:100]
            ]

        if isinstance(value, str):

            return value[:5000]

        if value is None or isinstance(
            value,
            (bool, int, float)
        ):
            return value

        return str(value)[:500]


alvex_audit_redactor = AlvexAuditRedactor()


# ------------------------------------------------------------
# 5. METADATA VALIDATOR
# ------------------------------------------------------------

class AlvexAuditValidator:

    def validate_metadata(self, metadata):

        if metadata is None:
            return {}

        sanitized = alvex_audit_redactor.redact(
            metadata
        )

        encoded = json.dumps(
            sanitized,
            ensure_ascii=False
        )

        if len(encoded) > ALVEX_AUDIT_CONFIG[
            "maximum_metadata_length"
        ]:

            raise HTTPException(
                status_code=400,
                detail="Audit metadata is too large."
            )

        return sanitized

    def validate_event_type(self, event_type):

        if not re.fullmatch(
            r"[a-zA-Z0-9_.:-]{2,100}",
            event_type
        ):

            raise HTTPException(
                status_code=400,
                detail="Invalid event type."
            )

        return event_type


alvex_audit_validator = AlvexAuditValidator()


# ------------------------------------------------------------
# 6. AUDIT LOGGER
# ------------------------------------------------------------

class AlvexAuditLogger:

    def create_record(
        self,
        db,
        user_id,
        event_type,
        category,
        description,
        severity="info",
        metadata=None
    ):

        alvex_audit_validator.validate_event_type(
            event_type
        )

        safe_metadata = (
            alvex_audit_validator.validate_metadata(
                metadata
            )
        )

        safe_description = (
            alvex_audit_redactor.redact(
                {"description": description}
            )["description"]
        )

        source_material = "|".join([
            str(user_id or "anonymous"),
            event_type,
            category,
            safe_description,
            datetime.utcnow().isoformat()
        ])

        source_hash = hashlib.sha256(
            source_material.encode("utf-8")
        ).hexdigest()

        record = AlvexAuditRecord(

            event_id=str(uuid.uuid4()),

            user_id=user_id,

            event_type=event_type,

            category=category,

            severity=severity,

            description=safe_description,

            metadata_json=json.dumps(
                safe_metadata,
                ensure_ascii=False
            ),

            source_hash=source_hash

        )

        db.add(record)
        db.commit()
        db.refresh(record)

        return record


alvex_audit_logger = AlvexAuditLogger()


# ------------------------------------------------------------
# 7. RISK SCORING ENGINE
# ------------------------------------------------------------

class AlvexSecurityRiskEngine:

    SEVERITY_POINTS = {
        "info": 0,
        "low": 10,
        "medium": 25,
        "high": 45,
        "critical": 70
    }

    def calculate_score(
        self,
        event_count,
        high_severity_count,
        failed_attempt_count,
        unusual_activity=False
    ):

        score = 0

        score += min(
            event_count * 2,
            20
        )

        score += min(
            high_severity_count * 15,
            35
        )

        score += min(
            failed_attempt_count * 5,
            25
        )

        if unusual_activity:
            score += 20

        return min(score, 100)

    def classify(self, score):

        if score >= 90:
            return "critical"

        if score >= 70:
            return "high"

        if score >= 40:
            return "medium"

        return "low"


alvex_security_risk_engine = (
    AlvexSecurityRiskEngine()
)


# ------------------------------------------------------------
# 8. SECURITY FINDING SERVICE
# ------------------------------------------------------------

class AlvexSecurityFindingService:

    def create(
        self,
        db,
        user_id,
        title,
        description,
        risk_score,
        evidence=None
    ):

        score = max(
            0,
            min(int(risk_score), 100)
        )

        finding = AlvexSecurityFinding(

            finding_id=str(uuid.uuid4()),

            user_id=user_id,

            title=title[:200],

            description=description[:3000],

            risk_score=score,

            severity=alvex_security_risk_engine.classify(
                score
            ),

            status="open",

            evidence_json=json.dumps(
                alvex_audit_redactor.redact(
                    evidence or {}
                ),
                ensure_ascii=False
            )

        )

        db.add(finding)
        db.commit()
        db.refresh(finding)

        return finding

    def get(
        self,
        db,
        finding_id
    ):

        finding = (
            db.query(AlvexSecurityFinding)
            .filter(
                AlvexSecurityFinding.finding_id
                == finding_id
            )
            .first()
        )

        if not finding:

            raise HTTPException(
                status_code=404,
                detail="Security finding not found."
            )

        return finding

    def update_status(
        self,
        db,
        finding,
        status
    ):

        finding.status = status

        if status in (
            "resolved",
            "false_positive"
        ):

            finding.resolved_at = datetime.utcnow()

        else:

            finding.resolved_at = None

        db.commit()
        db.refresh(finding)

        return finding


alvex_security_finding_service = (
    AlvexSecurityFindingService()
)


