class AlvexAuditQueryService:

    def list_records(
        self,
        db,
        user_id=None,
        severity=None,
        category=None,
        limit=100
    ):

        query = db.query(
            AlvexAuditRecord
        )

        if user_id is not None:

            query = query.filter(
                AlvexAuditRecord.user_id == user_id
            )

        if severity:

            query = query.filter(
                AlvexAuditRecord.severity == severity
            )

        if category:

            query = query.filter(
                AlvexAuditRecord.category == category
            )

        return (
            query.order_by(
                AlvexAuditRecord.created_at.desc()
            )
            .limit(limit)
            .all()
        )

    def count_by_severity(
        self,
        db
    ):

        results = (
            db.query(
                AlvexAuditRecord.severity,
                func.count(AlvexAuditRecord.id)
            )
            .group_by(
                AlvexAuditRecord.severity
            )
            .all()
        )

        return {
            severity: count
            for severity, count in results
        }


alvex_audit_query_service = (
    AlvexAuditQueryService()
)


# ------------------------------------------------------------
# 10. AUTOMATIC AUDIT ANALYZER
# ------------------------------------------------------------

class AlvexAuditAnalyzer:

    def analyze_user_activity(
        self,
        db,
        user_id,
        window_minutes=60
    ):

        cutoff = (
            datetime.utcnow()
            - timedelta(minutes=window_minutes)
        )

        records = (
            db.query(AlvexAuditRecord)
            .filter(
                AlvexAuditRecord.user_id == user_id,
                AlvexAuditRecord.created_at >= cutoff
            )
            .all()
        )

        event_count = len(records)

        high_count = sum(
            1
            for record in records
            if record.severity in (
                "high",
                "critical"
            )
        )

        failed_count = sum(
            1
            for record in records
            if "failed" in record.event_type.lower()
            or "denied" in record.event_type.lower()
        )

        score = (
            alvex_security_risk_engine.calculate_score(
                event_count,
                high_count,
                failed_count
            )
        )

        return {

            "user_id": user_id,

            "window_minutes": window_minutes,

            "event_count": event_count,

            "high_severity_count": high_count,

            "failed_attempt_count": failed_count,

            "risk_score": score,

            "risk_level": (
                alvex_security_risk_engine.classify(
                    score
                )
            )

        }


alvex_audit_analyzer = AlvexAuditAnalyzer()


