# ------------------------------------------------------------
# 4. TEXT NORMALIZATION
# ------------------------------------------------------------

class AlvexRAGTextProcessor:

    def normalize(self, text):

        text = str(text).lower()

        text = re.sub(
            r"\s+",
            " ",
            text
        )

        return text.strip()

    def tokenize(self, text):

        normalized = self.normalize(text)

        return re.findall(
            r"\b[\wğüşöçıİĞÜŞÖÇ]+\b",
            normalized,
            flags=re.UNICODE
        )

    def hash_content(self, content):

        return hashlib.sha256(
            content.encode("utf-8")
        ).hexdigest()


alvex_rag_text_processor = (
    AlvexRAGTextProcessor()
)


# ------------------------------------------------------------
# 5. CHUNKING ENGINE
# ------------------------------------------------------------

class AlvexRAGChunkingEngine:

    def split(self, text):

        size = ALVEX_RAG_CONFIG[
            "maximum_chunk_size"
        ]

        overlap = ALVEX_RAG_CONFIG[
            "chunk_overlap"
        ]

        if overlap >= size:

            raise ValueError(
                "Chunk overlap must be smaller than chunk size."
            )

        chunks = []

        start = 0

        while start < len(text):

            end = min(
                start + size,
                len(text)
            )

            if end < len(text):

                boundary = text.rfind(
                    " ",
                    start,
                    end
                )

                if boundary > start + size // 2:

                    end = boundary

            content = text[start:end].strip()

            if content:

                chunks.append(content)

            if end >= len(text):

                break

            start = max(
                start + 1,
                end - overlap
            )

            if len(chunks) > (
                ALVEX_RAG_CONFIG[
                    "maximum_chunks_per_document"
                ]
            ):

                raise ValueError(
                    "Document contains too many chunks."
                )

        return chunks


alvex_rag_chunking_engine = (
    AlvexRAGChunkingEngine()
)


# ------------------------------------------------------------
# 6. BM25-LIKE RETRIEVAL ENGINE
# ------------------------------------------------------------

class AlvexRAGRetrievalEngine:

    def __init__(self):

        self.processor = (
            alvex_rag_text_processor
        )

    def calculate_idf(
        self,
        term,
        documents
    ):

        document_count = len(documents)

        containing = sum(
            1
            for document in documents
            if term in set(
                self.processor.tokenize(document)
            )
        )

        return math.log(
            1 + (
                document_count - containing + 0.5
            ) / (
                containing + 0.5
            )
        )

    def score(
        self,
        query,
        document,
        documents
    ):

        query_terms = (
            self.processor.tokenize(query)
        )

        document_terms = (
            self.processor.tokenize(document)
        )

        if not query_terms or not document_terms:

            return 0.0

        frequencies = {}

        for term in document_terms:

            frequencies[term] = (
                frequencies.get(term, 0) + 1
            )

        average_length = (
            sum(
                len(
                    self.processor.tokenize(item)
                )
                for item in documents
            ) / max(len(documents), 1)
        )

        document_length = len(
            document_terms
        )

        k1 = 1.5
        b = 0.75

        score = 0.0

        for term in set(query_terms):

            frequency = frequencies.get(
                term,
                0
            )

            if not frequency:

                continue

            idf = self.calculate_idf(
                term,
                documents
            )

            denominator = frequency + k1 * (
                1 - b
                + b * document_length
                / max(average_length, 1)
            )

            score += idf * (
                frequency * (k1 + 1)
                / denominator
            )

        return round(score, 6)

    def search(
        self,
        query,
        chunks,
        limit=5
    ):

        contents = [
            chunk.content
            for chunk in chunks
        ]

        results = []

        for chunk in chunks:

            relevance = self.score(
                query,
                chunk.content,
                contents
            )

            if relevance >= (
                ALVEX_RAG_CONFIG[
                    "minimum_relevance_score"
                ]
            ):

                results.append({

                    "chunk": chunk,

                    "score": relevance

                })

        results.sort(
            key=lambda item: item["score"],
            reverse=True
        )

        return results[:limit]


alvex_rag_retrieval_engine = (
    AlvexRAGRetrievalEngine()
)


# ------------------------------------------------------------
# 7. DOCUMENT REPOSITORY
# ------------------------------------------------------------

class AlvexRAGRepository:

    def create_document(
        self,
        db,
        user_id,
        title,
        description,
        content
    ):

        existing = (
            db.query(AlvexRAGDocument)
            .filter(
                AlvexRAGDocument.user_id == user_id,
                AlvexRAGDocument.content_hash
                == alvex_rag_text_processor.hash_content(
                    content
                )
            )
            .first()
        )

        if existing:

            raise HTTPException(
                status_code=409,
                detail="This document is already indexed."
            )

        chunks = (
            alvex_rag_chunking_engine.split(
                content
            )
        )

        count = (
            db.query(AlvexRAGDocument)
            .filter(
                AlvexRAGDocument.user_id == user_id
            )
            .count()
        )

        if count >= ALVEX_RAG_CONFIG[
            "maximum_documents"
        ]:

            raise HTTPException(
                status_code=400,
                detail="Document limit reached."
            )

        document_id = str(uuid.uuid4())

        document = AlvexRAGDocument(

            document_id=document_id,

            user_id=user_id,

            title=title,

            description=description,

            content_hash=(
                alvex_rag_text_processor.hash_content(
                    content
                )
            ),

            total_chunks=len(chunks),

            status="indexed"

        )

        db.add(document)
        db.flush()

        for index, content_chunk in enumerate(chunks):

            chunk = AlvexRAGChunk(

                chunk_id=str(uuid.uuid4()),

                document_id=document_id,

                user_id=user_id,

                chunk_index=index,

                content=content_chunk,

                token_count=len(
                    alvex_rag_text_processor.tokenize(
                        content_chunk
                    )
                ),

                content_hash=(
                    alvex_rag_text_processor.hash_content(
                        content_chunk
                    )
                )

            )

            db.add(chunk)

        db.commit()
        db.refresh(document)

        return document

    def get_document(
        self,
        db,
        user_id,
        document_id
    ):

        document = (
            db.query(AlvexRAGDocument)
            .filter(
                AlvexRAGDocument.document_id
                == document_id,
                AlvexRAGDocument.user_id
                == user_id
            )
            .first()
        )

        if not document:

            raise HTTPException(
                status_code=404,
                detail="Document not found."
            )

        return document

    def get_chunks(
        self,
        db,
        user_id,
        document_id=None
    ):

        query = (
            db.query(AlvexRAGChunk)
            .filter(
                AlvexRAGChunk.user_id == user_id
            )
        )

        if document_id:

            query = query.filter(
                AlvexRAGChunk.document_id
                == document_id
            )

        return query.limit(
            10000
        ).all()

    def list_documents(
        self,
        db,
        user_id,
        limit=100
    ):

        return (
            db.query(AlvexRAGDocument)
            .filter(
                AlvexRAGDocument.user_id == user_id
            )
            .order_by(
                AlvexRAGDocument.created_at.desc()
            )
            .limit(limit)
            .all()
        )

    def delete_document(
        self,
        db,
        user_id,
        document_id
    ):

        document = self.get_document(
            db,
            user_id,
            document_id
        )

        db.query(AlvexRAGChunk).filter(
            AlvexRAGChunk.document_id
            == document_id,
            AlvexRAGChunk.user_id == user_id
        ).delete(
            synchronize_session=False
        )

        db.delete(document)
        db.commit()

        return True


alvex_rag_repository = AlvexRAGRepository()


# ------------------------------------------------------------
# 8. CONTEXT BUILDER
# ------------------------------------------------------------

class AlvexRAGContextBuilder:

    def build(
        self,
        results
    ):

        context_parts = []

        sources = []

        for index, result in enumerate(
            results,
            start=1
        ):

            chunk = result["chunk"]

            context_parts.append(
                f"[SOURCE {index}]\n{chunk.content}"
            )

            sources.append({

                "document_id": chunk.document_id,

                "chunk_id": chunk.chunk_id,

                "chunk_index": chunk.chunk_index,

                "relevance_score": result["score"]

            })

        return {

            "context": "\n\n".join(
                context_parts
            ),

            "sources": sources,

            "source_count": len(sources)

        }


alvex_rag_context_builder = (
    AlvexRAGContextBuilder()
)


# ------------------------------------------------------------
# 9. RAG SERVICE
# ------------------------------------------------------------

class AlvexRAGService:

    def search(
        self,
        db,
        user_id,
        request
    ):

        started = time.perf_counter()

        chunks = alvex_rag_repository.get_chunks(

            db,

            user_id,

            request.document_id

        )

        results = alvex_rag_retrieval_engine.search(

            request.query,

            chunks,

            request.limit

        )

        context = alvex_rag_context_builder.build(
            results
        )

        elapsed = (
            time.perf_counter() - started
        ) * 1000

        query_hash = hashlib.sha256(
            request.query.encode("utf-8")
        ).hexdigest()

        log = AlvexRAGQueryLog(

            query_id=str(uuid.uuid4()),

            user_id=user_id,

            query_hash=query_hash,

            result_count=len(results),

            processing_time_ms=round(
                elapsed,
                3
            )

        )

        db.add(log)
        db.commit()

        return {

            "query": request.query,

            "result_count": len(results),

            "processing_time_ms": round(
                elapsed,
                3
            ),

            "context": context["context"],

            "sources": context["sources"]

        }


alvex_rag_service = AlvexRAGService()


