import uuid
import json
import time
import logging
import hashlib

from datetime import datetime
from typing import Optional, Dict, Any, List, Callable

from pydantic import BaseModel, Field
from fastapi import Depends, HTTPException, Query


# ------------------------------------------------------------
# 1. CONFIGURATION
# ------------------------------------------------------------

ALVEX_AGENT_ORCHESTRATION_CONFIG = {

    "version": "1.0.0",

    "enabled": True,

    "maximum_steps": 8,

    "maximum_tools_per_execution": 6,

    "maximum_input_length": 10000,

    "maximum_output_length": 15000,

    "maximum_execution_seconds": 30,

    "require_tool_approval": True,

    "allow_external_network": False,

    "allow_arbitrary_code": False,

    "allowed_tools": [
        "text_analyzer",
        "calculator",
        "knowledge_search",
        "text_summarizer",
        "document_search"
    ]

}


# ------------------------------------------------------------
# 2. DATABASE MODELS
# ------------------------------------------------------------

class AlvexAgentExecution(Base):

    __tablename__ = "alvex_agent_orchestration_executions"

    id = Column(
        Integer,
        primary_key=True,
        index=True
    )

    execution_id = Column(
        String(100),
        unique=True,
        nullable=False,
        index=True
    )

    user_id = Column(
        Integer,
        ForeignKey("users.id"),
        nullable=False,
        index=True
    )

    objective = Column(
        Text,
        nullable=False
    )

    status = Column(
        String(30),
        default="pending",
        index=True
    )

    total_steps = Column(
        Integer,
        default=0
    )

    successful_steps = Column(
        Integer,
        default=0
    )

    failed_steps = Column(
        Integer,
        default=0
    )

    final_output = Column(
        Text,
        nullable=True
    )

    execution_time_ms = Column(
        Float,
        default=0.0
    )

    created_at = Column(
        DateTime,
        default=datetime.utcnow
    )

    completed_at = Column(
        DateTime,
        nullable=True
    )


class AlvexAgentExecutionStep(Base):

    __tablename__ = "alvex_agent_orchestration_steps"

    id = Column(
        Integer,
        primary_key=True,
        index=True
    )

    step_id = Column(
        String(100),
        unique=True,
        nullable=False,
        index=True
    )

    execution_id = Column(
        String(100),
        nullable=False,
        index=True
    )

    user_id = Column(
        Integer,
        ForeignKey("users.id"),
        nullable=False,
        index=True
    )

    step_number = Column(
        Integer,
        nullable=False
    )

    tool_name = Column(
        String(100),
        nullable=False
    )

    status = Column(
        String(30),
        default="pending"
    )

    input_hash = Column(
        String(64),
        nullable=False
    )

    output_text = Column(
        Text,
        nullable=True
    )

    error_message = Column(
        Text,
        nullable=True
    )

    duration_ms = Column(
        Float,
        default=0.0
    )

    created_at = Column(
        DateTime,
        default=datetime.utcnow
    )


Base.metadata.create_all(bind=engine)


# ------------------------------------------------------------
# 3. REQUEST SCHEMAS
# ------------------------------------------------------------

class AlvexAgentToolStep(BaseModel):

    tool_name: str = Field(
        min_length=2,
        max_length=100
    )

    input_data: Dict[str, Any] = Field(
        default_factory=dict
    )


class AlvexAgentExecutionRequest(BaseModel):

    objective: str = Field(
        min_length=3,
        max_length=10000
    )

    steps: List[AlvexAgentToolStep] = Field(
        min_length=1,
        max_length=8
    )


class AlvexAgentApprovalRequest(BaseModel):

    approved: bool


# ------------------------------------------------------------
# 4. INPUT VALIDATOR
# ------------------------------------------------------------

class AlvexAgentOrchestrationValidator:

    def validate(self, request):

        if len(request.steps) > (
            ALVEX_AGENT_ORCHESTRATION_CONFIG[
                "maximum_steps"
            ]
        ):

            raise HTTPException(
                status_code=400,
                detail="Maximum step count exceeded."
            )

        for step in request.steps:

            if step.tool_name not in (
                ALVEX_AGENT_ORCHESTRATION_CONFIG[
                    "allowed_tools"
                ]
            ):

                raise HTTPException(
                    status_code=400,
                    detail="Tool is not allowed."
                )

            encoded = json.dumps(
                step.input_data,
                ensure_ascii=False
            )

            if len(encoded) > (
                ALVEX_AGENT_ORCHESTRATION_CONFIG[
                    "maximum_input_length"
                ]
            ):

                raise HTTPException(
                    status_code=400,
                    detail="Tool input is too large."
                )

        return True


alvex_agent_orchestration_validator = (
    AlvexAgentOrchestrationValidator()
)


# ------------------------------------------------------------
# 5. TOOL REGISTRY
# ------------------------------------------------------------

class AlvexAgentToolRegistry:

    def __init__(self):

        self.tools = {}

        self.metadata = {}

    def register(
        self,
        name,
        handler,
        description,
        requires_approval=False
    ):

        if name not in (
            ALVEX_AGENT_ORCHESTRATION_CONFIG[
                "allowed_tools"
            ]
        ):

            raise ValueError(
                "Tool is not in the allowlist."
            )

        if not callable(handler):

            raise TypeError(
                "Tool handler must be callable."
            )

        if name in self.tools:

            raise ValueError(
                "Tool already registered."
            )

        self.tools[name] = handler

        self.metadata[name] = {

            "name": name,

            "description": description,

            "requires_approval": requires_approval,

            "registered_at": datetime.utcnow().isoformat()

        }

    def get(self, name):

        handler = self.tools.get(name)

        if handler is None:

            raise HTTPException(
                status_code=503,
                detail=f"Tool unavailable: {name}"
            )

        return handler

    def list_tools(self):

        return list(
            self.metadata.values()
        )


alvex_agent_tool_registry = (
    AlvexAgentToolRegistry()
)


# ------------------------------------------------------------
# 6. BUILT-IN TOOL: TEXT ANALYZER
# ------------------------------------------------------------

def alvex_agent_text_analyzer(input_data):

    text = str(
        input_data.get("text", "")
    )

    words = text.split()

    sentences = [
        item for item in text.split(".")
        if item.strip()
    ]

    return {

        "character_count": len(text),

        "word_count": len(words),

        "sentence_count": len(sentences),

        "average_word_length": round(
            sum(len(word) for word in words)
            / max(len(words), 1),
            2
        )

    }


# ------------------------------------------------------------
# 7. BUILT-IN TOOL: CALCULATOR
# ------------------------------------------------------------

def alvex_agent_calculator(input_data):

    operation = input_data.get(
        "operation"
    )

    first = float(
        input_data.get("first", 0)
    )

    second = float(
        input_data.get("second", 0)
    )

    operations = {

        "add": lambda: first + second,

        "subtract": lambda: first - second,

        "multiply": lambda: first * second,

        "divide": lambda: (
            first / second
            if second != 0
            else None
        )

    }

    if operation not in operations:

        raise ValueError(
            "Unsupported calculator operation."
        )

    result = operations[operation]()

    if result is None:

        raise ValueError(
            "Division by zero is not allowed."
        )

    return {

        "operation": operation,

        "result": result

    }


# ------------------------------------------------------------
# 8. BUILT-IN TOOL: TEXT SUMMARIZER
# ------------------------------------------------------------

def alvex_agent_text_summarizer(input_data):

    text = str(
        input_data.get("text", "")
    )

    maximum_words = int(
        input_data.get("maximum_words", 100)
    )

    maximum_words = max(
        10,
        min(maximum_words, 500)
    )

    words = text.split()

    summary = " ".join(
        words[:maximum_words]
    )

    return {

        "summary": summary,

        "original_word_count": len(words),

        "summary_word_count": len(
            summary.split()
        ),

        "method": "extractive_truncation"

    }


# ------------------------------------------------------------
# 9. BUILT-IN TOOL: KNOWLEDGE SEARCH
# ------------------------------------------------------------

def alvex_agent_knowledge_search(input_data):

    query = str(
        input_data.get("query", "")
    ).strip()

    if not query:

        raise ValueError(
            "Knowledge query is required."
        )

    return {

        "query": query,

        "status": "requires_user_scoped_context",

        "message": (
            "Use the authenticated knowledge adapter "
            "to retrieve user-owned knowledge."
        )

    }


# ------------------------------------------------------------
# 10. BUILT-IN TOOL: DOCUMENT SEARCH
# ------------------------------------------------------------

def alvex_agent_document_search(input_data):

    query = str(
        input_data.get("query", "")
    ).strip()

    if not query:

        raise ValueError(
            "Document query is required."
        )

    return {

        "query": query,

        "status": "requires_user_scoped_context",

        "message": (
            "Document search must be executed through "
            "the authenticated document repository."
        )

    }


# ------------------------------------------------------------
# 11. REGISTER BUILT-IN TOOLS
# ------------------------------------------------------------

alvex_agent_tool_registry.register(

    "text_analyzer",

    alvex_agent_text_analyzer,

    "Analyzes text structure."

)

alvex_agent_tool_registry.register(

    "calculator",

    alvex_agent_calculator,

    "Performs basic arithmetic operations."

)

alvex_agent_tool_registry.register(

    "text_summarizer",

    alvex_agent_text_summarizer,

    "Creates a simple extractive text summary."

)

alvex_agent_tool_registry.register(

    "knowledge_search",

    alvex_agent_knowledge_search,

    "Knowledge search adapter placeholder."

)

alvex_agent_tool_registry.register(

    "document_search",

    alvex_agent_document_search,

    "Document search adapter placeholder."

)


# ------------------------------------------------------------
# 12. TOOL EXECUTION ENGINE
# ------------------------------------------------------------

class AlvexAgentToolExecutionEngine:

    def execute(
        self,
        tool_name,
        input_data
    ):

        handler = alvex_agent_tool_registry.get(
            tool_name
        )

        started = time.perf_counter()

        result = handler(
            input_data
        )

        duration = (
            time.perf_counter() - started
        ) * 1000

        serialized = json.dumps(
            result,
            ensure_ascii=False,
            default=str
        )

        if len(serialized) > (
            ALVEX_AGENT_ORCHESTRATION_CONFIG[
                "maximum_output_length"
            ]
        ):

            raise ValueError(
                "Tool output exceeds maximum size."
            )

        return {

            "result": result,

            "duration_ms": round(
                duration,
                3
            )

        }


alvex_agent_tool_execution_engine = (
    AlvexAgentToolExecutionEngine()
)


# ------------------------------------------------------------
# 13. EXECUTION REPOSITORY
# ------------------------------------------------------------

class AlvexAgentExecutionRepository:

    def create(
        self,
        db,
        user_id,
        objective
    ):

        execution = AlvexAgentExecution(

            execution_id=str(uuid.uuid4()),

            user_id=user_id,

            objective=objective,

            status="running"

        )

        db.add(execution)

        db.commit()

        db.refresh(execution)

        return execution

    def create_step(
        self,
        db,
        user_id,
        execution_id,
        step_number,
        tool_name,
        input_data
    ):

        input_hash = hashlib.sha256(
            json.dumps(
                input_data,
                sort_keys=True,
                ensure_ascii=False
            ).encode("utf-8")
        ).hexdigest()

        record = AlvexAgentExecutionStep(

            step_id=str(uuid.uuid4()),

            execution_id=execution_id,

            user_id=user_id,

            step_number=step_number,

            tool_name=tool_name,

            input_hash=input_hash,

            status="running"

        )

        db.add(record)

        db.commit()

        db.refresh(record)

        return record

    def complete_step(
        self,
        db,
        record,
        status,
        output=None,
        error=None,
        duration=0
    ):

        record.status = status

        record.output_text = (
            json.dumps(
                output,
                ensure_ascii=False,
                default=str
            )[:15000]
            if output is not None else None
        )

        record.error_message = (
            str(error)[:2000]
            if error else None
        )

        record.duration_ms = duration

        db.commit()

        return record

    def finish(
        self,
        db,
        execution,
        status,
        output,
        successful,
        failed,
        duration
    ):

        execution.status = status

        execution.final_output = (
            str(output)[:30000]
        )

        execution.total_steps = (
            successful + failed
        )

        execution.successful_steps = successful

        execution.failed_steps = failed

        execution.execution_time_ms = round(
            duration,
            3
        )

        execution.completed_at = datetime.utcnow()

        db.commit()

        db.refresh(execution)

        return execution


alvex_agent_execution_repository = (
    AlvexAgentExecutionRepository()
)


# ------------------------------------------------------------
# 14. ORCHESTRATION ENGINE
# ------------------------------------------------------------

class AlvexAgentOrchestrationEngine:

    def run(
        self,
        db,
        user_id,
        request
    ):

        alvex_agent_orchestration_validator.validate(
            request
        )

        started = time.perf_counter()

        execution = (
            alvex_agent_execution_repository.create(

                db,

                user_id,

                request.objective

            )
        )

        outputs = []

        successful = 0

        failed = 0

        status = "completed"

        try:

            for index, step in enumerate(
                request.steps,
                start=1
            ):

                elapsed = (
                    time.perf_counter() - started
                )

                if elapsed > (
                    ALVEX_AGENT_ORCHESTRATION_CONFIG[
                        "maximum_execution_seconds"
                    ]
                ):

                    status = "timeout"

                    break

                record = (
                    alvex_agent_execution_repository.create_step(

                        db,

                        user_id,

                        execution.execution_id,

                        index,

                        step.tool_name,

                        step.input_data

                    )
                )

                step_started = time.perf_counter()

                try:

                    result = (
                        alvex_agent_tool_execution_engine.execute(

                            step.tool_name,

                            step.input_data

                        )
                    )

                    duration = (
                        time.perf_counter()
                        - step_started
                    ) * 1000

                    alvex_agent_execution_repository.complete_step(

                        db,

                        record,

                        "completed",

                        result["result"],

                        duration=duration

                    )

                    outputs.append({

                        "step": index,

                        "tool": step.tool_name,

                        "status": "completed",

                        "output": result["result"]

                    })

                    successful += 1

                except Exception as exc:

                    duration = (
                        time.perf_counter()
                        - step_started
                    ) * 1000

                    alvex_agent_execution_repository.complete_step(

                        db,

                        record,

                        "failed",

                        error=str(exc),

                        duration=duration

                    )

                    outputs.append({

                        "step": index,

                        "tool": step.tool_name,

                        "status": "failed",

                        "error": str(exc)[:1000]

                    })

                    failed += 1

            if status != "timeout" and failed:

                status = (
                    "completed_with_errors"
                )

            final_output = json.dumps(
                outputs,
                ensure_ascii=False,
                default=str
            )

            duration = (
                time.perf_counter() - started
            ) * 1000

            alvex_agent_execution_repository.finish(

                db,

                execution,

                status,

                final_output,

                successful,

                failed,

                duration

            )

            return {

                "success": status == "completed",

                "execution_id": execution.execution_id,

                "status": status,

                "successful_steps": successful,

                "failed_steps": failed,

                "execution_time_ms": round(
                    duration,
                    3
                ),

                "results": outputs

            }

        except Exception:

            db.rollback()

            logging.exception(
                "Agent orchestration failed."
            )

            raise


alvex_agent_orchestration_engine = (
    AlvexAgentOrchestrationEngine()
)


