ALVEX_CONVERSATION_INTELLIGENCE_CONFIG = {

    "version": "1.0.0",

    "enabled": True,

    "maximum_memory_items": 500,

    "maximum_memory_length": 5000,

    "maximum_search_results": 20,

    "minimum_search_score": 0.15,

    "automatic_memory_extraction": False,

    "require_user_confirmation": True,

    "allow_sensitive_memory": False,

    "retention_days": 365

}


