# ------------------------------------------------------------
# 4. TEXT NORMALIZATION
# ------------------------------------------------------------

class AlvexConversationTextProcessor:

    @staticmethod
    def normalize(text):

        return " ".join(
            str(text).lower().split()
        )

    @staticmethod
    def tokenize(text):

        normalized = (
            AlvexConversationTextProcessor.normalize(
                text
            )
        )

        return [

            token.strip(
                ".,!?;:()[]{}\"'"
            )

            for token in normalized.split()

            if len(token.strip()) > 1

        ]

    @staticmethod
    def fingerprint(text):

        return hashlib.sha256(
            text.encode("utf-8")
        ).hexdigest()


alvex_conversation_text_processor = (
    AlvexConversationTextProcessor()
)


# ------------------------------------------------------------
# 5. BASIC SENSITIVE DATA FILTER
# ------------------------------------------------------------

class AlvexMemoryPrivacyFilter:

    BLOCKED_PATTERNS = [

        "password",

        "parola",

        "şifre",

        "secret key",

        "api key",

        "private key",

        "kredi kartı"

    ]

    def validate(self, content):

        lowered = content.lower()

        for pattern in self.BLOCKED_PATTERNS:

            if pattern in lowered:

                raise HTTPException(
                    status_code=400,
                    detail=(
                        "This content may contain "
                        "sensitive information."
                    )
                )

        return True


alvex_memory_privacy_filter = (
    AlvexMemoryPrivacyFilter()
)


# ------------------------------------------------------------
# 6. INSIGHT REPOSITORY
# ------------------------------------------------------------

class AlvexConversationInsightRepository:

    def create(
        self,
        db,
        user_id,
        request
    ):

        existing_count = (
            db.query(AlvexConversationInsight)
            .filter(
                AlvexConversationInsight.user_id
                == user_id
            )
            .count()
        )

        if existing_count >= (
            ALVEX_CONVERSATION_INTELLIGENCE_CONFIG[
                "maximum_memory_items"
            ]
        ):

            raise HTTPException(
                status_code=409,
                detail="Memory capacity reached."
            )

        content_hash = (
            alvex_conversation_text_processor.fingerprint(
                request.content
            )
        )

        duplicate = (
            db.query(AlvexConversationInsight)
            .filter(
                AlvexConversationInsight.user_id
                == user_id,
                AlvexConversationInsight.content_hash
                == content_hash
            )
            .first()
        )

        if duplicate:

            raise HTTPException(
                status_code=409,
                detail="This insight already exists."
            )

        insight = AlvexConversationInsight(

            insight_id=str(uuid.uuid4()),

            user_id=user_id,

            conversation_id=request.conversation_id,

            insight_type=request.insight_type,

            title=request.title,

            content=request.content,

            confidence=request.confidence,

            content_hash=content_hash

        )

        db.add(insight)

        db.commit()

        db.refresh(insight)

        return insight

    def get(
        self,
        db,
        user_id,
        insight_id
    ):

        return (
            db.query(AlvexConversationInsight)
            .filter(
                AlvexConversationInsight.insight_id
                == insight_id,
                AlvexConversationInsight.user_id
                == user_id
            )
            .first()
        )

    def list(
        self,
        db,
        user_id,
        limit=50
    ):

        return (
            db.query(AlvexConversationInsight)
            .filter(
                AlvexConversationInsight.user_id
                == user_id
            )
            .order_by(
                AlvexConversationInsight.created_at.desc()
            )
            .limit(limit)
            .all()
        )

    def delete(
        self,
        db,
        user_id,
        insight_id
    ):

        insight = self.get(
            db,
            user_id,
            insight_id
        )

        if not insight:

            return False

        db.query(
            AlvexConversationMemoryLink
        ).filter(
            AlvexConversationMemoryLink.insight_id
            == insight_id,
            AlvexConversationMemoryLink.user_id
            == user_id
        ).delete(
            synchronize_session=False
        )

        db.delete(insight)

        db.commit()

        return True


alvex_conversation_insight_repository = (
    AlvexConversationInsightRepository()
)


# ------------------------------------------------------------
# 7. RELEVANCE SCORING
# ------------------------------------------------------------

class AlvexConversationRelevanceEngine:

    def score(
        self,
        query,
        title,
        content
    ):

        query_tokens = set(
            alvex_conversation_text_processor.tokenize(
                query
            )
        )

        document_tokens = set(
            alvex_conversation_text_processor.tokenize(
                title + " " + content
            )
        )

        if not query_tokens or not document_tokens:

            return 0.0

        intersection = (
            query_tokens & document_tokens
        )

        coverage = (
            len(intersection)
            / len(query_tokens)
        )

        precision = (
            len(intersection)
            / len(document_tokens)
        )

        exact_title_match = (
            query.lower() in title.lower()
        )

        score = (
            coverage * 0.65
            + precision * 0.25
            + (0.10 if exact_title_match else 0)
        )

        return round(
            min(score, 1.0),
            4
        )


alvex_conversation_relevance_engine = (
    AlvexConversationRelevanceEngine()
)


# ------------------------------------------------------------
# 8. MEMORY SEARCH ENGINE
# ------------------------------------------------------------

class AlvexConversationMemorySearchEngine:

    def search(
        self,
        db,
        user_id,
        request
    ):

        query = (
            db.query(AlvexConversationInsight)
            .filter(
                AlvexConversationInsight.user_id
                == user_id
            )
        )

        if request.insight_type:

            query = query.filter(
                AlvexConversationInsight.insight_type
                == request.insight_type
            )

        candidates = (
            query.order_by(
                AlvexConversationInsight.created_at.desc()
            )
            .limit(500)
            .all()
        )

        results = []

        for item in candidates:

            score = (
                alvex_conversation_relevance_engine.score(

                    request.query,

                    item.title,

                    item.content

                )
            )

            if score < (
                ALVEX_CONVERSATION_INTELLIGENCE_CONFIG[
                    "minimum_search_score"
                ]
            ):

                continue

            results.append({

                "insight_id": item.insight_id,

                "title": item.title,

                "content": item.content,

                "insight_type": item.insight_type,

                "confidence": item.confidence,

                "relevance_score": score,

                "created_at": item.created_at

            })

        results.sort(
            key=lambda item: item["relevance_score"],
            reverse=True
        )

        return results[:request.limit]


alvex_conversation_memory_search_engine = (
    AlvexConversationMemorySearchEngine()
)


