# ------------------------------------------------------------
# 10. CONVERSATION ANALYSIS SERVICE
# ------------------------------------------------------------

class AlvexConversationAnalysisService:

    def analyze_messages(self, messages):

        total_messages = len(messages)

        user_messages = 0

        assistant_messages = 0

        total_characters = 0

        for message in messages:

            role = getattr(
                message,
                "role",
                ""
            )

            content = str(
                getattr(
                    message,
                    "content",
                    ""
                )
            )

            total_characters += len(content)

            if role == "user":

                user_messages += 1

            elif role == "assistant":

                assistant_messages += 1

        return {

            "total_messages": total_messages,

            "user_messages": user_messages,

            "assistant_messages": assistant_messages,

            "total_characters": total_characters,

            "average_message_length": round(

                total_characters
                / max(total_messages, 1),

                2

            )

        }


alvex_conversation_analysis_service = (
    AlvexConversationAnalysisService()
)


