class AlvexReliabilityTestRequest(BaseModel):

    categories: List[str] = Field(
        default_factory=lambda: [
            "database",
            "agent",
            "rag",
            "memory",
            "provider"
        ],
        max_length=10
    )


# ------------------------------------------------------------
# 4. TEST RESULT MODEL
# ------------------------------------------------------------

class AlvexReliabilityResult:

    def __init__(
        self,
        name,
        category,
        status,
        message="",
        duration_ms=0,
        error_hash=None
    ):

        self.name = name

        self.category = category

        self.status = status

        self.message = message

        self.duration_ms = duration_ms

        self.error_hash = error_hash

    def serialize(self):

        return {

            "name": self.name,

            "category": self.category,

            "status": self.status,

            "message": self.message,

            "duration_ms": round(
                self.duration_ms,
                3
            ),

            "error_hash": self.error_hash

        }


# ------------------------------------------------------------
# 5. TEST REGISTRY
# ------------------------------------------------------------

class AlvexReliabilityTestRegistry:

    ALLOWED_CATEGORIES = {

        "database",

        "agent",

        "rag",

        "memory",

        "provider",

        "configuration"

    }

    def __init__(self):

        self.tests = {}

    def register(
        self,
        name,
        category,
        handler
    ):

        if category not in self.ALLOWED_CATEGORIES:

            raise ValueError(
                "Unsupported test category."
            )

        if name in self.tests:

            raise ValueError(
                "Test already registered."
            )

        if not callable(handler):

            raise TypeError(
                "Test handler must be callable."
            )

        self.tests[name] = {

            "name": name,

            "category": category,

            "handler": handler

        }

    def get_tests(self, categories=None):

        selected = []

        for test in self.tests.values():

            if (
                categories
                and test["category"] not in categories
            ):

                continue

            selected.append(test)

        return selected

    def list_tests(self):

        return [

            {

                "name": test["name"],

                "category": test["category"]

            }

            for test in self.tests.values()

        ]


alvex_reliability_test_registry = (
    AlvexReliabilityTestRegistry()
)


