# ------------------------------------------------------------
# 13. TEST EXECUTION ENGINE
# ------------------------------------------------------------

class AlvexReliabilityExecutionEngine:

    def execute_test(
        self,
        test
    ):

        started = time.perf_counter()

        try:

            output = test["handler"]()

            duration = (
                time.perf_counter() - started
            ) * 1000

            return AlvexReliabilityResult(

                name=test["name"],

                category=test["category"],

                status="passed",

                message=json.dumps(
                    output,
                    ensure_ascii=False,
                    default=str
                )[:2000],

                duration_ms=duration

            )

        except Exception as exc:

            duration = (
                time.perf_counter() - started
            ) * 1000

            error_hash = hashlib.sha256(
                (
                    type(exc).__name__
                    + ":"
                    + str(exc)
                ).encode("utf-8")
            ).hexdigest()

            logging.exception(
                "Reliability test failed: %s",
                test["name"]
            )

            return AlvexReliabilityResult(

                name=test["name"],

                category=test["category"],

                status="failed",

                message=(
                    type(exc).__name__
                    + ": "
                    + str(exc)[:500]
                ),

                duration_ms=duration,

                error_hash=error_hash

            )

    def execute(
        self,
        categories=None
    ):

        tests = (
            alvex_reliability_test_registry.get_tests(
                categories
            )
        )

        if len(tests) > (
            ALVEX_RELIABILITY_CONFIG[
                "maximum_test_cases"
            ]
        ):

            raise ValueError(
                "Test count exceeds configured maximum."
            )

        started = time.perf_counter()

        results = []

        for test in tests:

            elapsed = (
                time.perf_counter() - started
            )

            if elapsed > (
                ALVEX_RELIABILITY_CONFIG[
                    "maximum_test_duration_seconds"
                ]
            ):

                results.append(
                    AlvexReliabilityResult(

                        name="remaining_tests",

                        category="system",

                        status="skipped",

                        message="Execution time limit reached."

                    )
                )

                break

            result = self.execute_test(
                test
            )

            results.append(result)

        duration = (
            time.perf_counter() - started
        ) * 1000

        passed = sum(
            1 for item in results
            if item.status == "passed"
        )

        failed = sum(
            1 for item in results
            if item.status == "failed"
        )

        skipped = sum(
            1 for item in results
            if item.status == "skipped"
        )

        return {

            "results": results,

            "total": len(results),

            "passed": passed,

            "failed": failed,

            "skipped": skipped,

            "duration_ms": round(
                duration,
                3
            ),

            "status": (
                "passed"
                if failed == 0 and skipped == 0
                else "degraded"
                if failed == 0
                else "failed"
            )

        }


alvex_reliability_execution_engine = (
    AlvexReliabilityExecutionEngine()
)


# ------------------------------------------------------------
# 14. TEST HISTORY REPOSITORY
# ------------------------------------------------------------

class AlvexReliabilityRepository:

    def save_run(
        self,
        db,
        user_id,
        execution
    ):

        run_id = str(uuid.uuid4())

        run = AlvexReliabilityTestRun(

            run_id=run_id,

            user_id=user_id,

            execution_mode="diagnostic",

            status=execution["status"],

            total_tests=execution["total"],

            passed_tests=execution["passed"],

            failed_tests=execution["failed"],

            skipped_tests=execution["skipped"],

            duration_ms=execution["duration_ms"],

            completed_at=datetime.utcnow()

        )

        db.add(run)

        db.flush()

        for result in execution["results"]:

            record = AlvexReliabilityTestResult(

                result_id=str(uuid.uuid4()),

                run_id=run_id,

                user_id=user_id,

                test_name=result.name,

                category=result.category,

                status=result.status,

                message=result.message,

                duration_ms=result.duration_ms,

                error_hash=result.error_hash

            )

            db.add(record)

        db.commit()

        db.refresh(run)

        return run

    def get_user_history(
        self,
        db,
        user_id,
        limit=20
    ):

        return (
            db.query(AlvexReliabilityTestRun)
            .filter(
                AlvexReliabilityTestRun.user_id
                == user_id
            )
            .order_by(
                AlvexReliabilityTestRun.started_at.desc()
            )
            .limit(limit)
            .all()
        )


alvex_reliability_repository = (
    AlvexReliabilityRepository()
)


# ------------------------------------------------------------
# 15. RUN DIAGNOSTICS API
# ------------------------------------------------------------

@app.post(
    "/api/reliability/run"
)
def alvex_reliability_run(
    request: AlvexReliabilityTestRequest,
    db: Session = Depends(get_db),
    user=Depends(get_current_user)
):

    if not ALVEX_RELIABILITY_CONFIG[
        "test_execution_enabled"
    ]:

        raise HTTPException(
            status_code=403,
            detail="Diagnostic execution is disabled."
        )

    allowed = (
        alvex_reliability_test_registry.ALLOWED_CATEGORIES
    )

    invalid = (
        set(request.categories) - allowed
    )

    if invalid:

        raise HTTPException(
            status_code=400,
            detail="Unsupported test categories."
        )

    execution = (
        alvex_reliability_execution_engine.execute(
            request.categories
        )
    )

    run = (
        alvex_reliability_repository.save_run(

            db,

            user.id,

            execution

        )
    )

    return {

        "success": True,

        "run_id": run.run_id,

        "status": execution["status"],

        "summary": {

            "total": execution["total"],

            "passed": execution["passed"],

            "failed": execution["failed"],

            "skipped": execution["skipped"],

            "duration_ms": execution["duration_ms"]

        },

        "results": [

            result.serialize()

            for result in execution["results"]

        ]

    }


