def alvex_reliability_health(
    db: Session = Depends(get_db),
    user=Depends(get_current_user)
):

    components = {}

    try:

        db.execute(
            __import__("sqlalchemy").text(
                "SELECT 1"
            )
        )

        components["database"] = "healthy"

    except Exception:

        components["database"] = "unavailable"

    components["agent_registry"] = (

        "healthy"

        if globals().get(
            "alvex_agent_tool_registry"
        ) is not None

        else "unavailable"

    )

    components["rag_service"] = (

        "healthy"

        if globals().get(
            "alvex_rag_service"
        ) is not None

        else "unavailable"

    )

    components["memory_service"] = (

        "healthy"

        if globals().get(
            "alvex_conversation_memory_search_engine"
        ) is not None

        else "unavailable"

    )

    healthy = all(
        value == "healthy"
        for value in components.values()
    )

    return {

        "service": "ALVEX AI Reliability",

        "version": ALVEX_RELIABILITY_CONFIG[
            "version"
        ],

        "status": (
            "healthy"
            if healthy
            else "degraded"
        ),

        "components": components,

        "registered_tests": len(
            alvex_reliability_test_registry.tests
        )

    }


