# ------------------------------------------------------------
# 4. PROVIDER STATUS
# ------------------------------------------------------------

class AlvexProviderStatus:

    def __init__(self, name):

        self.name = name

        self.failures = 0

        self.successes = 0

        self.total_requests = 0

        self.average_latency_ms = 0.0

        self.circuit_open_until = None

        self.last_error = None

        self.last_success = None

        self.lock = threading.RLock()

    def is_available(self):

        with self.lock:

            if self.circuit_open_until is None:

                return True

            if datetime.utcnow() >= (
                self.circuit_open_until
            ):

                self.circuit_open_until = None

                self.failures = 0

                return True

            return False

    def record_success(self, duration):

        with self.lock:

            self.total_requests += 1

            self.successes += 1

            self.failures = 0

            self.last_success = datetime.utcnow()

            previous = self.average_latency_ms

            self.average_latency_ms = (

                previous * (self.successes - 1)
                + duration

            ) / self.successes

    def record_failure(self, error):

        with self.lock:

            self.total_requests += 1

            self.failures += 1

            self.last_error = str(error)[:500]

            threshold = (
                ALVEX_SMART_ROUTING_CONFIG[
                    "circuit_failure_threshold"
                ]
            )

            if self.failures >= threshold:

                recovery = (
                    ALVEX_SMART_ROUTING_CONFIG[
                        "circuit_recovery_seconds"
                    ]
                )

                self.circuit_open_until = (
                    datetime.utcnow()
                    + timedelta(seconds=recovery)
                )

    def serialize(self):

        with self.lock:

            return {

                "provider": self.name,

                "available": self.is_available(),

                "total_requests": self.total_requests,

                "successes": self.successes,

                "failures": self.failures,

                "average_latency_ms": round(
                    self.average_latency_ms,
                    2
                ),

                "last_error": self.last_error,

                "last_success": (
                    self.last_success.isoformat()
                    if self.last_success else None
                )

            }


# ------------------------------------------------------------
# 5. PROVIDER REGISTRY
# ------------------------------------------------------------

class AlvexSmartProviderRegistry:

    def __init__(self):

        self.providers = {}

        self.statuses = {}

        self.lock = threading.RLock()

    def register(
        self,
        name,
        handler,
        models=None,
        priority=100
    ):

        if not callable(handler):

            raise TypeError(
                "Provider handler must be callable."
            )

        with self.lock:

            if name in self.providers:

                raise ValueError(
                    "Provider already registered."
                )

            self.providers[name] = {

                "name": name,

                "handler": handler,

                "models": models or [],

                "priority": int(priority)

            }

            self.statuses[name] = (
                AlvexProviderStatus(name)
            )

    def get(self, name):

        with self.lock:

            return self.providers.get(name)

    def list_available(self):

        with self.lock:

            return [

                provider

                for name, provider in self.providers.items()

                if self.statuses[name].is_available()

            ]

    def get_status(self, name):

        return self.statuses.get(name)

    def list_status(self):

        with self.lock:

            return [

                self.statuses[name].serialize()

                for name in self.statuses

            ]


alvex_smart_provider_registry = (
    AlvexSmartProviderRegistry()
)


# ------------------------------------------------------------
# 6. CONNECT EXISTING PROVIDERS
# ------------------------------------------------------------

def alvex_register_existing_provider(
    name,
    handler,
    models=None,
    priority=100
):

    alvex_smart_provider_registry.register(

        name,

        handler,

        models=models,

        priority=priority

    )


def alvex_register_gateway_adapter(
    provider_name,
    model_name,
    gateway_handler,
    priority=100
):
    """
    gateway_handler must be an explicitly configured
    callable accepting:

        prompt
        model_name
        temperature
        system_instruction
        maximum_tokens

    Map this adapter to the actual Part 8 gateway
    method before registering it.
    """

    def adapter(**kwargs):

        return gateway_handler(

            prompt=kwargs["prompt"],

            model_name=kwargs["model_name"],

            temperature=kwargs["temperature"],

            system_instruction=kwargs.get(
                "system_instruction"
            ),

            maximum_tokens=kwargs.get(
                "maximum_tokens",
                2048
            )

        )

    alvex_register_existing_provider(

        provider_name,

        adapter,

        models=[model_name],

        priority=priority

    )


# ------------------------------------------------------------
# 7. MODEL SELECTION ENGINE
# ------------------------------------------------------------

class AlvexSmartModelSelector:

    def select(
        self,
        requested_model=None,
        requested_provider=None
    ):

        providers = (
            alvex_smart_provider_registry.list_available()
        )

        if requested_provider:

            providers = [

                provider

                for provider in providers

                if provider["name"] == requested_provider

            ]

        if requested_model:

            providers = [

                provider

                for provider in providers

                if requested_model in provider["models"]

            ]

        if not providers:

            raise HTTPException(

                status_code=503,

                detail="No suitable AI provider is available."

            )

        providers.sort(
            key=lambda item: item["priority"]
        )

        return providers


alvex_smart_model_selector = (
    AlvexSmartModelSelector()
)


# ------------------------------------------------------------
# 8. RESPONSE NORMALIZER
# ------------------------------------------------------------

class AlvexProviderResponseNormalizer:

    @staticmethod
    def normalize(response):

        if isinstance(response, str):

            text = response

        elif isinstance(response, dict):

            text = response.get(
                "response"
            )

            if text is None:

                text = response.get(
                    "content"
                )

        else:

            raise ValueError(
                "Unsupported provider response format."
            )

        if not isinstance(text, str):

            raise ValueError(
                "Provider returned no text response."
            )

        text = text.strip()

        if not text:

            raise ValueError(
                "Provider returned an empty response."
            )

        maximum = (
            ALVEX_SMART_ROUTING_CONFIG[
                "maximum_response_length"
            ]
        )

        if len(text) > maximum:

            text = text[:maximum]

        return text


alvex_provider_response_normalizer = (
    AlvexProviderResponseNormalizer()
)


# ------------------------------------------------------------
# 9. PROVIDER EXECUTION ENGINE
# ------------------------------------------------------------

class AlvexSmartProviderExecutionEngine:

    def execute_provider(
        self,
        provider,
        request
    ):

        name = provider["name"]

        status = (
            alvex_smart_provider_registry.get_status(
                name
            )
        )

        if not status or not status.is_available():

            raise RuntimeError(
                "Provider circuit is open."
            )

        handler = provider["handler"]

        started = time.perf_counter()

        try:

            response = handler(

                prompt=request.prompt,

                model_name=(
                    request.model_name
                    or (
                        provider["models"][0]
                        if provider["models"]
                        else None
                    )
                ),

                system_instruction=(
                    request.system_instruction
                ),

                temperature=request.temperature,

                maximum_tokens=request.maximum_tokens

            )

            normalized = (
                alvex_provider_response_normalizer.normalize(
                    response
                )
            )

            duration = (
                time.perf_counter() - started
            ) * 1000

            status.record_success(
                duration
            )

            return {

                "response": normalized,

                "provider": name,

                "model": (
                    request.model_name
                    or (
                        provider["models"][0]
                        if provider["models"]
                        else None
                    )
                ),

                "duration_ms": round(
                    duration,
                    3
                )

            }

        except Exception as exc:

            status.record_failure(
                exc
            )

            raise


alvex_smart_provider_execution_engine = (
    AlvexSmartProviderExecutionEngine()
)


# ------------------------------------------------------------
# 10. ROUTING ENGINE
# ------------------------------------------------------------

class AlvexSmartRoutingEngine:

    def route(self, request):

        started = time.perf_counter()

        providers = (
            alvex_smart_model_selector.select(

                requested_model=request.model_name,

                requested_provider=request.provider_name

            )
        )

        failures = []

        maximum_retries = (
            ALVEX_SMART_ROUTING_CONFIG[
                "maximum_retries"
            ]
        )

        for provider in providers:

            attempts = maximum_retries + 1

            for attempt in range(attempts):

                try:

                    result = (
                        alvex_smart_provider_execution_engine.execute_provider(

                            provider,

                            request

                        )
                    )

                    result["attempts"] = attempt + 1

                    result["routing_duration_ms"] = round(

                        (
                            time.perf_counter() - started
                        ) * 1000,

                        3

                    )

                    return result

                except Exception as exc:

                    failures.append({

                        "provider": provider["name"],

                        "attempt": attempt + 1,

                        "error": (
                            type(exc).__name__
                            + ": "
                            + str(exc)[:300]
                        )

                    })

                    if attempt < maximum_retries:

                        delay = (
                            ALVEX_SMART_ROUTING_CONFIG[
                                "retry_backoff_seconds"
                            ]
                            * (2 ** attempt)
                        )

                        time.sleep(
                            min(delay, 3)
                        )

                    if not (
                        ALVEX_SMART_ROUTING_CONFIG[
                            "automatic_failover"
                        ]
                    ):

                        break

        raise HTTPException(

            status_code=503,

            detail={

                "message": "All selected providers failed.",

                "failures": failures

            }

        )


alvex_smart_routing_engine = (
    AlvexSmartRoutingEngine()
)


# ------------------------------------------------------------
# 11. ROUTING AUDIT SERVICE
# ------------------------------------------------------------

class AlvexSmartRoutingAuditService:

    def log_success(
        self,
        db,
        user_id,
        request,
        result
    ):

        record = AlvexSmartRoutingLog(

            routing_id=str(uuid.uuid4()),

            user_id=user_id,

            requested_model=request.model_name,

            selected_provider=result["provider"],

            selected_model=result["model"],

            status="completed",

            attempts=result["attempts"],

            duration_ms=result["routing_duration_ms"]

        )

        db.add(record)

        db.commit()

        return record

    def log_failure(
        self,
        db,
        user_id,
        request,
        error
    ):

        record = AlvexSmartRoutingLog(

            routing_id=str(uuid.uuid4()),

            user_id=user_id,

            requested_model=request.model_name,

            status="failed",

            error_message=str(error)[:2000]

        )

        db.add(record)

        db.commit()

        return record


alvex_smart_routing_audit_service = (
    AlvexSmartRoutingAuditService()
)


# ------------------------------------------------------------
# 12. MAIN ROUTING API
# ------------------------------------------------------------

@app.post(
    "/api/smart-routing/generate"
)
def alvex_smart_routing_generate(
    request: AlvexSmartRoutingRequest,
    db: Session = Depends(get_db),
    user=Depends(get_current_user)
):

    if not ALVEX_SMART_ROUTING_CONFIG["enabled"]:

        raise HTTPException(
            status_code=503,
            detail="Smart routing is disabled."
        )

    try:

        result = (
            alvex_smart_routing_engine.route(
                request
            )
        )

        alvex_smart_routing_audit_service.log_success(

            db,

            user.id,

            request,

            result

        )

        return {

            "success": True,

            "response": result["response"],

            "provider": result["provider"],

            "model": result["model"],

            "attempts": result["attempts"],

            "duration_ms": result["duration_ms"],

            "routing_duration_ms": (
                result["routing_duration_ms"]
            )

        }

    except HTTPException as exc:

        try:

            alvex_smart_routing_audit_service.log_failure(

                db,

                user.id,

                request,

                exc.detail

            )

        except Exception:

            db.rollback()

            logging.exception(
                "Failed to save routing audit."
            )

        raise

    except Exception as exc:

        db.rollback()

        logging.exception(
            "Smart routing failed."
        )

        raise HTTPException(

            status_code=503,

            detail="AI routing service unavailable."

        )


