# ------------------------------------------------------------
# 3. REQUEST SCHEMAS
# ------------------------------------------------------------

class AlvexControlCenterEventRequest(BaseModel):

    event_type: str = Field(
        min_length=2,
        max_length=100
    )

    severity: str = Field(
        default="info",
        max_length=30
    )

    description: str = Field(
        min_length=2,
        max_length=2000
    )

    component: Optional[str] = Field(
        default=None,
        max_length=100
    )

    metadata: Dict[str, Any] = Field(
        default_factory=dict
    )


class AlvexControlCenterConfigurationRequest(BaseModel):

    config_key: str = Field(
        min_length=2,
        max_length=150
    )

    config_value: Dict[str, Any]

    description: Optional[str] = Field(
        default=None,
        max_length=500
    )


# ------------------------------------------------------------
# 4. EVENT VALIDATOR
# ------------------------------------------------------------

class AlvexControlCenterValidator:

    ALLOWED_SEVERITIES = {

        "info",

        "warning",

        "error",

        "critical"

    }

    RESERVED_KEYS = {

        "secret_key",

        "jwt_secret",

        "password",

        "database_url",

        "api_key",

        "private_key"

    }

    def validate_event(self, request):

        if request.severity not in (
            self.ALLOWED_SEVERITIES
        ):

            raise HTTPException(
                status_code=400,
                detail="Invalid event severity."
            )

        if len(request.metadata) > 20:

            raise HTTPException(
                status_code=400,
                detail="Too many metadata fields."
            )

        encoded = json.dumps(
            request.metadata,
            ensure_ascii=False,
            default=str
        )

        if len(encoded) > 5000:

            raise HTTPException(
                status_code=400,
                detail="Event metadata is too large."
            )

        return True

    def validate_configuration(self, request):

        key = request.config_key.lower()

        for reserved in self.RESERVED_KEYS:

            if reserved in key:

                raise HTTPException(
                    status_code=400,
                    detail="Sensitive configuration keys are forbidden."
                )

        encoded = json.dumps(
            request.config_value,
            ensure_ascii=False
        )

        if len(encoded) > 10000:

            raise HTTPException(
                status_code=400,
                detail="Configuration value is too large."
            )

        return True


alvex_control_center_validator = (
    AlvexControlCenterValidator()
)


# ------------------------------------------------------------
# 5. EVENT REPOSITORY
# ------------------------------------------------------------

class AlvexControlCenterEventRepository:

    def create(
        self,
        db,
        actor_user_id,
        request
    ):

        alvex_control_center_validator.validate_event(
            request
        )

        event = AlvexControlCenterEvent(

            event_id=str(uuid.uuid4()),

            actor_user_id=actor_user_id,

            event_type=request.event_type,

            severity=request.severity,

            description=request.description,

            component=request.component,

            metadata_json=json.dumps(
                request.metadata,
                ensure_ascii=False,
                default=str
            )

        )

        db.add(event)

        db.commit()

        db.refresh(event)

        return event

    def list_events(
        self,
        db,
        limit=50,
        severity=None
    ):

        query = db.query(
            AlvexControlCenterEvent
        )

        if severity:

            query = query.filter(
                AlvexControlCenterEvent.severity
                == severity
            )

        return (
            query.order_by(
                AlvexControlCenterEvent.created_at.desc()
            )
            .limit(limit)
            .all()
        )

    def count_by_severity(self, db):

        from sqlalchemy import func

        rows = (
            db.query(
                AlvexControlCenterEvent.severity,
                func.count(AlvexControlCenterEvent.id)
            )
            .group_by(
                AlvexControlCenterEvent.severity
            )
            .all()
        )

        return {

            severity: count

            for severity, count in rows

        }


alvex_control_center_event_repository = (
    AlvexControlCenterEventRepository()
)


# ------------------------------------------------------------
# 6. CONFIGURATION REPOSITORY
# ------------------------------------------------------------

class AlvexControlCenterConfigurationRepository:

    def list(self, db):

        return (
            db.query(
                AlvexControlCenterConfiguration
            )
            .order_by(
                AlvexControlCenterConfiguration.config_key.asc()
            )
            .all()
        )

    def get(
        self,
        db,
        key
    ):

        return (
            db.query(
                AlvexControlCenterConfiguration
            )
            .filter(
                AlvexControlCenterConfiguration.config_key
                == key
            )
            .first()
        )

    def save(
        self,
        db,
        request,
        admin_id
    ):

        alvex_control_center_validator.validate_configuration(
            request
        )

        item = self.get(
            db,
            request.config_key
        )

        encoded = json.dumps(
            request.config_value,
            ensure_ascii=False
        )

        if item:

            item.config_value = encoded

            item.description = request.description

            item.updated_by = admin_id

            item.updated_at = datetime.utcnow()

        else:

            item = AlvexControlCenterConfiguration(

                config_key=request.config_key,

                config_value=encoded,

                description=request.description,

                updated_by=admin_id

            )

            db.add(item)

        db.commit()

        db.refresh(item)

        return item


alvex_control_center_configuration_repository = (
    AlvexControlCenterConfigurationRepository()
)


# ------------------------------------------------------------
# 7. COMPONENT HEALTH COLLECTOR
# ------------------------------------------------------------

class AlvexControlCenterHealthCollector:

    def check_component(
        self,
        name,
        available,
        details=None
    ):

        return {

            "component": name,

            "status": (
                "available"
                if available
                else "unavailable"
            ),

            "details": details or {}

        }

    def collect(self):

        components = []

        components.append(
            self.check_component(

                "database",

                globals().get("engine") is not None

            )
        )

        components.append(
            self.check_component(

                "ai_gateway",

                globals().get(
                    "alvex_ai_gateway"
                ) is not None

            )
        )

        components.append(
            self.check_component(

                "rag",

                globals().get(
                    "alvex_rag_service"
                ) is not None

            )
        )

        components.append(
            self.check_component(

                "agent_tools",

                globals().get(
                    "alvex_agent_tool_registry"
                ) is not None

            )
        )

        components.append(
            self.check_component(

                "smart_routing",

                globals().get(
                    "alvex_smart_routing_engine"
                ) is not None

            )
        )

        components.append(
            self.check_component(

                "conversation_memory",

                globals().get(
                    "alvex_conversation_memory_search_engine"
                ) is not None

            )
        )

        available = sum(

            1

            for item in components

            if item["status"] == "available"

        )

        return {

            "components": components,

            "available": available,

            "total": len(components),

            "health_percentage": round(

                available / max(len(components), 1) * 100,

                2

            )

        }


alvex_control_center_health_collector = (
    AlvexControlCenterHealthCollector()
)


