class AlvexControlCenterUserStatistics:

    def collect(self, db):

        total_users = (
            db.query(User).count()
        )

        active_users = (
            db.query(User)
            .filter(
                User.is_active == True
            )
            .count()
        )

        return {

            "total_users": total_users,

            "active_users": active_users,

            "inactive_users": (
                total_users - active_users
            )

        }


