@app.post(
    "/api/admin/control-center/configuration"
)
def alvex_control_center_update_configuration(
    request: AlvexControlCenterConfigurationRequest,
    db: Session = Depends(get_db),
    admin=Depends(alvex_security_admin)
):

    if not ALVEX_CONTROL_CENTER_CONFIG[
        "allow_runtime_configuration"
    ]:

        raise HTTPException(
            status_code=403,
            detail="Runtime configuration changes are disabled."
        )

    item = (
        alvex_control_center_configuration_repository.save(

            db,

            request,

            admin.id

        )
    )

    return {

        "success": True,

        "config_key": item.config_key,

        "updated_at": item.updated_at

    }


