@app.get(
    "/api/admin/control-center/statistics"
)
def alvex_control_center_statistics(
    db: Session = Depends(get_db),
    admin=Depends(alvex_security_admin)
):

    total_events = (
        db.query(
            AlvexControlCenterEvent
        ).count()
    )

    recent_events = (
        db.query(
            AlvexControlCenterEvent
        )
        .filter(
            AlvexControlCenterEvent.created_at
            >= datetime.utcnow() - timedelta(days=7)
        )
        .count()
    )

    severity_counts = (
        alvex_control_center_event_repository.count_by_severity(
            db
        )
    )

    return {

        "total_events": total_events,

        "events_last_seven_days": recent_events,

        "severity_distribution": severity_counts,

        "registered_modules": len(
            alvex_control_center_module_registry.MODULES
        )

    }


